window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["国家知识产权局"] = {"zhuanlidailirendaimabiaozhun-2":[],"zhuanlidailirendaimabiaozhun":[],"zhuanlidailishizigekaoshibanfa-2":[{"i":1,"n":"第一条","txt":"为了规范专利代理师资格考试工作，根据《中华人民共和国专利法》和《专利代理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"专利代理师资格考试（以下简称考试）是全国统一的专利代理师执业准入资格考试。"},{"i":3,"n":"第三条","txt":"国家知识产权局负责考试组织工作，制定考试政策和考务管理制度，指导省、自治区、直辖市人民政府管理专利工作的部门的考务工作，负责考试命题、专利代理师资格证书颁发、组织巡考、考试安全保密、全国范围内重大突发事件的应急处理、应试人员和考试工作人员的违规违纪行为处理等工作。 国家知识产权局成立专利代理师考试委员会。考试委员会审定考试大纲和确定考试合格分数线，其成员由国家知识产权局、国务院有关部门、专利代理行业组织的有关人员和专利代理师代表组成，主任由国家知识产权局局长担任。考试委员会办公室负责考试各项具体工作。"},{"i":4,"n":"第四条","txt":"省、自治区、直辖市人民政府管理专利工作的部门负责本行政区域内的考务工作,执行国家知识产权局制定的考试政策和考务管理制度。省、自治区、直辖市人民政府管理专利工作的部门成立考试工作领导小组, 负责本行政区域内考务组织、考试安全保密、突发事件应急处理和上报、应试人员和考试工作人员违规违纪行为处理等工作。"},{"i":5,"n":"第五条","txt":"考试每年举行一次，实行全国统一命题，命题范围以考试大纲为准。考试包括以下科目： （一）专利法律知识； （二）相关法律知识； （三）专利代理实务。"},{"i":6,"n":"第六条","txt":"考试为闭卷考试，采用计算机化考试方式。"},{"i":7,"n":"第七条","txt":"考试实行全国统一评卷。阅卷的组织协调工作由考试委员会办公室承担。"},{"i":8,"n":"第八条","txt":"应试人员在三年内全部科目考试合格的，经审核后由国家知识产权局颁发专利代理师资格证。"},{"i":9,"n":"第九条","txt":"国家知识产权局和省、自治区、直辖市人民政府管理专利工作的部门应当做好考试的保密工作。保密工作应当坚持统一领导、分级管理、逐级负责、积极防范、突出重点的原则。"},{"i":10,"n":"第十条","txt":"国家知识产权局和省、自治区、直辖市人民政府管理专利工作的部门应当及时预防和有效应对考试过程中的突发事件。突发事件应急处理工作应当遵循统一指挥、分级负责、有效控制、依法处理的原则，做到预防为主、常备不懈。"},{"i":11,"n":"第十一条","txt":"国家知识产权局和省、自治区、直辖市人民政府管理专利工作的部门依据本办法对应试人员和考试工作人员的违规违纪行为进行处理时，应当事实清楚、证据确凿，程序规范，适用规定准确。"},{"i":12,"n":"第十二条","txt":"国家知识产权局可以根据专利代理行业发展的需要，在符合条件的地区实施考试优惠政策。符合考试优惠政策的考生，由国家知识产权局颁发允许在本省、自治区、直辖市内执业的专利代理师资格证。"},{"i":13,"n":"第十三条","txt":"国家知识产权局每年在举行考试四个月前向社会发布考试有关事项公告，公布考点城市、报名程序、考试时间和资格授予等相关安排。"},{"i":14,"n":"第十四条","txt":"省、自治区、直辖市人民政府管理专利工作的部门符合规定条件的，可以向国家知识产权局申请在本行政区域内设置考点。"},{"i":15,"n":"第十五条","txt":"国家知识产权局可以委托计算机化考试服务方（以下简称考试服务方）执行部分考务工作。 考试服务方应当接受国家知识产权局和在本行政区域内设有考点的省、自治区、直辖市人民政府管理专利工作的部门（以下简称考点局）的监督和指导。"},{"i":16,"n":"第十六条","txt":"国家知识产权局向考点局指派巡考人员。巡考人员监督、协调考点局和考试服务方的考务工作，发现问题及时向国家知识产权局上报。 全部科目考试结束后，巡考人员应当将考点局回收的考场情况记录表复印件、违规情况报告单和相关资料带回，交至考试委员会办公室。"},{"i":17,"n":"第十七条","txt":"考点局监督和指导考试服务方落实本地区考站和考场，组织对本地区考站和考场情况进行检查，监督和指导考试服务方承办考务工作，并应当在考试前召开监考职责说明会。 考点局应当指派考站负责人。"},{"i":18,"n":"第十八条","txt":"考点局应当监督和指导考试服务方按照集中、便利的原则选择考场。考场应当符合下列要求： （一）消防设施齐全、疏散通道畅通、安静、通风良好、光线充足； （二）硬件、软件和网络配置符合规定； （三）具备暂时存放考生随身携带物品的区域或者设施。"},{"i":19,"n":"第十九条","txt":"考点局应当在每个考站设置考务办公室，作为处理考试相关事务的场所，并根据需要安排、配备保卫和医务人员，协助维护考试秩序，提供医疗救助服务。"},{"i":20,"n":"第二十条","txt":"考试工作人员应当具有较高政治素质，遵守考试纪律，熟悉考试业务，工作认真负责。有配偶或者直系亲属参加当年考试的，应当主动回避。"},{"i":21,"n":"第二十一条","txt":"符合以下条件的中国公民，可以报名参加考试： （一）具有完全民事行为能力； （二）取得国家承认的理工科大专以上学历，并获得毕业证书或者学位证书。 香港特别行政区、澳门特别行政区永久性居民中的中国公民和台湾地区居民可以报名参加考试。"},{"i":22,"n":"第二十二条","txt":"从事专利审查等工作满七年的中国公民，可以申请免予专利代理实务科目考试。"},{"i":23,"n":"第二十三条","txt":"有下列情形之一的，不得报名参加考试： （一）因故意犯罪受过刑事处罚，自刑罚执行完毕之日起未满三年； （二）受吊销专利代理师资格证的处罚，自处罚决定之日起未满三年。"},{"i":24,"n":"第二十四条","txt":"报名参加考试的人员，应当选择适合的考点城市之一，在规定的时间内报名。报名人员应当填写、上传下列材料，并缴纳相关费用： （一）报名表、专利代理师资格预申请表及照片； （二）有效身份证件扫描件； （三）学历或者学位证书扫描件。持香港特别行政区、澳门特别行政区、台湾地区或者国外高等学校学历学位证书报名的，须上传教育部留学服务中心的学历学位认证书扫描件； （四）专利代理师资格申请承诺书扫描件。 申请免予专利代理实务科目考试的人员报名时还应当填写、上传免试申请书，证明从事专利审查等工作情况的材料。"},{"i":25,"n":"第二十五条","txt":"国家知识产权局考试委员会办公室统一制作准考证，并发放给符合报名条件的考试报名人员。"},{"i":26,"n":"第二十六条","txt":"应试人员应当持本人准考证和与报名信息一致的有效身份证件原件，在每科考试开始前的指定时间进入考场，接受身份查验后在指定位置参加考试。"},{"i":27,"n":"第二十七条","txt":"应试人员不得携带下列物品进入考场： （一）任何书籍、期刊、笔记以及带有文字的纸张； （二）任何具有通讯、存储、录放等功能的电子产品。 应试人员携带前款所述物品或者其他与考试无关的物品的，应当在各科考试开始前交由监考人员代为保管。"},{"i":28,"n":"第二十八条","txt":"应试人员在考试期间应当严格遵守考场纪律，保持考场肃静，不得相互交谈、随意站立或者走动，不得查看或者窥视他人答题，不得传递任何信息，不得在考场内喧哗、吸烟、饮食或者有其他影响考场秩序的行为。"},{"i":29,"n":"第二十九条","txt":"考试开始30分钟后，应试人员不得进入考场。考试开始60分钟后，应试人员方可交卷离场。"},{"i":30,"n":"第三十条","txt":"应试人员入座后，不得擅自离开座位和考场。考试结束前，应试人员有特殊情况需要暂时离开考场的，应当由监考人员陪同，返回考场时应当重新接受身份查验。 应试人员因突发疾病不能继续考试的，应当立即停止考试，离开考场。"},{"i":31,"n":"第三十一条","txt":"考试期间出现考试机故障、网络故障或者供电故障等异常情况，导致应试人员无法正常考试的，应试人员应当听从监考人员的安排。 因前款所述客观原因导致应试人员答题时间出现损失的，应试人员可以当场向监考人员提出补时要求，由监考人员依据本办法第三十九条的规定予以处理。"},{"i":32,"n":"第三十二条","txt":"考试结束时，应试人员应当听从监考人员指令，立即停止考试，将草稿纸整理好放在桌面上，等候监考人员清点回收。监考人员宣布退场后，应试人员方可退出考场。应试人员离开考场后不得在考场附近逗留、喧哗。"},{"i":33,"n":"第三十三条","txt":"应试人员不得抄录、复制、传播和扩散试题内容，不得将草稿纸带出考场。"},{"i":34,"n":"第三十四条","txt":"监考人员由国家知识产权局委托的考试服务方选派，并报国家知识产权局和考点局备案。"},{"i":35,"n":"第三十五条","txt":"监考人员进入考场应当佩戴统一制发的监考标志。"},{"i":36,"n":"第三十六条","txt":"考试开始前，监考人员应当完成下列工作： （一）考试开始前90分钟，进入考场，检查考场管理机、考试服务器和考试机是否正常运行； （二）考试开始前60分钟，到考务办公室领取考务相关表格和草稿纸； （三）考试开始前40分钟，组织应试人员进入考场，核对准考证和身份证件，查验应试人员身份，要求应试人员本人在考场情况记录表中签名并拍照。对没有同时携带准考证和身份证件的应试人员，不得允许其进入考场； （四）考试开始前10分钟，向应试人员宣读或者播放应试人员考场守则； （五）考试开始前5分钟，提醒应试人员登录考试界面、核对考试相关信息，并向应试人员发放草稿纸，做好考试准备； （六）考试开始时，准时点击考场管理机上的“开始考试”按钮。"},{"i":37,"n":"第三十七条","txt":"考试期间，监考人员应当逐一核对应试人员准考证和身份证件上的照片是否与本人一致。 发现应试人员本人与证件上照片不一致的，监考人员应当在考场管理机上与报名数据库中信息进行核对。经核对确认不一致的，监考人员应当报告考站负责人，由其决定该应试人员是否能够继续参加考试，并及时做好相应处理。"},{"i":38,"n":"第三十八条","txt":"考试期间出现考试机故障、网络故障或者供电故障等异常情况，导致应试人员无法正常考试的，监考人员应当维持考场秩序，安抚应试人员，立即请技术支持人员排除故障。重要情况应当及时向考站负责人报告。考站负责人应当做好相应处理，必要时应当逐级上报国家知识产权局，并根据国家知识产权局指令进行相应处理。"},{"i":39,"n":"第三十九条","txt":"因考试机故障等客观原因导致个别应试人员答题时间出现损失，应当向应试人员补时，补时应当等于应试人员实际损失时间。补时不超过10分钟的，经监考人员批准给予补时；补时10分钟以上30分钟以下的，报经考站负责人批准，给予补时；补时超过30分钟的，应当逐级上报国家知识产权局，并根据国家知识产权局指令进行相应处理。"},{"i":40,"n":"第四十条","txt":"监考人员应当恪尽职守，不得在考场内吸烟、阅读书报、闲谈、接打电话或者有其他与监考要求无关的行为。监考人员不得对试题内容作任何解释或者暗示。应试人员对试题的正确性提出质疑的，监考人员应当及时上报，并根据国家知识产权局指令进行相应处理。"},{"i":41,"n":"第四十一条","txt":"发现应试人员违规违纪行为的，监考人员应当及时报告考站负责人并做好以下工作： （一）要求该应试人员立即停止答题； （二）收缴违规物品，填写违规物品暂扣和退还表； （三）对应试人员违规违纪行为进行认定，并在违规情况报告单中记录其违规情况和交卷时间，由两名监考人员签字确认； （四）将记录的内容告知应试人员，并要求其签字确认。应试人员拒不签字的，监考人员应当在违规情况报告单中注明； （五）在考场情况记录表中记录该应试人员姓名、准考证号、违规违纪情形等内容； （六）及时向考站负责人报告应试人员违规违纪情况，并将考务相关表格及违规物品等证据材料一并上交考站负责人。确认应试人员有抄袭作弊行为的，监考人员应当提交相关证明材料。"},{"i":42,"n":"第四十二条","txt":"考试结束后，监考人员应当清点、回收草稿纸，检查所有考试机是否交卷成功，确认成功后按照要求上传本考场考试数据。"},{"i":43,"n":"第四十三条","txt":"考试期间监考人员应当如实填写考务相关表格。应试人员退出考场后，监考人员应当将考场情况记录表、违规情况报告单、违规物品暂扣和退还表、工作程序记录表和草稿纸交考站负责人验收。"},{"i":44,"n":"第四十四条","txt":"每科考试结束后，监考人员应当清理考场并对考场进行封闭，考场钥匙由考站指定的专人管理。"},{"i":45,"n":"第四十五条","txt":"考试成绩及考试合格分数线由考试委员会办公室公布。考试成绩公布前，任何人不得擅自泄露分数情况。"},{"i":46,"n":"第四十六条","txt":"应试人员认为其考试成绩有明显异常的，可以自考试成绩公布之日起十五日内向考试委员会办公室提出书面复查申请，逾期提出的复查申请不予受理。考试成绩复查仅限于重新核对各题得分之和相加是否有误。应试人员不得自行查阅本人试卷。"},{"i":47,"n":"第四十七条","txt":"考试委员会办公室应当指定两名以上工作人员共同完成复查工作。复查结果由考试委员会办公室书面通知提出复查请求的应试人员。 复查发现分数确有错误需要予以更正的，经考试委员会办公室负责人审核同意，报考试委员会主任批准后，方可更正分数。"},{"i":48,"n":"第四十八条","txt":"国家知识产权局在考试合格分数线公布后一个月内向通过考试并经过审核的应试人员颁发专利代理师资格证。"},{"i":49,"n":"第四十九条","txt":"未启用的考试试题为机密级国家秘密，考试试题题库为秘密级国家秘密，按照《中华人民共和国保守国家秘密法》的规定管理。"},{"i":50,"n":"第五十条","txt":"命审题人员信息、试题命制工作方案、参考答案、评分标准、考试合格标准、应试人员的考试成绩和其他有关数据，属于工作秘密，未经国家知识产权局批准不得公开。"},{"i":51,"n":"第五十一条","txt":"国家知识产权局组织成立考试保密工作领导小组，负责制定考试保密管理有关工作方案，指导、检查和监督考点局的考试安全保密工作，对命审题、巡考、阅卷等相关涉密人员进行保密教育和业务培训，在发生失泄密事件时会同国家知识产权局保密委员会采取有效措施进行处置。 国家知识产权局组织成立考试突发事件应急处理领导小组，指导考点局的突发事件应急处理工作，组织处理全国范围内的重大突发事件。"},{"i":52,"n":"第五十二条","txt":"考点局应当会同同级保密工作部门成立地方考试保密工作领导小组，负责制定本行政区域内考试保密制度的具体实施方案，监督、检查保密制度的执行情况，对参与考试工作的涉密人员进行审核并向国家知识产权局备案，对相关涉密考试工作人员进行保密教育和业务培训。 考点局应当成立考试突发事件应急处理领导小组，负责制定本行政区域内的考试突发事件应急处理预案，负责突发事件的处理和上报工作。"},{"i":53,"n":"第五十三条","txt":"考试服务方接受国家知识产权局委托，执行相应部分考务工作时应当接受国家知识产权局的监督和检查，严格遵守保密法律法规、本办法及委托合同中的具体要求，并对涉及考试的相关人员进行严格管理。"},{"i":54,"n":"第五十四条","txt":"考试保密工作管理具体办法和考试应急处理具体预案由国家知识产权局制定。"},{"i":55,"n":"第五十五条","txt":"应试人员有下列情形之一的，由监考人员给予其口头警告，并责令其改正；经警告仍不改正的，监考人员应当报告考站负责人，由其决定责令违规违纪人员离开考场： （一）随身携带本办法第二十七条禁止携带的物品进入考场； （二）有本办法第二十八条禁止的行为； （三）故意损坏考试设备； （四）有其他违规违纪行为。"},{"i":56,"n":"第五十六条","txt":"应试人员有下列情形之一的，监考人员应当报告考站负责人，由其决定责令违规违纪人员离开考场，并报国家知识产权局决定给予其本场考试成绩无效的处理： （一）夹带或者查看与考试有关资料； （二）违规使用具有通讯、存储、录放等功能的电子产品； （三）抄袭他人答案或者同意、默许、帮助他人抄袭； （四）以口头、书面或者肢体语言等方式传递答题信息； （五）协助他人作弊； （六）将考试内容带出考场； （七）有其他较为严重的违规违纪行为。"},{"i":57,"n":"第五十七条","txt":"应试人员有下列情形之一的，监考人员应当报告考站负责人，由其决定责令违规违纪人员离开考场，并报国家知识产权局决定给予其当年考试成绩无效的处理： （一）与其他考场应试人员或者考场外人员串通作弊； （二）以打架斗殴等方式严重扰乱考场秩序； （三）以威胁、侮辱、殴打等方式妨碍考试工作人员履行职责； （四）有其他严重的违规违纪行为。 应试人员以及其他人员有前款规定情形，构成违反治安管理行为的，移交公安机关处理；构成犯罪的，移交司法机关处理。"},{"i":58,"n":"第五十八条","txt":"应试人员有下列情形之一的，监考人员应当报告考站负责人，由其决定责令违规违纪人员离开考场，并报国家知识产权局决定给予其当年考试成绩无效、三年不得报名参加专利代理师资格考试的处理： （一）由他人冒名代替或者代替他人参加考试； （二）参与有组织作弊情节严重； （三）有其他特别严重的违规违纪行为。 应试人员以及其他人员有前款规定情形，构成违反治安管理行为的，移交公安机关处理；构成犯罪的，移交司法机关处理。"},{"i":59,"n":"第五十九条","txt":"通过提供虚假证明材料或者以其他违法手段获得准考证并参加考试的，由国家知识产权局决定给予其当年考试成绩无效的处理。已经取得专利代理师资格证的，由国家知识产权局决定给予撤销专利代理师资格证的处理。"},{"i":60,"n":"第六十条","txt":"考试工作人员有下列行为之一的，由国家知识产权局或者考点局决定停止其参加当年考务工作，并视情节轻重给予或者建议其所在单位给予相应处理： （一）有应当回避考试工作的情形而未回避； （二）发现报名人员有提供虚假证明或者证件等行为而隐瞒不报； （三）因资料审核、考场巡检或者发放准考证等环节工作失误，致使应试人员未能如期参加考试或者使考试工作受到重大影响； （四）擅自变更考试时间、地点或者其他考试安排； （五）因未认真履行职责，造成所负责的考场秩序混乱； （六）擅自将试题等与考试有关内容带出考场或者传递给他人； （七）命题人员在保密期内从事与专利代理师考试有关的授课、答疑、辅导等活动； （八）阅卷人员在评卷中擅自更改评分标准，或者不按评分标准进行评卷； （九）偷换或者涂改应试人员答卷、考试成绩或者考场原始记录材料。"},{"i":61,"n":"第六十一条","txt":"考试工作人员有下列情形之一的，由国家知识产权局或者考点局决定停止其参加当年考务工作，并视情节轻重给予或者建议其所在单位给予相应处分；构成犯罪的，移交司法机关处理： （一）组织或者参与组织考试作弊； （二）纵容、包庇或者帮助应试人员作弊； （三）丢失、泄露、窃取未启用的考试试题、参考答案和评分标准； （四）未按规定履行职责或者有其他违规违纪行为。"},{"i":62,"n":"第六十二条","txt":"国家知识产权局依据本办法对应试人员给予本场考试成绩无效、当年考试成绩无效、三年不得报名参加专利代理师考试、撤销专利代理师资格证的处理的，应当以书面方式作出处理决定并通知本人，按照有关规定实施失信联合惩戒。 对考试工作人员违规违纪行为进行处理的，应当以书面方式作出处理决定并通知本人，并将有关证据材料存档备查。"},{"i":63,"n":"第六十三条","txt":"对于应试人员或者考试工作人员因违规违纪行为受到处理的有关情况，国家知识产权局或者考点局认为必要时可以通报其所在单位。"},{"i":64,"n":"第六十四条","txt":"应试人员对处理决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":65,"n":"第六十五条","txt":"本办法中的考站是指实施考试的学校或者机构，考场是指举行考试的机房，考试机是指应试人员考试用计算机，考试工作人员是指参与考试命审题、试卷制作、监考、巡考、阅卷和考试保密管理等相关工作的人员。"},{"i":66,"n":"第六十六条","txt":"本办法施行之前国家知识产权局颁发的专利代理人资格证书继续有效。"},{"i":67,"n":"第六十七条","txt":"本办法自2019年6月1日起施行。2008年8月25日国家知识产权局令第47号发布的《专利代理人资格考试实施办法》、第48号发布的《专利代理人资格考试考务规则》和2008年9月26日国家知识产权局令第49号发布的《专利代理人资格考试违纪行为处理办法》同时废止。"}],"zhuanlidailiguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为了规范专利代理行为，保障委托人、专利代理机构以及专利代理师的合法权益，维护专利代理行业的正常秩序，促进专利代理行业健康发展，根据《中华人民共和国专利法》《专利代理条例》以及其他有关法律、行政法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家知识产权局和省、自治区、直辖市人民政府管理专利工作的部门依法对专利代理机构和专利代理师进行管理和监督。"},{"i":3,"n":"第三条","txt":"国家知识产权局和省、自治区、直辖市人民政府管理专利工作的部门应当按照公平公正公开、依法有序、透明高效的原则对专利代理执业活动进行检查和监督。"},{"i":4,"n":"第四条","txt":"专利代理机构和专利代理师可以依法成立和参加全国性或者地方性专利代理行业组织。专利代理行业组织是社会团体，是专利代理师的自律性组织。 专利代理行业组织应当制定专利代理行业自律规范，行业自律规范不得与法律、行政法规、部门规章相抵触。专利代理机构、专利代理师应当遵守行业自律规范。"},{"i":5,"n":"第五条","txt":"专利代理机构和专利代理师执业应当遵守法律、行政法规和本办法，恪守职业道德、执业纪律，诚实守信，规范执业，提升专利代理质量，维护委托人的合法权益和专利代理行业正常秩序。"},{"i":6,"n":"第六条","txt":"国家知识产权局和省、自治区、直辖市人民政府管理专利工作的部门可以根据实际情况，通过制定政策、建立机制等措施，支持引导专利代理机构为小微企业以及无收入或者低收入的发明人、设计人提供专利代理援助服务。 鼓励专利代理行业组织和专利代理机构利用自身资源开展专利代理援助工作。"},{"i":7,"n":"第七条","txt":"国家知识产权局和省、自治区、直辖市人民政府管理专利工作的部门应当加强电子政务建设和专利代理公共信息发布，优化专利代理管理系统，方便专利代理机构、专利代理师和公众办理事务、查询信息。"},{"i":8,"n":"第八条","txt":"任何单位、个人未经许可，不得代理专利申请和宣告专利权无效等业务。"},{"i":9,"n":"第九条","txt":"专利代理机构的组织形式应当为合伙企业、有限责任公司等。合伙人、股东应当为中国公民。"},{"i":10,"n":"第十条","txt":"合伙企业形式的专利代理机构申请办理执业许可证的，应当具备下列条件： （一） 有符合法律、行政法规和本办法第十四条规定的专利代理机构名称； （二） 有书面合伙协议； （三） 有独立的经营场所； （四） 有两名以上合伙人； （五） 合伙人具有专利代理师资格证，并有两年以上专利代理师执业经历。"},{"i":11,"n":"第十一条","txt":"有限责任公司形式的专利代理机构申请办理执业许可证的，应当具备下列条件： （一） 有符合法律、行政法规和本办法第十四条规定的专利代理机构名称； （二） 有书面公司章程； （三） 有独立的经营场所； （四） 有五名以上股东； （五） 五分之四以上股东以及公司法定代表人具有专利代理师资格证，并有两年以上专利代理师执业经历。"},{"i":12,"n":"第十二条","txt":"律师事务所申请办理执业许可证的，应当具备下列条件： （一） 有独立的经营场所； （二） 有两名以上合伙人或者专职律师具有专利代理师资格证。"},{"i":13,"n":"第十三条","txt":"有下列情形之一的，不得作为专利代理机构的合伙人、股东： （一） 不具有完全民事行为能力； （二） 因故意犯罪受过刑事处罚； （三） 不能专职在专利代理机构工作； （四） 所在专利代理机构解散或者被撤销、吊销执业许可证，未妥善处理各种尚未办结的专利代理业务。 专利代理机构以欺骗、贿赂等不正当手段取得执业许可证，被依法撤销、吊销的，其合伙人、股东、法定代表人自处罚决定作出之日起三年内不得在专利代理机构新任合伙人或者股东、法定代表人。"},{"i":14,"n":"第十四条","txt":"专利代理机构只能使用一个名称。除律师事务所外，专利代理机构的名称中应当含有“专利代理”或者“知识产权代理”等字样。专利代理机构分支机构的名称由专利代理机构全名称、分支机构所在城市名称或者所在地区名称和 “分公司”或者“分所”等组成。 专利代理机构的名称不得在全国范围内与正在使用或者已经使用过的专利代理机构的名称相同或者近似。 律师事务所申请办理执业许可证的，可以使用该律师事务所的名称。"},{"i":15,"n":"第十五条","txt":"申请专利代理机构执业许可证的，应当通过专利代理管理系统向国家知识产权局提交申请书和下列申请材料： （一） 合伙企业形式的专利代理机构应当提交营业执照、合伙协议和合伙人身份证件扫描件； （二） 有限责任公司形式的专利代理机构应当提交营业执照、公司章程和股东身份证件扫描件； （三） 律师事务所应当提交律师事务所执业许可证和具有专利代理师资格证的合伙人、专职律师身份证件扫描件。 申请人应当对其申请材料实质内容的真实性负责。必要时，国家知识产权局可以要求申请人提供原件进行核实。法律、行政法规和国务院决定另有规定的除外。"},{"i":16,"n":"第十六条","txt":"申请材料不符合本办法第十五条规定的，国家知识产权局应当自收到申请材料之日起五日内一次告知申请人需要补正的全部内容，逾期未告知的，自收到申请材料之日起视为受理；申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正申请材料的，应当受理该申请。受理或者不予受理申请的，应当书面通知申请人并说明理由。 国家知识产权局应当自受理之日起十日内予以审核，对符合规定条件的，予以批准，向申请人颁发专利代理机构执业许可证；对不符合规定条件的，不予批准，书面通知申请人并说明理由。"},{"i":17,"n":"第十七条","txt":"专利代理机构名称、经营场所、合伙协议或者公司章程、合伙人或者执行事务合伙人、股东或者法定代表人发生变化的，应当自办理企业变更登记之日起三十日内向国家知识产权局申请办理变更手续；律师事务所具有专利代理师资格证的合伙人或者专职律师等事项发生变化的，应当自司法行政部门批准之日起三十日内向国家知识产权局申请办理变更手续。 国家知识产权局应当自申请受理之日起十日内作出相应决定，对符合本办法规定的事项予以变更。"},{"i":18,"n":"第十八条","txt":"专利代理机构在国家知识产权局登记的信息应当与其在市场监督管理部门或者司法行政部门的登记信息一致。"},{"i":19,"n":"第十九条","txt":"专利代理机构解散或者不再办理专利代理业务的，应当在妥善处理各种尚未办结的业务后，向国家知识产权局办理注销专利代理机构执业许可证手续。 专利代理机构注销营业执照，或者营业执照、执业许可证被撤销、吊销的，应当在营业执照注销三十日前或者接到撤销、吊销通知书之日起三十日内通知委托人解除委托合同，妥善处理尚未办结的业务，并向国家知识产权局办理注销专利代理机构执业许可证的手续。未妥善处理全部专利代理业务的，专利代理机构的合伙人、股东不得办理专利代理师执业备案变更。"},{"i":20,"n":"第二十条","txt":"专利代理机构设立分支机构办理专利代理业务的，应当具备下列条件： （一） 办理专利代理业务时间满两年； （二） 有十名以上专利代理师执业，拟设分支机构应当有一名以上专利代理师执业，并且分支机构负责人应当具有专利代理师资格证； （三） 专利代理师不得同时在两个以上的分支机构担任负责人； （四） 设立分支机构前三年内未受过专利代理行政处罚； （五） 设立分支机构时未被列入经营异常名录或者严重违法失信名单。"},{"i":21,"n":"第二十一条","txt":"专利代理机构的分支机构不得以自己的名义办理专利代理业务。专利代理机构应当对其分支机构的执业活动承担法律责任。"},{"i":22,"n":"第二十二条","txt":"专利代理机构设立、变更或者注销分支机构的，应当自完成分支机构相关企业或者司法登记手续之日起三十日内，通过专利代理管理系统向分支机构所在地的省、自治区、直辖市人民政府管理专利工作的部门进行备案。 备案应当填写备案表并上传下列材料： （一） 设立分支机构的，上传分支机构营业执照或者律师事务所分所执业许可证扫描件； （二） 变更分支机构注册事项的，上传变更以后的分支机构营业执照或者律师事务所分所执业许可证扫描件； （三） 注销分支机构的，上传妥善处理完各种事项的说明。"},{"i":23,"n":"第二十三条","txt":"专利代理机构应当建立健全质量管理、利益冲突审查、投诉处理、年度考核等执业管理制度以及人员管理、财务管理、档案管理等运营制度，对专利代理师在执业活动中遵守职业道德、执业纪律的情况进行监督。 专利代理机构的股东应当遵守国家有关规定，恪守专利代理职业道德、执业纪律，维护专利代理行业正常秩序。"},{"i":24,"n":"第二十四条","txt":"专利代理机构通过互联网平台宣传、承接专利代理业务的，应当遵守《中华人民共和国电子商务法》等相关规定。 前款所述专利代理机构应当在首页显著位置持续公示并及时更新专利代理机构执业许可证等信息。"},{"i":25,"n":"第二十五条","txt":"专利代理机构应当依法按照自愿和协商一致的原则与其聘用的专利代理师订立劳动合同。专利代理师应当受专利代理机构指派承办专利代理业务，不得自行接受委托。"},{"i":26,"n":"第二十六条","txt":"专利代理师执业应当符合下列条件： （一） 具有完全民事行为能力； （二） 取得专利代理师资格证； （三） 在专利代理机构实习满一年，但具有律师执业经历或者三年以上专利审查经历的人员除外； （四） 在专利代理机构担任合伙人、股东，或者与专利代理机构签订劳动合同； （五） 能专职从事专利代理业务。 符合前款所列全部条件之日为执业之日。"},{"i":27,"n":"第二十七条","txt":"专利代理实习人员进行专利代理业务实习，应当接受专利代理机构的指导。"},{"i":28,"n":"第二十八条","txt":"专利代理师首次执业的，应当自执业之日起三十日内通过专利代理管理系统向专利代理机构所在地的省、自治区、直辖市人民政府管理专利工作的部门进行执业备案。 备案应当填写备案表并上传下列材料： （一） 本人身份证件扫描件； （二） 与专利代理机构签订的劳动合同； （三） 实习评价材料。 专利代理师应当对其备案材料实质内容的真实性负责。必要时，省、自治区、直辖市人民政府管理专利工作的部门可以要求提供原件进行核实。"},{"i":29,"n":"第二十九条","txt":"专利代理师从专利代理机构离职的，应当妥善办理业务移交手续，并自离职之日起三十日内通过专利代理管理系统向专利代理机构所在地的省、自治区、直辖市人民政府管理专利工作的部门提交解聘证明等，进行执业备案变更。 专利代理师转换执业专利代理机构的，应当自转换执业之日起三十日内进行执业备案变更，上传与专利代理机构签订的劳动合同或者担任股东、合伙人的证明。 未在规定时间内变更执业备案的，视为逾期未主动履行备案变更手续，省、自治区、直辖市人民政府管理专利工作的部门核实后可以直接予以变更。"},{"i":30,"n":"第三十条","txt":"专利代理行业组织应当严格行业自律，组织引导专利代理机构和专利代理师依法规范执业，不断提高行业服务水平。"},{"i":31,"n":"第三十一条","txt":"国家知识产权局和省、自治区、直辖市人民政府管理专利工作的部门根据国家有关规定对专利代理行业组织进行监督和管理。"},{"i":32,"n":"第三十二条","txt":"专利代理行业组织应当依法履行下列职责： （一） 维护专利代理机构和专利代理师的合法权益； （二） 制定行业自律规范，加强行业自律，对会员实施考核、奖励和惩戒，及时向社会公布其吸纳的会员信息和对会员的惩戒情况； （三） 组织专利代理机构、专利代理师开展专利代理援助服务； （四） 组织专利代理师实习培训和执业培训，以及职业道德、执业纪律教育； （五） 按照国家有关规定推荐专利代理师担任诉讼代理人； （六） 指导专利代理机构完善管理制度，提升专利代理服务质量； （七） 指导专利代理机构开展实习工作； （八） 开展专利代理行业国际交流； （九） 其他依法应当履行的职责。"},{"i":33,"n":"第三十三条","txt":"专利代理行业组织应当建立健全非执业会员制度，鼓励取得专利代理师资格证的非执业人员参加专利代理行业组织、参与专利代理行业组织事务，加强非执业会员的培训和交流。"},{"i":34,"n":"第三十四条","txt":"国家知识产权局组织指导全国的专利代理机构年度报告、经营异常名录和严重违法失信名单的公示工作。"},{"i":35,"n":"第三十五条","txt":"专利代理机构应当按照国家有关规定提交年度报告。年度报告应当包括以下内容： （一） 专利代理机构通信地址、邮政编码、联系电话、电子邮箱等信息； （二） 执行事务合伙人或者法定代表人、合伙人或者股东、专利代理师的姓名，从业人数信息； （三） 合伙人、股东的出资额、出资时间、出资方式等信息； （四） 设立分支机构的信息； （五） 专利代理机构通过互联网等信息网络提供专利代理服务的信息网络平台名称、网址等信息； （六） 专利代理机构办理专利申请、宣告专利权无效、转让、许可、纠纷的行政处理和诉讼、质押融资等业务信息； （七） 专利代理机构资产总额、负债总额、营业总收入、主营业务收入、利润总额、净利润、纳税总额等信息； （八） 专利代理机构设立境外分支机构、其从业人员获得境外专利代理从业资质的信息； （九） 其他应当予以报告的信息。 律师事务所可仅提交其从事专利事务相关的内容。"},{"i":36,"n":"第三十六条","txt":"国家知识产权局以及省、自治区、直辖市人民政府管理专利工作的部门的工作人员应当对专利代理机构年度报告中不予公示的内容保密。"},{"i":37,"n":"第三十七条","txt":"专利代理机构有下列情形之一的，按照国家有关规定列入经营异常名录： （一） 未在规定的期限提交年度报告； （二） 取得专利代理机构执业许可证或者提交年度报告时提供虚假信息； （三） 擅自变更名称、办公场所、执行事务合伙人或者法定代表人、合伙人或者股东； （四） 分支机构设立、变更、注销未按照规定办理备案手续； （五） 不再符合执业许可条件，省、自治区、直辖市人民政府管理专利工作的部门责令其整改，期限届满仍不符合条件； （六） 专利代理机构公示信息与其在市场监督管理部门或者司法行政部门的登记信息不一致； （七） 通过登记的经营场所无法联系。"},{"i":38,"n":"第三十八条","txt":"专利代理机构有下列情形之一的，按照国家有关规定列入严重违法失信名单： （一） 被列入经营异常名录满三年仍未履行相关义务； （二） 受到责令停止承接新的专利代理业务、吊销专利代理机构执业许可证的专利代理行政处罚。"},{"i":39,"n":"第三十九条","txt":"国家知识产权局指导省、自治区、直辖市人民政府管理专利工作的部门对专利代理机构和专利代理师的执业活动情况进行检查、监督。 专利代理机构跨省设立分支机构的，其分支机构应当由分支机构所在地的省、自治区、直辖市人民政府管理专利工作的部门进行检查、监督。该专利代理机构所在地的省、自治区、直辖市人民政府管理专利工作的部门应当予以协助。"},{"i":40,"n":"第四十条","txt":"国家知识产权局和省、自治区、直辖市人民政府管理专利工作的部门应当采取书面检查、实地检查、网络监测等方式对专利代理机构和专利代理师进行检查、监督。 在检查过程中应当随机抽取检查对象，随机选派执法检查人员。发现违法违规情况的，应当及时依法处理，并向社会公布检查、处理结果。对已被列入经营异常名录或者严重违法失信名单的专利代理机构，省、自治区、直辖市人民政府管理专利工作的部门应当进行实地检查。"},{"i":41,"n":"第四十一条","txt":"省、自治区、直辖市人民政府管理专利工作的部门应当重点对下列事项进行检查、监督： （一） 专利代理机构是否符合执业许可条件； （二） 专利代理机构合伙人、股东以及法定代表人是否符合规定； （三） 专利代理机构年度报告的信息是否真实、完整、有效，与其在市场监督管理部门或者司法行政部门公示的信息是否一致； （四） 专利代理机构是否存在本办法第三十七条规定的情形； （五） 专利代理机构是否建立健全执业管理制度和运营制度等情况； （六） 专利代理师是否符合执业条件并履行备案手续； （七） 未取得专利代理执业许可的单位或者个人是否存在擅自开展专利代理业务的违法行为。"},{"i":42,"n":"第四十二条","txt":"省、自治区、直辖市人民政府管理专利工作的部门依法进行检查监督时，应当将检查监督的情况和处理结果予以记录，由检查监督人员签字后归档。 当事人应当配合省、自治区、直辖市人民政府管理专利工作的部门的检查监督，接受询问，如实提供有关情况和材料。"},{"i":43,"n":"第四十三条","txt":"国家知识产权局和省、自治区、直辖市人民政府管理专利工作的部门对存在违法违规行为的机构或者人员，可以进行警示谈话、提出意见，督促及时整改。"},{"i":44,"n":"第四十四条","txt":"国家知识产权局和省、自治区、直辖市人民政府管理专利工作的部门应当督促专利代理机构贯彻实施专利代理相关服务规范，引导专利代理机构提升服务质量。"},{"i":45,"n":"第四十五条","txt":"国家知识产权局应当及时向社会公布专利代理机构执业许可证取得、变更、注销、撤销、吊销等相关信息，以及专利代理师的执业备案、撤销、吊销等相关信息。 国家知识产权局和省、自治区、直辖市人民政府管理专利工作的部门应当及时向社会公示专利代理机构年度报告信息，列入或者移出经营异常名录、严重违法失信名单信息，行政处罚信息，以及对专利代理执业活动的检查情况。行政处罚、检查监督结果纳入国家企业信用信息公示系统向社会公布。 律师事务所、律师受到专利代理行政处罚的，应当由国家知识产权局和省、自治区、直辖市人民政府管理专利工作的部门将信息通报相关司法行政部门。"},{"i":46,"n":"第四十六条","txt":"任何单位或者个人认为专利代理机构、专利代理师的执业活动违反专利代理管理有关法律、行政法规、部门规章规定，或者认为存在擅自开展专利代理业务情形的，可以向省、自治区、直辖市人民政府管理专利工作的部门投诉和举报。 省、自治区、直辖市人民政府管理专利工作的部门收到投诉和举报后，应当依据市场监督管理投诉举报处理办法、行政处罚程序等有关规定进行调查处理。本办法另有规定的除外。"},{"i":47,"n":"第四十七条","txt":"对具有重大影响的专利代理违法违规行为，国家知识产权局可以协调或者指定有关省、自治区、直辖市人民政府管理专利工作的部门进行处理。对于专利代理违法行为的处理涉及两个以上省、自治区、直辖市人民政府管理专利工作的部门的，可以报请国家知识产权局组织协调处理。 对省、自治区、直辖市人民政府管理专利工作的部门专利代理违法行为处理工作，国家知识产权局依法进行监督。"},{"i":48,"n":"第四十八条","txt":"省、自治区、直辖市人民政府管理专利工作的部门可以依据本地实际，要求下一级人民政府管理专利工作的部门协助处理专利代理违法违规行为；也可以依法委托有实际处理能力的管理公共事务的事业组织处理专利代理违法违规行为。 委托方应当对受托方的行为进行监督和指导，并承担法律责任。"},{"i":49,"n":"第四十九条","txt":"省、自治区、直辖市人民政府管理专利工作的部门应当及时、全面、客观、公正地调查收集与案件有关的证据。可以通过下列方式对案件事实进行调查核实： （一） 要求当事人提交书面意见陈述； （二） 询问当事人； （三） 到当事人所在地进行现场调查，可以调阅有关业务案卷和档案材料； （四） 其他必要、合理的方式。"},{"i":50,"n":"第五十条","txt":"案件调查终结后，省、自治区、直辖市人民政府管理专利工作的部门认为应当对专利代理机构作出责令停止承接新的专利代理业务、吊销执业许可证，或者对专利代理师作出责令停止承办新的专利代理业务、吊销专利代理师资格证行政处罚的，应当及时报送调查结果和处罚建议，提请国家知识产权局处理。"},{"i":51,"n":"第五十一条","txt":"专利代理机构有下列情形之一的，属于《专利代理条例》第二十五条规定的“疏于管理，造成严重后果”的违法行为： （一） 因故意或者重大过失给委托人、第三人利益造成损失，或者损害社会公共利益； （二） 从事非正常专利申请行为，严重扰乱专利工作秩序； （三） 诋毁其他专利代理师、专利代理机构，以不正当手段招揽业务，存在弄虚作假行为，严重扰乱行业秩序，受到有关行政机关处罚； （四） 严重干扰专利审查工作或者专利行政执法工作正常进行； （五） 专利代理师从专利代理机构离职未妥善办理业务移交手续，造成严重后果； （六） 专利代理机构执业许可证信息与市场监督管理部门、司法行政部门的登记信息或者实际情况不一致，未按照要求整改，给社会公众造成重大误解； （七） 分支机构设立、变更、注销不符合规定的条件或者没有按照规定备案，严重损害当事人利益； （八） 默许、指派专利代理师在未经其本人撰写或者审核的专利申请等"},{"i":52,"n":"第五十二条","txt":"有下列情形之一的，属于《专利代理条例》第二十七条规定的“擅自开展专利代理业务”的违法行为： （一） 通过租用、借用等方式利用他人资质开展专利代理业务； （二） 未取得专利代理机构执业许可证或者不符合专利代理师执业条件，擅自代理专利申请、宣告专利权无效等相关业务，或者以专利代理机构、专利代理师的名义招揽业务； （三） 专利代理机构执业许可证或者专利代理师资格证被撤销或者吊销后，擅自代理专利申请、宣告专利权无效等相关业务，或者以专利代理机构、专利代理师的名义招揽业务。"},{"i":53,"n":"第五十三条","txt":"专利代理师对其签名办理的专利代理业务负责。对于非经本人办理的专利事务，专利代理师有权拒绝在相关法律文件上签名。 专利代理师因专利代理质量等原因给委托人、第三人利益造成损失或者损害社会公共利益的，省、自治区、直辖市人民政府管理专利工作的部门可以对签名的专利代理师予以警告。"},{"i":54,"n":"第五十四条","txt":"国家知识产权局按照有关规定，对专利代理领域严重失信主体开展联合惩戒。"},{"i":55,"n":"第五十五条","txt":"法律、行政法规对专利代理机构经营活动违法行为的处理另有规定的，从其规定。"},{"i":56,"n":"第五十六条","txt":"本办法由国家市场监督管理总局负责解释。"},{"i":57,"n":"第五十七条","txt":"本办法中二十日以内期限的规定是指工作日，不含法定节假日。"},{"i":58,"n":"第五十八条","txt":"本办法自2019年5月1日起施行。2015年4月30日国家知识产权局令第70号发布的《专利代理管理办法》、2002年12月12日国家知识产权局令第25号发布的《专利代理惩戒规则（试行）》同时废止。"}],"zhuanliyouxianshenchaguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为了促进产业结构优化升级，推进国家知识产权战略实施和知识产权强国建设，服务创新驱动发展，完善专利审查程序，根据《中华人民共和国专利法》和《中华人民共和国专利法实施细则》（以下简称专利法实施细则）的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"下列专利申请或者案件的优先审查适用本办法： （一）实质审查阶段的发明专利申请； （二）实用新型和外观设计专利申请； （三）发明、实用新型和外观设计专利申请的复审； （四）发明、实用新型和外观设计专利的无效宣告。 依据国家知识产权局与其他国家或者地区专利审查机构签订的双边或者多边协议开展优先审查的，按照有关规定处理，不适用本办法。"},{"i":3,"n":"第三条","txt":"有下列情形之一的专利申请或者专利复审案件，可以请求优先审查： （一）涉及节能环保、新一代信息技术、生物、高端装备制造、新能源、新材料、新能源汽车、智能制造等国家重点发展产业； （二）涉及各省级和设区的市级人民政府重点鼓励的产业； （三）涉及互联网、大数据、云计算等领域且技术或者产品更新速度快； （四）专利申请人或者复审请求人已经做好实施准备或者已经开始实施，或者有证据证明他人正在实施其发明创造； （五）就相同主题首次在中国提出专利申请又向其他国家或者地区提出申请的该中国首次申请； （六）其他对国家利益或者公共利益具有重大意义需要优先审查。"},{"i":4,"n":"第四条","txt":"有下列情形之一的无效宣告案件，可以请求优先审查： （一）针对无效宣告案件涉及的专利发生侵权纠纷，当事人已请求地方知识产权局处理、向人民法院起诉或者请求仲裁调解组织仲裁调解； （二）无效宣告案件涉及的专利对国家利益或者公共利益具有重大意义。"},{"i":5,"n":"第五条","txt":"对专利申请、专利复审案件提出优先审查请求，应当经全体申请人或者全体复审请求人同意；对无效宣告案件提出优先审查请求，应当经无效宣告请求人或者全体专利权人同意。 处理、审理涉案专利侵权纠纷的地方知识产权局、人民法院或者仲裁调解组织可以对无效宣告案件提出优先审查请求。"},{"i":6,"n":"第六条","txt":"对专利申请、专利复审案件、无效宣告案件进行优先审查的数量，由国家知识产权局根据不同专业技术领域的审查能力、上一年度专利授权量以及本年度待审案件数量等情况确定。"},{"i":7,"n":"第七条","txt":"请求优先审查的专利申请或者专利复审案件应当采用电子申请方式。"},{"i":8,"n":"第八条","txt":"申请人提出发明、实用新型、外观设计专利申请优先审查请求的，应当提交优先审查请求书、现有技术或者现有设计信息材料和相关证明文件；除本办法第三条第五项的情形外，优先审查请求书应当由国务院相关部门或者省级知识产权局签署推荐意见。 当事人提出专利复审、无效宣告案件优先审查请求的，应当提交优先审查请求书和相关证明文件；除在实质审查或者初步审查程序中已经进行优先审查的专利复审案件外，优先审查请求书应当由国务院相关部门或者省级知识产权局签署推荐意见。 地方知识产权局、人民法院、仲裁调解组织提出无效宣告案件优先审查请求的，应当提交优先审查请求书并说明理由。"},{"i":9,"n":"第九条","txt":"国家知识产权局受理和审核优先审查请求后，应当及时将审核意见通知优先审查请求人。"},{"i":10,"n":"第十条","txt":"国家知识产权局同意进行优先审查的，应当自同意之日起，在以下期限内结案： （一）发明专利申请在四十五日内发出第一次审查意见通知书，并在一年内结案； （二）实用新型和外观设计专利申请在两个月内结案； （三）专利复审案件在七个月内结案； （四）发明和实用新型专利无效宣告案件在五个月内结案，外观设计专利无效宣告案件在四个月内结案。"},{"i":11,"n":"第十一条","txt":"对于优先审查的专利申请，申请人应当尽快作出答复或者补正。申请人答复发明专利审查意见通知书的期限为通知书发文日起两个月，申请人答复实用新型和外观设计专利审查意见通知书的期限为通知书发文日起十五日。"},{"i":12,"n":"第十二条","txt":"对于优先审查的专利申请，有下列情形之一的，国家知识产权局可以停止优先审查程序，按普通程序处理，并及时通知优先审查请求人： （一）优先审查请求获得同意后，申请人根据专利法实施细则第五十一条第一、二款对申请文件提出修改； （二）申请人答复期限超过本办法第十一条规定的期限； （三）申请人提交虚假材料； （四）在审查过程中发现为非正常专利申请。"},{"i":13,"n":"第十三条","txt":"对于优先审查的专利复审或者无效宣告案件，有下列情形之一的，专利复审委员会可以停止优先审查程序，按普通程序处理，并及时通知优先审查请求人： （一）复审请求人延期答复； （二）优先审查请求获得同意后，无效宣告请求人补充证据和理由； （三）优先审查请求获得同意后，专利权人以删除以外的方式修改权利要求书； （四）专利复审或者无效宣告程序被中止； （五）案件审理依赖于其他案件的审查结论； （六）疑难案件，并经专利复审委员会主任批准。"},{"i":14,"n":"第十四条","txt":"本办法由国家知识产权局负责解释。"},{"i":15,"n":"第十五条","txt":"本办法自2017年8月1日起施行。2012年8月1日起施行的《发明专利申请优先审查管理办法》同时废止。"}],"zhuanliyouxianshenchaguanlibanfa":[{"i":1,"n":"第一条","txt":"为了促进产业结构优化升级，推进国家知识产权战略实施和知识产权强国建设，服务创新驱动发展，完善专利审查程序，根据《中华人民共和国专利法》和《中华人民共和国专利法实施细则》（以下简称专利法实施细则）的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"下列专利申请或者案件的优先审查适用本办法： （一）实质审查阶段的发明专利申请； （二）实用新型和外观设计专利申请； （三）发明、实用新型和外观设计专利申请的复审； （四）发明、实用新型和外观设计专利的无效宣告。 依据国家知识产权局与其他国家或者地区专利审查机构签订的双边或者多边协议开展优先审查的，按照有关规定处理，不适用本办法。"},{"i":3,"n":"第三条","txt":"有下列情形之一的专利申请或者专利复审案件，可以请求优先审查： （一）涉及节能环保、新一代信息技术、生物、高端装备制造、新能源、新材料、新能源汽车、智能制造等国家重点发展产业； （二）涉及各省级和设区的市级人民政府重点鼓励的产业； （三）涉及互联网、大数据、云计算等领域且技术或者产品更新速度快； （四）专利申请人或者复审请求人已经做好实施准备或者已经开始实施，或者有证据证明他人正在实施其发明创造； （五）就相同主题首次在中国提出专利申请又向其他国家或者地区提出申请的该中国首次申请； （六）其他对国家利益或者公共利益具有重大意义需要优先审查。"},{"i":4,"n":"第四条","txt":"有下列情形之一的无效宣告案件，可以请求优先审查： （一）针对无效宣告案件涉及的专利发生侵权纠纷，当事人已请求地方知识产权局处理、向人民法院起诉或者请求仲裁调解组织仲裁调解； （二）无效宣告案件涉及的专利对国家利益或者公共利益具有重大意义。"},{"i":5,"n":"第五条","txt":"对专利申请、专利复审案件提出优先审查请求，应当经全体申请人或者全体复审请求人同意；对无效宣告案件提出优先审查请求，应当经无效宣告请求人或者全体专利权人同意。 处理、审理涉案专利侵权纠纷的地方知识产权局、人民法院或者仲裁调解组织可以对无效宣告案件提出优先审查请求。"},{"i":6,"n":"第六条","txt":"对专利申请、专利复审案件、无效宣告案件进行优先审查的数量，由国家知识产权局根据不同专业技术领域的审查能力、上一年度专利授权量以及本年度待审案件数量等情况确定。"},{"i":7,"n":"第七条","txt":"请求优先审查的专利申请或者专利复审案件应当采用电子申请方式。"},{"i":8,"n":"第八条","txt":"申请人提出发明、实用新型、外观设计专利申请优先审查请求的，应当提交优先审查请求书、现有技术或者现有设计信息材料和相关证明文件；除本办法第三条第五项的情形外，优先审查请求书应当由国务院相关部门或者省级知识产权局签署推荐意见。 当事人提出专利复审、无效宣告案件优先审查请求的，应当提交优先审查请求书和相关证明文件；除在实质审查或者初步审查程序中已经进行优先审查的专利复审案件外，优先审查请求书应当由国务院相关部门或者省级知识产权局签署推荐意见。 地方知识产权局、人民法院、仲裁调解组织提出无效宣告案件优先审查请求的，应当提交优先审查请求书并说明理由。"},{"i":9,"n":"第九条","txt":"国家知识产权局受理和审核优先审查请求后，应当及时将审核意见通知优先审查请求人。"},{"i":10,"n":"第十条","txt":"国家知识产权局同意进行优先审查的，应当自同意之日起，在以下期限内结案： （一）发明专利申请在四十五日内发出第一次审查意见通知书，并在一年内结案； （二）实用新型和外观设计专利申请在两个月内结案； （三）专利复审案件在七个月内结案； （四）发明和实用新型专利无效宣告案件在五个月内结案，外观设计专利无效宣告案件在四个月内结案。"},{"i":11,"n":"第十一条","txt":"对于优先审查的专利申请，申请人应当尽快作出答复或者补正。申请人答复发明专利审查意见通知书的期限为通知书发文日起两个月，申请人答复实用新型和外观设计专利审查意见通知书的期限为通知书发文日起十五日。"},{"i":12,"n":"第十二条","txt":"对于优先审查的专利申请，有下列情形之一的，国家知识产权局可以停止优先审查程序，按普通程序处理，并及时通知优先审查请求人： （一）优先审查请求获得同意后，申请人根据专利法实施细则第五十一条第一、二款对申请文件提出修改； （二）申请人答复期限超过本办法第十一条规定的期限； （三）申请人提交虚假材料； （四）在审查过程中发现为非正常专利申请。"},{"i":13,"n":"第十三条","txt":"对于优先审查的专利复审或者无效宣告案件，有下列情形之一的，专利复审委员会可以停止优先审查程序，按普通程序处理，并及时通知优先审查请求人： （一）复审请求人延期答复； （二）优先审查请求获得同意后，无效宣告请求人补充证据和理由； （三）优先审查请求获得同意后，专利权人以删除以外的方式修改权利要求书； （四）专利复审或者无效宣告程序被中止； （五）案件审理依赖于其他案件的审查结论； （六）疑难案件，并经专利复审委员会主任批准。"},{"i":14,"n":"第十四条","txt":"本办法由国家知识产权局负责解释。"},{"i":15,"n":"第十五条","txt":"本办法自2017年8月1日起施行。2012年8月1日起施行的《发明专利申请优先审查管理办法》同时废止。"}],"zhuanlishishiqiangzhixukebanfa-2":[{"i":1,"n":"第一条","txt":"为了规范实施发明专利或者实用新型专利的强制许可（以下简称强制许可）的给予、费用裁决和终止程序，根据《中华人民共和国专利法》（以下简称专利法）、《中华人民共和国专利法实施细则》及有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"国家知识产权局负责受理和审查强制许可请求、强制许可使用费裁决请求和终止强制许可请求并作出决定。"},{"i":3,"n":"第三条","txt":"请求给予强制许可、请求裁决强制许可使用费和请求终止强制许可，应当使用中文以书面形式办理。 依照本办法提交的各种证件、证明文件是外文的，国家知识产权局认为必要时，可以要求当事人在指定期限内附送中文译文；期满未附送的，视为未提交该证件、证明文件。"},{"i":4,"n":"第四条","txt":"在中国没有经常居所或者营业所的外国人、外国企业或者外国其他组织办理强制许可事务的，应当委托依法设立的专利代理机构办理。 当事人委托专利代理机构办理强制许可事务的，应当提交委托书，写明委托权限。一方当事人有两个以上且未委托专利代理机构的，除另有声明外，以提交的书面文件中指明的第一当事人为该方代表人。"},{"i":5,"n":"第五条","txt":"专利权人自专利权被授予之日起满3年，且自提出专利申请之日起满4年，无正当理由未实施或者未充分实施其专利的，具备实施条件的单位或者个人可以根据专利法第四十八条第一项的规定，请求给予强制许可。 专利权人行使专利权的行为被依法认定为垄断行为的，为消除或者减少该行为对竞争产生的不利影响，具备实施条件的单位或者个人可以根据专利法第四十八条第二项的规定，请求给予强制许可。"},{"i":6,"n":"第六条","txt":"在国家出现紧急状态或者非常情况时，或者为了公共利益的目的，国务院有关主管部门可以根据专利法第四十九条的规定，建议国家知识产权局给予其指定的具备实施条件的单位强制许可。"},{"i":7,"n":"第七条","txt":"为了公共健康目的，具备实施条件的单位可以根据专利法第五十条的规定，请求给予制造取得专利权的药品并将其出口到下列国家或者地区的强制许可： （一）最不发达国家或者地区； （二）依照有关国际条约通知世界贸易组织表明希望作为进口方的该组织的发达成员或者发展中成员。"},{"i":8,"n":"第八条","txt":"一项取得专利权的发明或者实用新型比前已经取得专利权的发明或者实用新型具有显著经济意义的重大技术进步，其实施又有赖于前一发明或者实用新型的实施的，该专利权人可以根据专利法第五十一条的规定请求给予实施前一专利的强制许可。国家知识产权局给予实施前一专利的强制许可的，前一专利权人也可以请求给予实施后一专利的强制许可。"},{"i":9,"n":"第九条","txt":"请求给予强制许可的，应当提交强制许可请求书，写明下列各项： （一）请求人的姓名或者名称、地址、邮政编码、联系人及电话； （二）请求人的国籍或者注册的国家或者地区； （三）请求给予强制许可的发明专利或者实用新型专利的名称、专利号、申请日、授权公告日，以及专利权人的姓名或者名称； （四）请求给予强制许可的理由和事实、期限； （五）请求人委托专利代理机构的，受托机构的名称、机构代码以及该机构指定的代理人的姓名、执业证号码、联系电话； （六）请求人的签字或者盖章；委托专利代理机构的，还应当有该机构的盖章； （七）附加文件清单； （八）其他需要注明的事项。 请求书及其附加文件应当一式两份。"},{"i":10,"n":"第十条","txt":"强制许可请求涉及两个或者两个以上的专利权人的，请求人应当按专利权人的数量提交请求书及其附加文件副本。"},{"i":11,"n":"第十一条","txt":"根据专利法第四十八条第一项或者第五十一条的规定请求给予强制许可的，请求人应当提供证据，证明其以合理的条件请求专利权人许可其实施专利，但未能在合理的时间内获得许可。 根据专利法第四十八条第二项的规定请求给予强制许可的，请求人应当提交已经生效的司法机关或者反垄断执法机构依法将专利权人行使专利权的行为认定为垄断行为的判决或者决定。"},{"i":12,"n":"第十二条","txt":"国务院有关主管部门根据专利法第四十九条建议给予强制许可的，应当指明下列各项： （一）国家出现紧急状态或者非常情况，或者为了公共利益目的需要给予强制许可； （二）建议给予强制许可的发明专利或者实用新型专利的名称、专利号、申请日、授权公告日，以及专利权人的姓名或者名称； （三）建议给予强制许可的期限； （四）指定的具备实施条件的单位名称、地址、邮政编码、联系人及电话； （五）其他需要注明的事项。"},{"i":13,"n":"第十三条","txt":"根据专利法第五十条的规定请求给予强制许可的，请求人应当提供进口方及其所需药品和给予强制许可的有关信息。"},{"i":14,"n":"第十四条","txt":"强制许可请求有下列情形之一的，不予受理并通知请求人： （一） 请求给予强制许可的发明专利或者实用新型专利的专利号不明确或者难以确定； （二）请求文件未使用中文； （三）明显不具备请求强制许可的理由； （四） 请求给予强制许可的专利权已经终止或者被宣告无效。"},{"i":15,"n":"第十五条","txt":"请求文件不符合本办法第四条、第九条、第十条规定的，请求人应当自收到通知之日起15日内进行补正。期满未补正的，该请求视为未提出。"},{"i":16,"n":"第十六条","txt":"国家知识产权局受理强制许可请求的，应当及时将请求书副本送交专利权人。除另有指定的外，专利权人应当自收到通知之日起15日内陈述意见；期满未答复的，不影响国家知识产权局作出决定。"},{"i":17,"n":"第十七条","txt":"国家知识产权局应当对请求人陈述的理由、提供的信息和提交的有关证明文件以及专利权人陈述的意见进行审查；需要实地核查的，应当指派两名以上工作人员实地核查。"},{"i":18,"n":"第十八条","txt":"请求人或者专利权人要求听证的，由国家知识产权局组织听证。 国家知识产权局应当在举行听证7日前通知请求人、专利权人和其他利害关系人。 除涉及国家秘密、商业秘密或者个人隐私外，听证公开进行。 举行听证时，请求人、专利权人和其他利害关系人可以进行申辩和质证。 举行听证时应当制作听证笔录，交听证参加人员确认无误后签字或者盖章。 根据专利法第四十九条或者第五十条的规定建议或者请求给予强制许可的，不适用听证程序。"},{"i":19,"n":"第十九条","txt":"请求人在国家知识产权局作出决定前撤回其请求的，强制许可请求的审查程序终止。 在国家知识产权局作出决定前，请求人与专利权人订立了专利实施许可合同的，应当及时通知国家知识产权局，并撤回其强制许可请求。"},{"i":20,"n":"第二十条","txt":"经审查认为强制许可请求有下列情形之一的，国家知识产权局应当作出驳回强制许可请求的决定： （一）请求人不符合本办法第四条、第五条、第七条或者第八条的规定； （二）请求给予强制许可的理由不符合专利法第四十八条、第五十条或者第五十一条的规定； （三）强制许可请求涉及的发明创造是半导体技术的，其理由不符合专利法第五十二条的规定； （四）强制许可请求不符合本办法第十一条或者第十三条的规定； （五）请求人陈述的理由、提供的信息或者提交的有关证明文件不充分或者不真实。 国家知识产权局在作出驳回强制许可请求的决定前，应当通知请求人拟作出的决定及其理由。除另有指定的外，请求人可以自收到通知之日起15日内陈述意见。"},{"i":21,"n":"第二十一条","txt":"经审查认为请求给予强制许可的理由成立的，国家知识产权局应当作出给予强制许可的决定。在作出给予强制许可的决定前，应当通知请求人和专利权人拟作出的决定及其理由。除另有指定的外，双方当事人可以自收到通知之日起15日内陈述意见。 国家知识产权局根据专利法第四十九条作出给予强制许可的决定前，应当通知专利权人拟作出的决定及其理由。"},{"i":22,"n":"第二十二条","txt":"给予强制许可的决定应当写明下列各项： （一）取得强制许可的单位或者个人的名称或者姓名、地址； （二）被给予强制许可的发明专利或者实用新型专利的名称、专利号、申请日及授权公告日； （三）给予强制许可的范围和期限； （四）决定的理由、事实和法律依据； （五）国家知识产权局的印章及负责人签字； （六）决定的日期； （七）其他有关事项。 给予强制许可的决定应当自作出之日起5日内通知请求人和专利权人。"},{"i":23,"n":"第二十三条","txt":"国家知识产权局根据专利法第五十条作出给予强制许可的决定的，还应当在该决定中明确下列要求： （一）依据强制许可制造的药品数量不得超过进口方所需的数量，并且必须全部出口到该进口方； （二）依据强制许可制造的药品应当采用特定的标签或者标记明确注明该药品是依据强制许可而制造的；在可行并且不会对药品价格产生显著影响的情况下，应当对药品本身采用特殊的颜色或者形状，或者对药品采用特殊的包装； （三）药品装运前，取得强制许可的单位应当在其网站或者世界贸易组织的有关网站上发布运往进口方的药品数量以及本条第二项所述的药品识别特征等信息。"},{"i":24,"n":"第二十四条","txt":"国家知识产权局根据专利法第五十条作出给予强制许可的决定的，由国务院有关主管部门将下列信息通报世界贸易组织： （一）取得强制许可的单位的名称和地址； （二）出口药品的名称和数量； （三）进口方； （四）强制许可的期限； （五）本办法第二十三条第三项所述网址。"},{"i":25,"n":"第二十五条","txt":"请求裁决强制许可使用费的，应当提交强制许可使用费裁决请求书，写明下列各项： （一）请求人的姓名或者名称、地址； （二）请求人的国籍或者注册的国家或者地区； （三）给予强制许可的决定的文号； （四）被请求人的姓名或者名称、地址； （五）请求裁决强制许可使用费的理由； （六）请求人委托专利代理机构的，受托机构的名称、机构代码以及该机构指定的代理人的姓名、执业证号码、联系电话； （七）请求人的签字或者盖章；委托专利代理机构的，还应当有该机构的盖章； （八）附加文件清单； （九）其他需要注明的事项。 请求书及其附加文件应当一式两份。"},{"i":26,"n":"第二十六条","txt":"强制许可使用费裁决请求有下列情形之一的，不予受理并通知请求人： （一）给予强制许可的决定尚未作出； （二）请求人不是专利权人或者取得强制许可的单位或者个人； （三）双方尚未进行协商或者经协商已经达成协议。"},{"i":27,"n":"第二十七条","txt":"国家知识产权局受理强制许可使用费裁决请求的，应当及时将请求书副本送交对方当事人。除另有指定的外，对方当事人应当自收到通知之日起15日内陈述意见；期满未答复的，不影响国家知识产权局作出决定。 强制许可使用费裁决过程中，双方当事人可以提交书面意见。国家知识产权局可以根据案情需要听取双方当事人的口头意见。"},{"i":28,"n":"第二十八条","txt":"请求人在国家知识产权局作出决定前撤回其裁决请求的，裁决程序终止。"},{"i":29,"n":"第二十九条","txt":"国家知识产权局应当自收到请求书之日起3个月内作出强制许可使用费的裁决决定。"},{"i":30,"n":"第三十条","txt":"强制许可使用费裁决决定应当写明下列各项： （一）取得强制许可的单位或者个人的名称或者姓名、地址； （二）被给予强制许可的发明专利或者实用新型专利的名称、专利号、申请日及授权公告日； （三）裁决的内容及其理由； （四）国家知识产权局的印章及负责人签字； （五）决定的日期； （六）其他有关事项。 强制许可使用费裁决决定应当自作出之日起5日内通知双方当事人。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，强制许可自动终止： （一）给予强制许可的决定规定的强制许可期限届满； （二）被给予强制许可的发明专利或者实用新型专利终止或者被宣告无效。"},{"i":32,"n":"第三十二条","txt":"给予强制许可的决定中规定的强制许可期限届满前，强制许可的理由消除并不再发生的，专利权人可以请求国家知识产权局作出终止强制许可的决定。 请求终止强制许可的，应当提交终止强制许可请求书，写明下列各项： （一）专利权人的姓名或者名称、地址； （二）专利权人的国籍或者注册的国家或者地区； （三）请求终止的给予强制许可决定的文号； （四）请求终止强制许可的理由和事实； （五）专利权人委托专利代理机构的，受托机构的名称、机构代码以及该机构指定的代理人的姓名、执业证号码、联系电话； （六）专利权人的签字或者盖章；委托专利代理机构的，还应当有该机构的盖章； （七）附加文件清单； （八）其他需要注明的事项。 请求书及其附加文件应当一式两份。"},{"i":33,"n":"第三十三条","txt":"终止强制许可的请求有下列情形之一的，不予受理并通知请求人： （一）请求人不是被给予强制许可的发明专利或者实用新型专利的专利权人； （二）未写明请求终止的给予强制许可决定的文号； （三）请求文件未使用中文； （四）明显不具备终止强制许可的理由。"},{"i":34,"n":"第三十四条","txt":"请求文件不符合本办法第三十二条规定的，请求人应当自收到通知之日起15日内进行补正。期满未补正的，该请求视为未提出。"},{"i":35,"n":"第三十五条","txt":"国家知识产权局受理终止强制许可请求的，应当及时将请求书副本送交取得强制许可的单位或者个人。除另有指定的外，取得强制许可的单位或者个人应当自收到通知之日起15日内陈述意见；期满未答复的，不影响国家知识产权局作出决定。"},{"i":36,"n":"第三十六条","txt":"国家知识产权局应当对专利权人陈述的理由和提交的有关证明文件以及取得强制许可的单位或者个人陈述的意见进行审查；需要实地核查的，应当指派两名以上工作人员实地核查。"},{"i":37,"n":"第三十七条","txt":"专利权人在国家知识产权局作出决定前撤回其请求的，相关程序终止。"},{"i":38,"n":"第三十八条","txt":"经审查认为请求终止强制许可的理由不成立的，国家知识产权局应当作出驳回终止强制许可请求的决定。在作出驳回终止强制许可请求的决定前，应当通知专利权人拟作出的决定及其理由。除另有指定的外，专利权人可以自收到通知之日起15日内陈述意见。"},{"i":39,"n":"第三十九条","txt":"经审查认为请求终止强制许可的理由成立的，国家知识产权局应当作出终止强制许可的决定。在作出终止强制许可的决定前，应当通知取得强制许可的单位或者个人拟作出的决定及其理由。除另有指定的外，取得强制许可的单位或者个人可以自收到通知之日起15日内陈述意见。 终止强制许可的决定应当写明下列各项： （一）专利权人的姓名或者名称、地址； （二）取得强制许可的单位或者个人的名称或者姓名、地址； （三）被给予强制许可的发明专利或者实用新型专利的名称、专利号、申请日及授权公告日； （四）给予强制许可的决定的文号； （五）决定的事实和法律依据； （六）国家知识产权局的印章及负责人签字； （七）决定的日期； （八）其他有关事项。 终止强制许可的决定应当自作出之日起5日内通知专利权人和取得强制许可的单位或者个人。"},{"i":40,"n":"第四十条","txt":"已经生效的给予强制许可的决定和终止强制许可的决定，以及强制许可自动终止的，应当在专利登记簿上登记并在专利公报上公告。"},{"i":41,"n":"第四十一条","txt":"当事人对国家知识产权局关于强制许可的决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":42,"n":"第四十二条","txt":"本办法由国家知识产权局负责解释。"},{"i":43,"n":"第四十三条","txt":"本办法自2012年5月1日起施行。2003年6月13日国家知识产权局令第三十一号发布的《专利实施强制许可办法》和2005年11月29日国家知识产权局令第三十七号发布的《涉及公共健康问题的专利实施强制许可办法》同时废止。"}],"zhuanlishishiqiangzhixukebanfa":[{"i":1,"n":"第一条","txt":"为了规范实施发明专利或者实用新型专利的强制许可（以下简称强制许可）的给予、费用裁决和终止程序，根据《中华人民共和国专利法》（以下简称专利法）、《中华人民共和国专利法实施细则》及有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"国家知识产权局负责受理和审查强制许可请求、强制许可使用费裁决请求和终止强制许可请求并作出决定。"},{"i":3,"n":"第三条","txt":"请求给予强制许可、请求裁决强制许可使用费和请求终止强制许可，应当使用中文以书面形式办理。 依照本办法提交的各种证件、证明文件是外文的，国家知识产权局认为必要时，可以要求当事人在指定期限内附送中文译文；期满未附送的，视为未提交该证件、证明文件。"},{"i":4,"n":"第四条","txt":"在中国没有经常居所或者营业所的外国人、外国企业或者外国其他组织办理强制许可事务的，应当委托依法设立的专利代理机构办理。 当事人委托专利代理机构办理强制许可事务的，应当提交委托书，写明委托权限。一方当事人有两个以上且未委托专利代理机构的，除另有声明外，以提交的书面文件中指明的第一当事人为该方代表人。"},{"i":5,"n":"第五条","txt":"专利权人自专利权被授予之日起满3年，且自提出专利申请之日起满4年，无正当理由未实施或者未充分实施其专利的，具备实施条件的单位或者个人可以根据专利法第四十八条第一项的规定，请求给予强制许可。 专利权人行使专利权的行为被依法认定为垄断行为的，为消除或者减少该行为对竞争产生的不利影响，具备实施条件的单位或者个人可以根据专利法第四十八条第二项的规定，请求给予强制许可。"},{"i":6,"n":"第六条","txt":"在国家出现紧急状态或者非常情况时，或者为了公共利益的目的，国务院有关主管部门可以根据专利法第四十九条的规定，建议国家知识产权局给予其指定的具备实施条件的单位强制许可。"},{"i":7,"n":"第七条","txt":"为了公共健康目的，具备实施条件的单位可以根据专利法第五十条的规定，请求给予制造取得专利权的药品并将其出口到下列国家或者地区的强制许可： （一）最不发达国家或者地区； （二）依照有关国际条约通知世界贸易组织表明希望作为进口方的该组织的发达成员或者发展中成员。"},{"i":8,"n":"第八条","txt":"一项取得专利权的发明或者实用新型比前已经取得专利权的发明或者实用新型具有显著经济意义的重大技术进步，其实施又有赖于前一发明或者实用新型的实施的，该专利权人可以根据专利法第五十一条的规定请求给予实施前一专利的强制许可。国家知识产权局给予实施前一专利的强制许可的，前一专利权人也可以请求给予实施后一专利的强制许可。"},{"i":9,"n":"第九条","txt":"请求给予强制许可的，应当提交强制许可请求书，写明下列各项： （一）请求人的姓名或者名称、地址、邮政编码、联系人及电话； （二）请求人的国籍或者注册的国家或者地区； （三）请求给予强制许可的发明专利或者实用新型专利的名称、专利号、申请日、授权公告日，以及专利权人的姓名或者名称； （四）请求给予强制许可的理由和事实、期限； （五）请求人委托专利代理机构的，受托机构的名称、机构代码以及该机构指定的代理人的姓名、执业证号码、联系电话； （六）请求人的签字或者盖章；委托专利代理机构的，还应当有该机构的盖章； （七）附加文件清单； （八）其他需要注明的事项。 请求书及其附加文件应当一式两份。"},{"i":10,"n":"第十条","txt":"强制许可请求涉及两个或者两个以上的专利权人的，请求人应当按专利权人的数量提交请求书及其附加文件副本。"},{"i":11,"n":"第十一条","txt":"根据专利法第四十八条第一项或者第五十一条的规定请求给予强制许可的，请求人应当提供证据，证明其以合理的条件请求专利权人许可其实施专利，但未能在合理的时间内获得许可。 根据专利法第四十八条第二项的规定请求给予强制许可的，请求人应当提交已经生效的司法机关或者反垄断执法机构依法将专利权人行使专利权的行为认定为垄断行为的判决或者决定。"},{"i":12,"n":"第十二条","txt":"国务院有关主管部门根据专利法第四十九条建议给予强制许可的，应当指明下列各项： （一）国家出现紧急状态或者非常情况，或者为了公共利益目的需要给予强制许可； （二）建议给予强制许可的发明专利或者实用新型专利的名称、专利号、申请日、授权公告日，以及专利权人的姓名或者名称； （三）建议给予强制许可的期限； （四）指定的具备实施条件的单位名称、地址、邮政编码、联系人及电话； （五）其他需要注明的事项。"},{"i":13,"n":"第十三条","txt":"根据专利法第五十条的规定请求给予强制许可的，请求人应当提供进口方及其所需药品和给予强制许可的有关信息。"},{"i":14,"n":"第十四条","txt":"强制许可请求有下列情形之一的，不予受理并通知请求人： （一） 请求给予强制许可的发明专利或者实用新型专利的专利号不明确或者难以确定； （二）请求文件未使用中文； （三）明显不具备请求强制许可的理由； （四） 请求给予强制许可的专利权已经终止或者被宣告无效。"},{"i":15,"n":"第十五条","txt":"请求文件不符合本办法第四条、第九条、第十条规定的，请求人应当自收到通知之日起15日内进行补正。期满未补正的，该请求视为未提出。"},{"i":16,"n":"第十六条","txt":"国家知识产权局受理强制许可请求的，应当及时将请求书副本送交专利权人。除另有指定的外，专利权人应当自收到通知之日起15日内陈述意见；期满未答复的，不影响国家知识产权局作出决定。"},{"i":17,"n":"第十七条","txt":"国家知识产权局应当对请求人陈述的理由、提供的信息和提交的有关证明文件以及专利权人陈述的意见进行审查；需要实地核查的，应当指派两名以上工作人员实地核查。"},{"i":18,"n":"第十八条","txt":"请求人或者专利权人要求听证的，由国家知识产权局组织听证。 国家知识产权局应当在举行听证7日前通知请求人、专利权人和其他利害关系人。 除涉及国家秘密、商业秘密或者个人隐私外，听证公开进行。 举行听证时，请求人、专利权人和其他利害关系人可以进行申辩和质证。 举行听证时应当制作听证笔录，交听证参加人员确认无误后签字或者盖章。 根据专利法第四十九条或者第五十条的规定建议或者请求给予强制许可的，不适用听证程序。"},{"i":19,"n":"第十九条","txt":"请求人在国家知识产权局作出决定前撤回其请求的，强制许可请求的审查程序终止。 在国家知识产权局作出决定前，请求人与专利权人订立了专利实施许可合同的，应当及时通知国家知识产权局，并撤回其强制许可请求。"},{"i":20,"n":"第二十条","txt":"经审查认为强制许可请求有下列情形之一的，国家知识产权局应当作出驳回强制许可请求的决定： （一）请求人不符合本办法第四条、第五条、第七条或者第八条的规定； （二）请求给予强制许可的理由不符合专利法第四十八条、第五十条或者第五十一条的规定； （三）强制许可请求涉及的发明创造是半导体技术的，其理由不符合专利法第五十二条的规定； （四）强制许可请求不符合本办法第十一条或者第十三条的规定； （五）请求人陈述的理由、提供的信息或者提交的有关证明文件不充分或者不真实。 国家知识产权局在作出驳回强制许可请求的决定前，应当通知请求人拟作出的决定及其理由。除另有指定的外，请求人可以自收到通知之日起15日内陈述意见。"},{"i":21,"n":"第二十一条","txt":"经审查认为请求给予强制许可的理由成立的，国家知识产权局应当作出给予强制许可的决定。在作出给予强制许可的决定前，应当通知请求人和专利权人拟作出的决定及其理由。除另有指定的外，双方当事人可以自收到通知之日起15日内陈述意见。 国家知识产权局根据专利法第四十九条作出给予强制许可的决定前，应当通知专利权人拟作出的决定及其理由。"},{"i":22,"n":"第二十二条","txt":"给予强制许可的决定应当写明下列各项： （一）取得强制许可的单位或者个人的名称或者姓名、地址； （二）被给予强制许可的发明专利或者实用新型专利的名称、专利号、申请日及授权公告日； （三）给予强制许可的范围和期限； （四）决定的理由、事实和法律依据； （五）国家知识产权局的印章及负责人签字； （六）决定的日期； （七）其他有关事项。 给予强制许可的决定应当自作出之日起5日内通知请求人和专利权人。"},{"i":23,"n":"第二十三条","txt":"国家知识产权局根据专利法第五十条作出给予强制许可的决定的，还应当在该决定中明确下列要求： （一）依据强制许可制造的药品数量不得超过进口方所需的数量，并且必须全部出口到该进口方； （二）依据强制许可制造的药品应当采用特定的标签或者标记明确注明该药品是依据强制许可而制造的；在可行并且不会对药品价格产生显著影响的情况下，应当对药品本身采用特殊的颜色或者形状，或者对药品采用特殊的包装； （三）药品装运前，取得强制许可的单位应当在其网站或者世界贸易组织的有关网站上发布运往进口方的药品数量以及本条第二项所述的药品识别特征等信息。"},{"i":24,"n":"第二十四条","txt":"国家知识产权局根据专利法第五十条作出给予强制许可的决定的，由国务院有关主管部门将下列信息通报世界贸易组织： （一）取得强制许可的单位的名称和地址； （二）出口药品的名称和数量； （三）进口方； （四）强制许可的期限； （五）本办法第二十三条第三项所述网址。"},{"i":25,"n":"第二十五条","txt":"请求裁决强制许可使用费的，应当提交强制许可使用费裁决请求书，写明下列各项： （一）请求人的姓名或者名称、地址； （二）请求人的国籍或者注册的国家或者地区； （三）给予强制许可的决定的文号； （四）被请求人的姓名或者名称、地址； （五）请求裁决强制许可使用费的理由； （六）请求人委托专利代理机构的，受托机构的名称、机构代码以及该机构指定的代理人的姓名、执业证号码、联系电话； （七）请求人的签字或者盖章；委托专利代理机构的，还应当有该机构的盖章； （八）附加文件清单； （九）其他需要注明的事项。 请求书及其附加文件应当一式两份。"},{"i":26,"n":"第二十六条","txt":"强制许可使用费裁决请求有下列情形之一的，不予受理并通知请求人： （一）给予强制许可的决定尚未作出； （二）请求人不是专利权人或者取得强制许可的单位或者个人； （三）双方尚未进行协商或者经协商已经达成协议。"},{"i":27,"n":"第二十七条","txt":"国家知识产权局受理强制许可使用费裁决请求的，应当及时将请求书副本送交对方当事人。除另有指定的外，对方当事人应当自收到通知之日起15日内陈述意见；期满未答复的，不影响国家知识产权局作出决定。 强制许可使用费裁决过程中，双方当事人可以提交书面意见。国家知识产权局可以根据案情需要听取双方当事人的口头意见。"},{"i":28,"n":"第二十八条","txt":"请求人在国家知识产权局作出决定前撤回其裁决请求的，裁决程序终止。"},{"i":29,"n":"第二十九条","txt":"国家知识产权局应当自收到请求书之日起3个月内作出强制许可使用费的裁决决定。"},{"i":30,"n":"第三十条","txt":"强制许可使用费裁决决定应当写明下列各项： （一）取得强制许可的单位或者个人的名称或者姓名、地址； （二）被给予强制许可的发明专利或者实用新型专利的名称、专利号、申请日及授权公告日； （三）裁决的内容及其理由； （四）国家知识产权局的印章及负责人签字； （五）决定的日期； （六）其他有关事项。 强制许可使用费裁决决定应当自作出之日起5日内通知双方当事人。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，强制许可自动终止： （一）给予强制许可的决定规定的强制许可期限届满； （二）被给予强制许可的发明专利或者实用新型专利终止或者被宣告无效。"},{"i":32,"n":"第三十二条","txt":"给予强制许可的决定中规定的强制许可期限届满前，强制许可的理由消除并不再发生的，专利权人可以请求国家知识产权局作出终止强制许可的决定。 请求终止强制许可的，应当提交终止强制许可请求书，写明下列各项： （一）专利权人的姓名或者名称、地址； （二）专利权人的国籍或者注册的国家或者地区； （三）请求终止的给予强制许可决定的文号； （四）请求终止强制许可的理由和事实； （五）专利权人委托专利代理机构的，受托机构的名称、机构代码以及该机构指定的代理人的姓名、执业证号码、联系电话； （六）专利权人的签字或者盖章；委托专利代理机构的，还应当有该机构的盖章； （七）附加文件清单； （八）其他需要注明的事项。 请求书及其附加文件应当一式两份。"},{"i":33,"n":"第三十三条","txt":"终止强制许可的请求有下列情形之一的，不予受理并通知请求人： （一）请求人不是被给予强制许可的发明专利或者实用新型专利的专利权人； （二）未写明请求终止的给予强制许可决定的文号； （三）请求文件未使用中文； （四）明显不具备终止强制许可的理由。"},{"i":34,"n":"第三十四条","txt":"请求文件不符合本办法第三十二条规定的，请求人应当自收到通知之日起15日内进行补正。期满未补正的，该请求视为未提出。"},{"i":35,"n":"第三十五条","txt":"国家知识产权局受理终止强制许可请求的，应当及时将请求书副本送交取得强制许可的单位或者个人。除另有指定的外，取得强制许可的单位或者个人应当自收到通知之日起15日内陈述意见；期满未答复的，不影响国家知识产权局作出决定。"},{"i":36,"n":"第三十六条","txt":"国家知识产权局应当对专利权人陈述的理由和提交的有关证明文件以及取得强制许可的单位或者个人陈述的意见进行审查；需要实地核查的，应当指派两名以上工作人员实地核查。"},{"i":37,"n":"第三十七条","txt":"专利权人在国家知识产权局作出决定前撤回其请求的，相关程序终止。"},{"i":38,"n":"第三十八条","txt":"经审查认为请求终止强制许可的理由不成立的，国家知识产权局应当作出驳回终止强制许可请求的决定。在作出驳回终止强制许可请求的决定前，应当通知专利权人拟作出的决定及其理由。除另有指定的外，专利权人可以自收到通知之日起15日内陈述意见。"},{"i":39,"n":"第三十九条","txt":"经审查认为请求终止强制许可的理由成立的，国家知识产权局应当作出终止强制许可的决定。在作出终止强制许可的决定前，应当通知取得强制许可的单位或者个人拟作出的决定及其理由。除另有指定的外，取得强制许可的单位或者个人可以自收到通知之日起15日内陈述意见。 终止强制许可的决定应当写明下列各项： （一）专利权人的姓名或者名称、地址； （二）取得强制许可的单位或者个人的名称或者姓名、地址； （三）被给予强制许可的发明专利或者实用新型专利的名称、专利号、申请日及授权公告日； （四）给予强制许可的决定的文号； （五）决定的事实和法律依据； （六）国家知识产权局的印章及负责人签字； （七）决定的日期； （八）其他有关事项。 终止强制许可的决定应当自作出之日起5日内通知专利权人和取得强制许可的单位或者个人。"},{"i":40,"n":"第四十条","txt":"已经生效的给予强制许可的决定和终止强制许可的决定，以及强制许可自动终止的，应当在专利登记簿上登记并在专利公报上公告。"},{"i":41,"n":"第四十一条","txt":"当事人对国家知识产权局关于强制许可的决定不服的，可以依法申请行政复议或者提起行政诉讼。"},{"i":42,"n":"第四十二条","txt":"本办法由国家知识产权局负责解释。"},{"i":43,"n":"第四十三条","txt":"本办法自2012年5月1日起施行。2003年6月13日国家知识产权局令第三十一号发布的《专利实施强制许可办法》和2005年11月29日国家知识产权局令第三十七号发布的《涉及公共健康问题的专利实施强制许可办法》同时废止。"}],"zhuanlishishixukehetongbeianbanfa-2":[{"i":1,"n":"第一条","txt":"为了切实保护专利权，规范专利实施许可行为，促进专利权的运用，根据《中华人民共和国专利法》、《中华人民共和国合同法》和相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"国家知识产权局负责全国专利实施许可合同的备案工作。"},{"i":3,"n":"第三条","txt":"专利实施许可的许可人应当是合法的专利权人或者其他权利人。 以共有的专利权订立专利实施许可合同的，除全体共有人另有约定或者《中华人民共和国专利法》另有规定的外，应当取得其他共有人的同意。"},{"i":4,"n":"第四条","txt":"申请备案的专利实施许可合同应当以书面形式订立。 订立专利实施许可合同可以使用国家知识产权局统一制订的合同范本；采用其他合同文本的，应当符合《中华人民共和国合同法》的规定。"},{"i":5,"n":"第五条","txt":"当事人应当自专利实施许可合同生效之日起3个月内办理备案手续。"},{"i":6,"n":"第六条","txt":"在中国没有经常居所或者营业所的外国人、外国企业或者外国其他组织办理备案相关手续的，应当委托依法设立的专利代理机构办理。 中国单位或者个人办理备案相关手续的，可以委托依法设立的专利代理机构办理。"},{"i":7,"n":"第七条","txt":"当事人可以通过邮寄、直接送交或者国家知识产权局规定的其他方式办理专利实施许可合同备案相关手续。"},{"i":8,"n":"第八条","txt":"申请专利实施许可合同备案的，应当提交下列文件： （一）许可人或者其委托的专利代理机构签字或者盖章的专利实施许可合同备案申请表； （二）专利实施许可合同； （三）双方当事人的身份证明； （四）委托专利代理机构的，注明委托权限的委托书； （五）其他需要提供的材料。"},{"i":9,"n":"第九条","txt":"当事人提交的专利实施许可合同应当包括以下内容： （一）当事人的姓名或者名称、地址； （二）专利权项数以及每项专利权的名称、专利号、申请日、授权公告日； （三）实施许可的种类和期限。"},{"i":10,"n":"第十条","txt":"除身份证明外，当事人提交的其他各种文件应当使用中文。身份证明是外文的，当事人应当附送中文译文；未附送的，视为未提交。"},{"i":11,"n":"第十一条","txt":"国家知识产权局自收到备案申请之日起7个工作日内进行审查并决定是否予以备案。"},{"i":12,"n":"第十二条","txt":"备案申请经审查合格的，国家知识产权局应当向当事人出具《专利实施许可合同备案证明》。 备案申请有下列情形之一的，不予备案，并向当事人发送《专利实施许可合同不予备案通知书》： （一）专利权已经终止或者被宣告无效的； （二）许可人不是专利登记簿记载的专利权人或者有权授予许可的其他权利人的； （三）专利实施许可合同不符合本办法第九条规定的； （四）实施许可的期限超过专利权有效期的； （五）共有专利权人违反法律规定或者约定订立专利实施许可合同的； （六）专利权处于年费缴纳滞纳期的； （七）因专利权的归属发生纠纷或者人民法院裁定对专利权采取保全措施，专利权的有关程序被中止的； （八）同一专利实施许可合同重复申请备案的； （九）专利权被质押的，但经质权人同意的除外； （十）与已经备案的专利实施许可合同冲突的； （十一）其他不应当予以备案的情形。"},{"i":13,"n":"第十三条","txt":"专利实施许可合同备案后，国家知识产权局发现备案申请存在本办法第十二条第二款所列情形并且尚未消除的，应当撤销专利实施许可合同备案，并向当事人发出《撤销专利实施许可合同备案通知书》。"},{"i":14,"n":"第十四条","txt":"专利实施许可合同备案的有关内容由国家知识产权局在专利登记簿上登记，并在专利公报上公告以下内容：许可人、被许可人、主分类号、专利号、申请日、授权公告日、实施许可的种类和期限、备案日期。 专利实施许可合同备案后变更、注销以及撤销的，国家知识产权局予以相应登记和公告。"},{"i":15,"n":"第十五条","txt":"国家知识产权局建立专利实施许可合同备案数据库。公众可以查询专利实施许可合同备案的法律状态。"},{"i":16,"n":"第十六条","txt":"当事人延长实施许可的期限的，应当在原实施许可的期限届满前2个月内，持变更协议、备案证明和其他有关文件向国家知识产权局办理备案变更手续。 变更专利实施许可合同其他内容的，参照前款规定办理。"},{"i":17,"n":"第十七条","txt":"实施许可的期限届满或者提前解除专利实施许可合同的，当事人应当在期限届满或者订立解除协议后30日内持备案证明、解除协议和其他有关文件向国家知识产权局办理备案注销手续。"},{"i":18,"n":"第十八条","txt":"经备案的专利实施许可合同涉及的专利权被宣告无效或者在期限届满前终止的，当事人应当及时办理备案注销手续。"},{"i":19,"n":"第十九条","txt":"经备案的专利实施许可合同的种类、期限、许可使用费计算方法或者数额等，可以作为管理专利工作的部门对侵权赔偿数额进行调解的参照。"},{"i":20,"n":"第二十条","txt":"当事人以专利申请实施许可合同申请备案的，参照本办法执行。 申请备案时，专利申请被驳回、撤回或者视为撤回的，不予备案。"},{"i":21,"n":"第二十一条","txt":"当事人以专利申请实施许可合同申请备案的，专利申请被批准授予专利权后，当事人应当及时将专利申请实施许可合同名称及有关条款作相应变更；专利申请被驳回、撤回或者视为撤回的，当事人应当及时办理备案注销手续。"},{"i":22,"n":"第二十二条","txt":"本办法自2011年8月1日起施行。2001年12月17日国家知识产权局令第十八号发布的《专利实施许可合同备案管理办法》同时废止。"}],"zhuanlishishixukehetongbeianbanfa":[{"i":1,"n":"第一条","txt":"为了切实保护专利权，规范专利实施许可行为，促进专利权的运用，根据《中华人民共和国专利法》、《中华人民共和国合同法》和相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"国家知识产权局负责全国专利实施许可合同的备案工作。"},{"i":3,"n":"第三条","txt":"专利实施许可的许可人应当是合法的专利权人或者其他权利人。 以共有的专利权订立专利实施许可合同的，除全体共有人另有约定或者《中华人民共和国专利法》另有规定的外，应当取得其他共有人的同意。"},{"i":4,"n":"第四条","txt":"申请备案的专利实施许可合同应当以书面形式订立。 订立专利实施许可合同可以使用国家知识产权局统一制订的合同范本；采用其他合同文本的，应当符合《中华人民共和国合同法》的规定。"},{"i":5,"n":"第五条","txt":"当事人应当自专利实施许可合同生效之日起3个月内办理备案手续。"},{"i":6,"n":"第六条","txt":"在中国没有经常居所或者营业所的外国人、外国企业或者外国其他组织办理备案相关手续的，应当委托依法设立的专利代理机构办理。 中国单位或者个人办理备案相关手续的，可以委托依法设立的专利代理机构办理。"},{"i":7,"n":"第七条","txt":"当事人可以通过邮寄、直接送交或者国家知识产权局规定的其他方式办理专利实施许可合同备案相关手续。"},{"i":8,"n":"第八条","txt":"申请专利实施许可合同备案的，应当提交下列文件： （一）许可人或者其委托的专利代理机构签字或者盖章的专利实施许可合同备案申请表； （二）专利实施许可合同； （三）双方当事人的身份证明； （四）委托专利代理机构的，注明委托权限的委托书； （五）其他需要提供的材料。"},{"i":9,"n":"第九条","txt":"当事人提交的专利实施许可合同应当包括以下内容： （一）当事人的姓名或者名称、地址； （二）专利权项数以及每项专利权的名称、专利号、申请日、授权公告日； （三）实施许可的种类和期限。"},{"i":10,"n":"第十条","txt":"除身份证明外，当事人提交的其他各种文件应当使用中文。身份证明是外文的，当事人应当附送中文译文；未附送的，视为未提交。"},{"i":11,"n":"第十一条","txt":"国家知识产权局自收到备案申请之日起7个工作日内进行审查并决定是否予以备案。"},{"i":12,"n":"第十二条","txt":"备案申请经审查合格的，国家知识产权局应当向当事人出具《专利实施许可合同备案证明》。 备案申请有下列情形之一的，不予备案，并向当事人发送《专利实施许可合同不予备案通知书》： （一）专利权已经终止或者被宣告无效的； （二）许可人不是专利登记簿记载的专利权人或者有权授予许可的其他权利人的； （三）专利实施许可合同不符合本办法第九条规定的； （四）实施许可的期限超过专利权有效期的； （五）共有专利权人违反法律规定或者约定订立专利实施许可合同的； （六）专利权处于年费缴纳滞纳期的； （七）因专利权的归属发生纠纷或者人民法院裁定对专利权采取保全措施，专利权的有关程序被中止的； （八）同一专利实施许可合同重复申请备案的； （九）专利权被质押的，但经质权人同意的除外； （十）与已经备案的专利实施许可合同冲突的； （十一）其他不应当予以备案的情形。"},{"i":13,"n":"第十三条","txt":"专利实施许可合同备案后，国家知识产权局发现备案申请存在本办法第十二条第二款所列情形并且尚未消除的，应当撤销专利实施许可合同备案，并向当事人发出《撤销专利实施许可合同备案通知书》。"},{"i":14,"n":"第十四条","txt":"专利实施许可合同备案的有关内容由国家知识产权局在专利登记簿上登记，并在专利公报上公告以下内容：许可人、被许可人、主分类号、专利号、申请日、授权公告日、实施许可的种类和期限、备案日期。 专利实施许可合同备案后变更、注销以及撤销的，国家知识产权局予以相应登记和公告。"},{"i":15,"n":"第十五条","txt":"国家知识产权局建立专利实施许可合同备案数据库。公众可以查询专利实施许可合同备案的法律状态。"},{"i":16,"n":"第十六条","txt":"当事人延长实施许可的期限的，应当在原实施许可的期限届满前2个月内，持变更协议、备案证明和其他有关文件向国家知识产权局办理备案变更手续。 变更专利实施许可合同其他内容的，参照前款规定办理。"},{"i":17,"n":"第十七条","txt":"实施许可的期限届满或者提前解除专利实施许可合同的，当事人应当在期限届满或者订立解除协议后30日内持备案证明、解除协议和其他有关文件向国家知识产权局办理备案注销手续。"},{"i":18,"n":"第十八条","txt":"经备案的专利实施许可合同涉及的专利权被宣告无效或者在期限届满前终止的，当事人应当及时办理备案注销手续。"},{"i":19,"n":"第十九条","txt":"经备案的专利实施许可合同的种类、期限、许可使用费计算方法或者数额等，可以作为管理专利工作的部门对侵权赔偿数额进行调解的参照。"},{"i":20,"n":"第二十条","txt":"当事人以专利申请实施许可合同申请备案的，参照本办法执行。 申请备案时，专利申请被驳回、撤回或者视为撤回的，不予备案。"},{"i":21,"n":"第二十一条","txt":"当事人以专利申请实施许可合同申请备案的，专利申请被批准授予专利权后，当事人应当及时将专利申请实施许可合同名称及有关条款作相应变更；专利申请被驳回、撤回或者视为撤回的，当事人应当及时办理备案注销手续。"},{"i":22,"n":"第二十二条","txt":"本办法自2011年8月1日起施行。2001年12月17日国家知识产权局令第十八号发布的《专利实施许可合同备案管理办法》同时废止。"}],"zhuanlishenchazhinan":[],"zhuanlishujuyuansubiaozhundi1bufenguanyuyongxmlchu017387":[],"zhuanlishujuyuansubiaozhundi2bufenguanyuyongxmlchub20900":[],"zhuanliquanzhiyadengjibanfa":[{"i":1,"n":"第一条","txt":"为了促进专利权的运用和资金融通，保障债权的实现，规范专利权质押登记，根据《中华人民共和国物权法》、《中华人民共和国担保法》、《中华人民共和国专利法》及有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国家知识产权局负责专利权质押登记工作。"},{"i":3,"n":"第三条","txt":"以专利权出质的，出质人与质权人应当订立书面质押合同。 质押合同可以是单独订立的合同，也可以是主合同中的担保条款。"},{"i":4,"n":"第四条","txt":"以共有的专利权出质的，除全体共有人另有约定的以外，应当取得其他共有人的同意。"},{"i":5,"n":"第五条","txt":"在中国没有经常居所或者营业所的外国人、外国企业或者外国其他组织办理专利权质押登记手续的，应当委托依法设立的专利代理机构办理。 中国单位或者个人办理专利权质押登记手续的，可以委托依法设立的专利代理机构办理。"},{"i":6,"n":"第六条","txt":"当事人可以通过邮寄、直接送交等方式办理专利权质押登记相关手续。"},{"i":7,"n":"第七条","txt":"申请专利权质押登记的，当事人应当向国家知识产权局提交下列文件： （一）出质人和质权人共同签字或者盖章的专利权质押登记申请表； （二）专利权质押合同； （三）双方当事人的身份证明； （四）委托代理的，注明委托权限的委托书； （五）其他需要提供的材料。 专利权经过资产评估的，当事人还应当提交资产评估报告。 除身份证明外，当事人提交的其他各种文件应当使用中文。身份证明是外文的，当事人应当附送中文译文；未附送的，视为未提交。 对于本条第一款和第二款规定的文件，当事人可以提交电子扫描件。"},{"i":8,"n":"第八条","txt":"国家知识产权局收到当事人提交的质押登记申请文件后，应当通知申请人。"},{"i":9,"n":"第九条","txt":"当事人提交的专利权质押合同应当包括以下与质押登记相关的内容： （一）当事人的姓名或者名称、地址； （二）被担保债权的种类和数额； （三）债务人履行债务的期限； （四）专利权项数以及每项专利权的名称、专利号、申请日、授权公告日； （五）质押担保的范围。"},{"i":10,"n":"第十条","txt":"除本办法第九条规定的事项外，当事人可以在专利权质押合同中约定下列事项： （一）质押期间专利权年费的缴纳； （二）质押期间专利权的转让、实施许可； （三）质押期间专利权被宣告无效或者专利权归属发生变更时的处理； （四）实现质权时，相关技术资料的交付。"},{"i":11,"n":"第十一条","txt":"国家知识产权局自收到专利权质押登记申请文件之日起7个工作日内进行审查并决定是否予以登记。"},{"i":12,"n":"第十二条","txt":"专利权质押登记申请经审查合格的，国家知识产权局在专利登记簿上予以登记，并向当事人发送《专利权质押登记通知书》。质权自国家知识产权局登记时设立。 经审查发现有下列情形之一的，国家知识产权局作出不予登记的决定，并向当事人发送《专利权质押不予登记通知书》： （一）出质人与专利登记簿记载的专利权人不一致的； （二）专利权已终止或者已被宣告无效的； （三）专利申请尚未被授予专利权的； （四）专利权处于年费缴纳滞纳期的； （五）专利权已被启动无效宣告程序的； （六）因专利权的归属发生纠纷或者人民法院裁定对专利权采取保全措施，专利权的质押手续被暂停办理的； （七）债务人履行债务的期限超过专利权有效期的； （八）质押合同约定在债务履行期届满质权人未受清偿时，专利权归质权人所有的； （九）质押合同不符合本办法第九条规定的； （十）以共有专利权出质但未取得全体共有人同意的； （十一）专利权已被申请质押登记"},{"i":13,"n":"第十三条","txt":"专利权质押期间，国家知识产权局发现质押登记存在本办法第十二条第二款所列情形并且尚未消除的，或者发现其他应当撤销专利权质押登记的情形的，应当撤销专利权质押登记，并向当事人发出《专利权质押登记撤销通知书》。 专利权质押登记被撤销的，质押登记的效力自始无效。"},{"i":14,"n":"第十四条","txt":"国家知识产权局在专利公报上公告专利权质押登记的下列内容：出质人、质权人、主分类号、专利号、授权公告日、质押登记日等。 专利权质押登记后变更、注销的，国家知识产权局予以登记和公告。"},{"i":15,"n":"第十五条","txt":"专利权质押期间，出质人未提交质权人同意其放弃该专利权的证明材料的，国家知识产权局不予办理专利权放弃手续。"},{"i":16,"n":"第十六条","txt":"专利权质押期间，出质人未提交质权人同意转让或者许可实施该专利权的证明材料的，国家知识产权局不予办理专利权转让登记手续或者专利实施合同备案手续。 出质人转让或者许可他人实施出质的专利权的，出质人所得的转让费、许可费应当向质权人提前清偿债务或者提存。"},{"i":17,"n":"第十七条","txt":"专利权质押期间，当事人的姓名或者名称、地址、被担保的主债权种类及数额或者质押担保的范围发生变更的，当事人应当自变更之日起30日内持变更协议、原《专利权质押登记通知书》和其他有关文件，向国家知识产权局办理专利权质押登记变更手续。"},{"i":18,"n":"第十八条","txt":"有下列情形之一的，当事人应当持《专利权质押登记通知书》以及相关证明文件，向国家知识产权局办理质押登记注销手续： （一）债务人按期履行债务或者出质人提前清偿所担保的债务的； （二）质权已经实现的； （三）质权人放弃质权的； （四）因主合同无效、被撤销致使质押合同无效、被撤销的； （五）法律规定质权消灭的其他情形。 国家知识产权局收到注销登记申请后，经审核，向当事人发出《专利权质押登记注销通知书》。专利权质押登记的效力自注销之日起终止。"},{"i":19,"n":"第十九条","txt":"专利权在质押期间被宣告无效或者终止的，国家知识产权局应当通知质权人。"},{"i":20,"n":"第二十条","txt":"专利权人没有按照规定缴纳已经质押的专利权的年费的，国家知识产权局应当在向专利权人发出缴费通知书的同时通知质权人。"},{"i":21,"n":"第二十一条","txt":"本办法由国家知识产权局负责解释。"},{"i":22,"n":"第二十二条","txt":"本办法自2010年10月1日起施行。1996年9月19日中华人民共和国专利局令第八号发布的《专利权质押合同登记管理暂行办法》同时废止。"}],"zhuanlibiaoshibiaozhubanfa-2":[{"i":1,"n":"第一条","txt":"为了规范专利标识的标注方式，维护正常的市场经济秩序，根据《中华人民共和国专利法》（以下简称专利法）和《中华人民共和国专利法实施细则》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"标注专利标识的，应当按照本办法予以标注。"},{"i":3,"n":"第三条","txt":"管理专利工作的部门负责在本行政区域内对标注专利标识的行为进行监督管理。"},{"i":4,"n":"第四条","txt":"在授予专利权之后的专利权有效期内，专利权人或者经专利权人同意享有专利标识标注权的被许可人可以在其专利产品、依照专利方法直接获得的产品、该产品的包装或者该产品的说明书等材料上标注专利标识。"},{"i":5,"n":"第五条","txt":"标注专利标识的，应当标明下述内容： （一）采用中文标明专利权的类别，例如中国发明专利、中国实用新型专利、中国外观设计专利； （二）国家知识产权局授予专利权的专利号。 除上述内容之外，可以附加其他文字、图形标记，但附加的文字、图形标记及其标注方式不得误导公众。"},{"i":6,"n":"第六条","txt":"在依照专利方法直接获得的产品、该产品的包装或者该产品的说明书等材料上标注专利标识的，应当采用中文标明该产品系依照专利方法所获得的产品。"},{"i":7,"n":"第七条","txt":"专利权被授予前在产品、该产品的包装或者该产品的说明书等材料上进行标注的，应当采用中文标明中国专利申请的类别、专利申请号，并标明“专利申请，尚未授权”字样。"},{"i":8,"n":"第八条","txt":"专利标识的标注不符合本办法第五条、第六条或者第七条规定的，由管理专利工作的部门责令改正。 专利标识标注不当，构成假冒专利行为的，由管理专利工作的部门依照专利法第六十三条的规定进行处罚。"},{"i":9,"n":"第九条","txt":"本办法由国家知识产权局负责解释。"},{"i":10,"n":"第十条","txt":"本办法自2012年5月1日起施行。2003年5月30日国家知识产权局令第二十九号发布的《专利标记和专利号标注方式的规定》同时废止。"}],"zhuanlibiaoshibiaozhubanfa":[{"i":1,"n":"第一条","txt":"为了规范专利标识的标注方式，维护正常的市场经济秩序，根据《中华人民共和国专利法》（以下简称专利法）和《中华人民共和国专利法实施细则》的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"标注专利标识的，应当按照本办法予以标注。"},{"i":3,"n":"第三条","txt":"管理专利工作的部门负责在本行政区域内对标注专利标识的行为进行监督管理。"},{"i":4,"n":"第四条","txt":"在授予专利权之后的专利权有效期内，专利权人或者经专利权人同意享有专利标识标注权的被许可人可以在其专利产品、依照专利方法直接获得的产品、该产品的包装或者该产品的说明书等材料上标注专利标识。"},{"i":5,"n":"第五条","txt":"标注专利标识的，应当标明下述内容： （一）采用中文标明专利权的类别，例如中国发明专利、中国实用新型专利、中国外观设计专利； （二）国家知识产权局授予专利权的专利号。 除上述内容之外，可以附加其他文字、图形标记，但附加的文字、图形标记及其标注方式不得误导公众。"},{"i":6,"n":"第六条","txt":"在依照专利方法直接获得的产品、该产品的包装或者该产品的说明书等材料上标注专利标识的，应当采用中文标明该产品系依照专利方法所获得的产品。"},{"i":7,"n":"第七条","txt":"专利权被授予前在产品、该产品的包装或者该产品的说明书等材料上进行标注的，应当采用中文标明中国专利申请的类别、专利申请号，并标明“专利申请，尚未授权”字样。"},{"i":8,"n":"第八条","txt":"专利标识的标注不符合本办法第五条、第六条或者第七条规定的，由管理专利工作的部门责令改正。 专利标识标注不当，构成假冒专利行为的，由管理专利工作的部门依照专利法第六十三条的规定进行处罚。"},{"i":9,"n":"第九条","txt":"本办法由国家知识产权局负责解释。"},{"i":10,"n":"第十条","txt":"本办法自2012年5月1日起施行。2003年5月30日国家知识产权局令第二十九号发布的《专利标记和专利号标注方式的规定》同时废止。"}],"zhuanlishenqingrenhezhuanliquanrendaimabiaozhun":[],"zhuanlishenqinghaobiaozhun-2":[],"zhuanlishenqinghaobiaozhun":[],"zhuanlixingzhengzhifabanfa-2":[{"i":1,"n":"第一条","txt":"为深入推进依法行政，规范专利行政执法行为，保护专利权人和社会公众的合法权益，维护社会主义市场经济秩序，根据《中华人民共和国专利法》、《中华人民共和国专利法实施细则》以及其他有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"管理专利工作的部门开展专利行政执法，即处理专利侵权纠纷、调解专利纠纷以及查处假冒专利行为，适用本办法。"},{"i":3,"n":"第三条","txt":"管理专利工作的部门处理专利侵权纠纷应当以事实为依据、以法律为准绳，遵循公正、及时的原则。 管理专利工作的部门调解专利纠纷，应当遵循自愿、合法的原则，在查明事实、分清是非的基础上，促使当事人相互谅解，达成调解协议。 管理专利工作的部门查处假冒专利行为，应当以事实为依据、以法律为准绳，遵循公正、公开的原则，给予的行政处罚应当与违法行为的事实、性质、情节以及社会危害程度相当。"},{"i":4,"n":"第四条","txt":"管理专利工作的部门应当加强专利行政执法力量建设，严格行政执法人员资格管理，落实行政执法责任制，规范开展专利行政执法。 专利行政执法人员（以下简称“执法人员”）应当持有国家知识产权局或者省、自治区、直辖市人民政府颁发的行政执法证件。执法人员执行公务时应当严肃着装。"},{"i":5,"n":"第五条","txt":"对有重大影响的专利侵权纠纷案件、假冒专利案件，国家知识产权局在必要时可以组织有关管理专利工作的部门处理、查处。 对于行为发生地涉及两个以上省、自治区、直辖市的重大案件，有关省、自治区、直辖市管理专利工作的部门可以报请国家知识产权局协调处理或者查处。 管理专利工作的部门开展专利行政执法遇到疑难问题的，国家知识产权局应当给予必要的指导和支持。"},{"i":6,"n":"第六条","txt":"管理专利工作的部门可以依据本地实际，委托有实际处理能力的市、县级人民政府设立的专利管理部门查处假冒专利行为、调解专利纠纷。 委托方应当对受托方查处假冒专利和调解专利纠纷的行为进行监督和指导，并承担法律责任。"},{"i":7,"n":"第七条","txt":"管理专利工作的部门指派的执法人员与当事人有直接利害关系的，应当回避，当事人有权申请其回避。当事人申请回避的，应当说明理由。 执法人员的回避，由管理专利工作部门的负责人决定。是否回避的决定作出前，被申请回避的人员应当暂停参与本案的工作。"},{"i":8,"n":"第八条","txt":"管理专利工作的部门应当加强展会和电子商务领域的行政执法，快速调解、处理展会期间和电子商务平台上的专利侵权纠纷，及时查处假冒专利行为。"},{"i":9,"n":"第九条","txt":"管理专利工作的部门应当加强行政执法信息化建设和信息共享。"},{"i":10,"n":"第十条","txt":"请求管理专利工作的部门处理专利侵权纠纷的，应当符合下列条件： （一）请求人是专利权人或者利害关系人； （二）有明确的被请求人； （三）有明确的请求事项和具体事实、理由； （四）属于受案管理专利工作的部门的受案和管辖范围； （五）当事人没有就该专利侵权纠纷向人民法院起诉。 第一项所称利害关系人包括专利实施许可合同的被许可人、专利权人的合法继承人。专利实施许可合同的被许可人中，独占实施许可合同的被许可人可以单独提出请求；排他实施许可合同的被许可人在专利权人不请求的情况下，可以单独提出请求；除合同另有约定外，普通实施许可合同的被许可人不能单独提出请求。"},{"i":11,"n":"第十一条","txt":"请求管理专利工作的部门处理专利侵权纠纷的，应当提交请求书及下列证明材料： （一）主体资格证明，即个人应当提交居民身份证或者其他有效身份证件，单位应当提交有效的营业执照或者其他主体资格证明文件副本及法定代表人或者主要负责人的身份证明； （二）专利权有效的证明，即专利登记簿副本，或者专利证书和当年缴纳专利年费的收据。 专利侵权纠纷涉及实用新型或者外观设计专利的，管理专利工作的部门可以要求请求人出具由国家知识产权局作出的专利权评价报告（实用新型专利检索报告）。 请求人应当按照被请求人的数量提供请求书副本及有关证据。"},{"i":12,"n":"第十二条","txt":"请求书应当记载以下内容： （一）请求人的姓名或者名称、地址，法定代表人或者主要负责人的姓名、职务，委托代理人的，代理人的姓名和代理机构的名称、地址； （二）被请求人的姓名或者名称、地址； （三）请求处理的事项以及事实和理由。 有关证据和证明材料可以以请求书附件的形式提交。 请求书应当由请求人签名或者盖章。"},{"i":13,"n":"第十三条","txt":"请求符合本办法第十条规定条件的，管理专利工作的部门应当在收到请求书之日起5个工作日内立案并通知请求人，同时指定3名或者3名以上单数执法人员处理该专利侵权纠纷；请求不符合本办法第十条规定条件的，管理专利工作的部门应当在收到请求书之日起5个工作日内通知请求人不予受理，并说明理由。"},{"i":14,"n":"第十四条","txt":"管理专利工作的部门应当在立案之日起5个工作日内将请求书及其附件的副本送达被请求人，要求其在收到之日起15日内提交答辩书并按照请求人的数量提供答辩书副本。被请求人逾期不提交答辩书的，不影响管理专利工作的部门进行处理。 被请求人提交答辩书的，管理专利工作的部门应当在收到之日起5个工作日内将答辩书副本送达请求人。"},{"i":15,"n":"第十五条","txt":"管理专利工作的部门处理专利侵权纠纷案件时，可以根据当事人的意愿进行调解。双方当事人达成一致的，由管理专利工作的部门制作调解协议书，加盖其公章，并由双方当事人签名或者盖章。调解不成的，应当及时作出处理决定。"},{"i":16,"n":"第十六条","txt":"管理专利工作的部门处理专利侵权纠纷，可以根据案情需要决定是否进行口头审理。管理专利工作的部门决定进行口头审理的，应当至少在口头审理3个工作日前将口头审理的时间、地点通知当事人。当事人无正当理由拒不参加的，或者未经允许中途退出的，对请求人按撤回请求处理，对被请求人按缺席处理。"},{"i":17,"n":"第十七条","txt":"管理专利工作的部门举行口头审理的，应当将口头审理的参加人和审理要点记入笔录，经核对无误后，由执法人员和参加人签名或者盖章。"},{"i":18,"n":"第十八条","txt":"专利法第五十九条第一款所称的“发明或者实用新型专利权的保护范围以其权利要求的内容为准”，是指专利权的保护范围应当以其权利要求记载的技术特征所确定的范围为准，也包括与记载的技术特征相等同的特征所确定的范围。等同特征是指与记载的技术特征以基本相同的手段，实现基本相同的功能，达到基本相同的效果，并且所属领域的普通技术人员无需经过创造性劳动就能够联想到的特征。"},{"i":19,"n":"第十九条","txt":"除达成调解协议或者请求人撤回请求之外，管理专利工作的部门处理专利侵权纠纷应当制作处理决定书，写明以下内容： （一）当事人的姓名或者名称、地址； （二）当事人陈述的事实和理由； （三）认定侵权行为是否成立的理由和依据； （四）处理决定认定侵权行为成立并需要责令侵权人立即停止侵权行为的，应当明确写明责令被请求人立即停止的侵权行为的类型、对象和范围；认定侵权行为不成立的，应当驳回请求人的请求； （五）不服处理决定提起行政诉讼的途径和期限。 处理决定书应当加盖管理专利工作的部门的公章。"},{"i":20,"n":"第二十条","txt":"管理专利工作的部门或者人民法院作出认定侵权成立并责令侵权人立即停止侵权行为的处理决定或者判决之后，被请求人就同一专利权再次作出相同类型的侵权行为，专利权人或者利害关系人请求处理的，管理专利工作的部门可以直接作出责令立即停止侵权行为的处理决定。"},{"i":21,"n":"第二十一条","txt":"管理专利工作的部门处理专利侵权纠纷，应当自立案之日起3个月内结案。案件特别复杂需要延长期限的，应当由管理专利工作的部门负责人批准。经批准延长的期限，最多不超过1个月。 案件处理过程中的公告、鉴定、中止等时间不计入前款所述案件办理期限。"},{"i":22,"n":"第二十二条","txt":"请求管理专利工作的部门调解专利纠纷的，应当提交请求书。 请求书应当记载以下内容： （一）请求人的姓名或者名称、地址，法定代表人或者主要负责人的姓名、职务，委托代理人的，代理人的姓名和代理机构的名称、地址； （二）被请求人的姓名或者名称、地址； （三）请求调解的具体事项和理由。 单独请求调解侵犯专利权赔偿数额的，应当提交有关管理专利工作的部门作出的认定侵权行为成立的处理决定书副本。"},{"i":23,"n":"第二十三条","txt":"管理专利工作的部门收到调解请求书后，应当及时将请求书副本通过寄交、直接送交或者其他方式送达被请求人，要求其在收到之日起15日内提交意见陈述书。"},{"i":24,"n":"第二十四条","txt":"被请求人提交意见陈述书并同意进行调解的，管理专利工作的部门应当在收到意见陈述书之日起5个工作日内立案，并通知请求人和被请求人进行调解的时间和地点。 被请求人逾期未提交意见陈述书，或者在意见陈述书中表示不接受调解的，管理专利工作的部门不予立案，并通知请求人。"},{"i":25,"n":"第二十五条","txt":"管理专利工作的部门调解专利纠纷可以邀请有关单位或者个人协助，被邀请的单位或者个人应当协助进行调解。"},{"i":26,"n":"第二十六条","txt":"当事人经调解达成协议的，由管理专利工作的部门制作调解协议书，加盖其公章，并由双方当事人签名或者盖章；未能达成协议的，管理专利工作的部门以撤销案件的方式结案，并通知双方当事人。"},{"i":27,"n":"第二十七条","txt":"因专利申请权或者专利权的归属纠纷请求调解的，当事人可以持管理专利工作的部门的受理通知书请求国家知识产权局中止该专利申请或者专利权的有关程序。 经调解达成协议的，当事人应当持调解协议书向国家知识产权局办理恢复手续；达不成协议的，当事人应当持管理专利工作的部门出具的撤销案件通知书向国家知识产权局办理恢复手续。自请求中止之日起满1年未请求延长中止的，国家知识产权局自行恢复有关程序。"},{"i":28,"n":"第二十八条","txt":"管理专利工作的部门发现或者接受举报、投诉发现涉嫌假冒专利行为的，应当自发现之日起5个工作日内或者收到举报、投诉之日起10个工作日内立案，并指定两名或者两名以上执法人员进行调查。"},{"i":29,"n":"第二十九条","txt":"查处假冒专利行为由行为发生地的管理专利工作的部门管辖。 管理专利工作的部门对管辖权发生争议的，由其共同的上级人民政府管理专利工作的部门指定管辖；无共同上级人民政府管理专利工作的部门的，由国家知识产权局指定管辖。"},{"i":30,"n":"第三十条","txt":"管理专利工作的部门查封、扣押涉嫌假冒专利产品的，应当经其负责人批准。查封、扣押时，应当向当事人出具有关通知书。 管理专利工作的部门查封、扣押涉嫌假冒专利产品，应当当场清点，制作笔录和清单，由当事人和执法人员签名或者盖章。当事人拒绝签名或者盖章的，由执法人员在笔录上注明。清单应当交当事人一份。"},{"i":31,"n":"第三十一条","txt":"案件调查终结，经管理专利工作的部门负责人批准，根据案件情况分别作如下处理： （一）假冒专利行为成立应当予以处罚的，依法给予行政处罚； （二）假冒专利行为轻微并已及时改正的，免予处罚； （三）假冒专利行为不成立的，依法撤销案件； （四）涉嫌犯罪的，依法移送公安机关。"},{"i":32,"n":"第三十二条","txt":"管理专利工作的部门作出行政处罚决定前，应当告知当事人作出处罚决定的事实、理由和依据，并告知当事人依法享有的权利。 管理专利工作的部门作出较大数额罚款的决定之前，应当告知当事人有要求举行听证的权利。当事人提出听证要求的，应当依法组织听证。"},{"i":33,"n":"第三十三条","txt":"当事人有权进行陈述和申辩，管理专利工作的部门不得因当事人申辩而加重行政处罚。 管理专利工作的部门对当事人提出的事实、理由和证据应当进行核实。当事人提出的事实属实、理由成立的，管理专利工作的部门应当予以采纳。"},{"i":34,"n":"第三十四条","txt":"对情节复杂或者重大违法行为给予较重的行政处罚的，应当由管理专利工作的部门负责人集体讨论决定。"},{"i":35,"n":"第三十五条","txt":"经调查，假冒专利行为成立应当予以处罚的，管理专利工作的部门应当制作处罚决定书，写明以下内容： （一）当事人的姓名或者名称、地址； （二）认定假冒专利行为成立的证据、理由和依据； （三）处罚的内容以及履行方式； （四）不服处罚决定申请行政复议和提起行政诉讼的途径和期限。 处罚决定书应当加盖管理专利工作的部门的公章。"},{"i":36,"n":"第三十六条","txt":"管理专利工作的部门查处假冒专利案件，应当自立案之日起1个月内结案。案件特别复杂需要延长期限的，应当由管理专利工作的部门负责人批准。经批准延长的期限，最多不超过15日。 案件处理过程中听证、公告等时间不计入前款所述案件办理期限。"},{"i":37,"n":"第三十七条","txt":"在专利侵权纠纷处理过程中，当事人因客观原因不能自行收集部分证据的，可以书面请求管理专利工作的部门调查取证。管理专利工作的部门根据情况决定是否调查收集有关证据。 在处理专利侵权纠纷、查处假冒专利行为过程中，管理专利工作的部门可以根据需要依职权调查收集有关证据。 执法人员调查收集有关证据时，应当向当事人或者有关人员出示其行政执法证件。当事人和有关人员应当协助、配合，如实反映情况，不得拒绝、阻挠。"},{"i":38,"n":"第三十八条","txt":"管理专利工作的部门调查收集证据可以查阅、复制与案件有关的合同、账册等有关文件；询问当事人和证人；采用测量、拍照、摄像等方式进行现场勘验。涉嫌侵犯制造方法专利权的，管理专利工作的部门可以要求被调查人进行现场演示。 管理专利工作的部门调查收集证据应当制作笔录。笔录应当由执法人员、被调查的单位或者个人签名或者盖章。被调查的单位或者个人拒绝签名或者盖章的，由执法人员在笔录上注明。"},{"i":39,"n":"第三十九条","txt":"管理专利工作的部门调查收集证据可以采取抽样取证的方式。 涉及产品专利的，可以从涉嫌侵权的产品中抽取一部分作为样品；涉及方法专利的，可以从涉嫌依照该方法直接获得的产品中抽取一部分作为样品。被抽取样品的数量应当以能够证明事实为限。 管理专利工作的部门进行抽样取证应当制作笔录和清单，写明被抽取样品的名称、特征、数量以及保存地点，由执法人员、被调查的单位或者个人签字或者盖章。被调查的单位或者个人拒绝签名或者盖章的，由执法人员在笔录上注明。清单应当交被调查人一份。"},{"i":40,"n":"第四十条","txt":"在证据可能灭失或者以后难以取得，又无法进行抽样取证的情况下，管理专利工作的部门可以进行登记保存，并在7日内作出决定。 经登记保存的证据，被调查的单位或者个人不得销毁或者转移。 管理专利工作的部门进行登记保存应当制作笔录和清单，写明被登记保存证据的名称、特征、数量以及保存地点，由执法人员、被调查的单位或者个人签名或者盖章。被调查的单位或者个人拒绝签名或者盖章的，由执法人员在笔录上注明。清单应当交被调查人一份。"},{"i":41,"n":"第四十一条","txt":"管理专利工作的部门需要委托其他管理专利工作的部门协助调查收集证据的，应当提出明确的要求。接受委托的部门应当及时、认真地协助调查收集证据，并尽快回复。"},{"i":42,"n":"第四十二条","txt":"海关对被扣留的侵权嫌疑货物进行调查，请求管理专利工作的部门提供协助的，管理专利工作的部门应当依法予以协助。 管理专利工作的部门处理涉及进出口货物的专利案件的，可以请求海关提供协助。"},{"i":43,"n":"第四十三条","txt":"管理专利工作的部门认定专利侵权行为成立，作出处理决定，责令侵权人立即停止侵权行为的，应当采取下列制止侵权行为的措施： （一）侵权人制造专利侵权产品的，责令其立即停止制造行为，销毁制造侵权产品的专用设备、模具，并且不得销售、使用尚未售出的侵权产品或者以任何其他形式将其投放市场；侵权产品难以保存的，责令侵权人销毁该产品； （二）侵权人未经专利权人许可使用专利方法的，责令侵权人立即停止使用行为，销毁实施专利方法的专用设备、模具，并且不得销售、使用尚未售出的依照专利方法所直接获得的侵权产品或者以任何其他形式将其投放市场；侵权产品难以保存的，责令侵权人销毁该产品； （三）侵权人销售专利侵权产品或者依照专利方法直接获得的侵权产品的，责令其立即停止销售行为，并且不得使用尚未售出的侵权产品或者以任何其他形式将其投放市场；尚未售出的侵权产品难以保存的，责令侵权人销毁该产品； （四）侵权人许诺销售专利侵权"},{"i":44,"n":"第四十四条","txt":"管理专利工作的部门作出认定专利侵权行为成立并责令侵权人立即停止侵权行为的处理决定后，被请求人向人民法院提起行政诉讼的，在诉讼期间不停止决定的执行。 侵权人对管理专利工作的部门作出的认定侵权行为成立的处理决定期满不起诉又不停止侵权行为的，管理专利工作的部门可以申请人民法院强制执行。"},{"i":45,"n":"第四十五条","txt":"管理专利工作的部门认定假冒专利行为成立的，应当责令行为人采取下列改正措施： （一）在未被授予专利权的产品或者其包装上标注专利标识、专利权被宣告无效后或者终止后继续在产品或者其包装上标注专利标识或者未经许可在产品或者产品包装上标注他人的专利号的，立即停止标注行为，消除尚未售出的产品或者其包装上的专利标识；产品上的专利标识难以消除的，销毁该产品或者包装； （二）销售第（一）项所述产品的，立即停止销售行为； （三）在产品说明书等材料中将未被授予专利权的技术或者设计称为专利技术或者专利设计，将专利申请称为专利，或者未经许可使用他人的专利号，使公众将所涉及的技术或者设计误认为是他人的专利技术或者专利设计的，立即停止发放该材料，销毁尚未发出的材料，并消除影响； （四）伪造或者变造专利证书、专利文件或者专利申请文件的，立即停止伪造或者变造行为，销毁伪造或者变造的专利证书、专利文件或者专利申请文件，并"},{"i":46,"n":"第四十六条","txt":"管理专利工作的部门作出认定专利侵权行为成立并责令侵权人立即停止侵权行为的决定，或者认定假冒专利行为成立并作出处罚决定的，应当自作出决定之日起20个工作日内予以公开，通过政府网站等途径及时发布执法信息。"},{"i":47,"n":"第四十七条","txt":"管理专利工作的部门认定假冒专利行为成立的，可以按照下列方式确定行为人的违法所得： （一）销售假冒专利的产品的，以产品销售价格乘以所销售产品的数量作为其违法所得； （二）订立假冒专利的合同的，以收取的费用作为其违法所得。"},{"i":48,"n":"第四十八条","txt":"管理专利工作的部门作出处罚决定后，当事人申请行政复议或者向人民法院提起行政诉讼的，在行政复议或者诉讼期间不停止决定的执行。"},{"i":49,"n":"第四十九条","txt":"假冒专利行为的行为人应当自收到处罚决定书之日起15日内，到指定的银行缴纳处罚决定书写明的罚款；到期不缴纳的，每日按罚款数额的百分之三加处罚款。"},{"i":50,"n":"第五十条","txt":"拒绝、阻碍管理专利工作的部门依法执行公务的，由公安机关根据《中华人民共和国治安管理处罚法》的规定给予处罚；情节严重构成犯罪的，由司法机关依法追究刑事责任。"},{"i":51,"n":"第五十一条","txt":"管理专利工作的部门可以通过寄交、直接送交、留置送达、公告送达或者其他方式送达有关法律文书和材料。"},{"i":52,"n":"第五十二条","txt":"本办法由国家知识产权局负责解释。"},{"i":53,"n":"第五十三条","txt":"本办法自2011年2月1日起施行。2001年12月17日国家知识产权局令第十九号发布的《专利行政执法办法》同时废止。"}],"zhuanlixingzhengzhifabanfa":[{"i":1,"n":"第一条","txt":"为深入推进依法行政，规范专利行政执法行为，保护专利权人和社会公众的合法权益，维护社会主义市场经济秩序，根据《中华人民共和国专利法》、《中华人民共和国专利法实施细则》以及其他有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"管理专利工作的部门开展专利行政执法，即处理专利侵权纠纷、调解专利纠纷以及查处假冒专利行为，适用本办法。"},{"i":3,"n":"第三条","txt":"管理专利工作的部门处理专利侵权纠纷应当以事实为依据、以法律为准绳，遵循公正、及时的原则。 管理专利工作的部门调解专利纠纷，应当遵循自愿、合法的原则，在查明事实、分清是非的基础上，促使当事人相互谅解，达成调解协议。 管理专利工作的部门查处假冒专利行为，应当以事实为依据、以法律为准绳，遵循公正、公开的原则，给予的行政处罚应当与违法行为的事实、性质、情节以及社会危害程度相当。"},{"i":4,"n":"第四条","txt":"管理专利工作的部门应当加强专利行政执法力量建设，严格行政执法人员资格管理，落实行政执法责任制，规范开展专利行政执法。 专利行政执法人员（以下简称“执法人员”）应当持有国家知识产权局或者省、自治区、直辖市人民政府颁发的行政执法证件。执法人员执行公务时应当严肃着装。"},{"i":5,"n":"第五条","txt":"对有重大影响的专利侵权纠纷案件、假冒专利案件，国家知识产权局在必要时可以组织有关管理专利工作的部门处理、查处。 对于行为发生地涉及两个以上省、自治区、直辖市的重大案件，有关省、自治区、直辖市管理专利工作的部门可以报请国家知识产权局协调处理或者查处。 管理专利工作的部门开展专利行政执法遇到疑难问题的，国家知识产权局应当给予必要的指导和支持。"},{"i":6,"n":"第六条","txt":"管理专利工作的部门可以依据本地实际，委托有实际处理能力的市、县级人民政府设立的专利管理部门查处假冒专利行为、调解专利纠纷。 委托方应当对受托方查处假冒专利和调解专利纠纷的行为进行监督和指导，并承担法律责任。"},{"i":7,"n":"第七条","txt":"管理专利工作的部门指派的执法人员与当事人有直接利害关系的，应当回避，当事人有权申请其回避。当事人申请回避的，应当说明理由。 执法人员的回避，由管理专利工作部门的负责人决定。是否回避的决定作出前，被申请回避的人员应当暂停参与本案的工作。"},{"i":8,"n":"第八条","txt":"管理专利工作的部门应当加强展会和电子商务领域的行政执法，快速调解、处理展会期间和电子商务平台上的专利侵权纠纷，及时查处假冒专利行为。"},{"i":9,"n":"第九条","txt":"管理专利工作的部门应当加强行政执法信息化建设和信息共享。"},{"i":10,"n":"第十条","txt":"请求管理专利工作的部门处理专利侵权纠纷的，应当符合下列条件： （一）请求人是专利权人或者利害关系人； （二）有明确的被请求人； （三）有明确的请求事项和具体事实、理由； （四）属于受案管理专利工作的部门的受案和管辖范围； （五）当事人没有就该专利侵权纠纷向人民法院起诉。 第一项所称利害关系人包括专利实施许可合同的被许可人、专利权人的合法继承人。专利实施许可合同的被许可人中，独占实施许可合同的被许可人可以单独提出请求；排他实施许可合同的被许可人在专利权人不请求的情况下，可以单独提出请求；除合同另有约定外，普通实施许可合同的被许可人不能单独提出请求。"},{"i":11,"n":"第十一条","txt":"请求管理专利工作的部门处理专利侵权纠纷的，应当提交请求书及下列证明材料： （一）主体资格证明，即个人应当提交居民身份证或者其他有效身份证件，单位应当提交有效的营业执照或者其他主体资格证明文件副本及法定代表人或者主要负责人的身份证明； （二）专利权有效的证明，即专利登记簿副本，或者专利证书和当年缴纳专利年费的收据。 专利侵权纠纷涉及实用新型或者外观设计专利的，管理专利工作的部门可以要求请求人出具由国家知识产权局作出的专利权评价报告（实用新型专利检索报告）。 请求人应当按照被请求人的数量提供请求书副本及有关证据。"},{"i":12,"n":"第十二条","txt":"请求书应当记载以下内容： （一）请求人的姓名或者名称、地址，法定代表人或者主要负责人的姓名、职务，委托代理人的，代理人的姓名和代理机构的名称、地址； （二）被请求人的姓名或者名称、地址； （三）请求处理的事项以及事实和理由。 有关证据和证明材料可以以请求书附件的形式提交。 请求书应当由请求人签名或者盖章。"},{"i":13,"n":"第十三条","txt":"请求符合本办法第十条规定条件的，管理专利工作的部门应当在收到请求书之日起5个工作日内立案并通知请求人，同时指定3名或者3名以上单数执法人员处理该专利侵权纠纷；请求不符合本办法第十条规定条件的，管理专利工作的部门应当在收到请求书之日起5个工作日内通知请求人不予受理，并说明理由。"},{"i":14,"n":"第十四条","txt":"管理专利工作的部门应当在立案之日起5个工作日内将请求书及其附件的副本送达被请求人，要求其在收到之日起15日内提交答辩书并按照请求人的数量提供答辩书副本。被请求人逾期不提交答辩书的，不影响管理专利工作的部门进行处理。 被请求人提交答辩书的，管理专利工作的部门应当在收到之日起5个工作日内将答辩书副本送达请求人。"},{"i":15,"n":"第十五条","txt":"管理专利工作的部门处理专利侵权纠纷案件时，可以根据当事人的意愿进行调解。双方当事人达成一致的，由管理专利工作的部门制作调解协议书，加盖其公章，并由双方当事人签名或者盖章。调解不成的，应当及时作出处理决定。"},{"i":16,"n":"第十六条","txt":"管理专利工作的部门处理专利侵权纠纷，可以根据案情需要决定是否进行口头审理。管理专利工作的部门决定进行口头审理的，应当至少在口头审理3个工作日前将口头审理的时间、地点通知当事人。当事人无正当理由拒不参加的，或者未经允许中途退出的，对请求人按撤回请求处理，对被请求人按缺席处理。"},{"i":17,"n":"第十七条","txt":"管理专利工作的部门举行口头审理的，应当将口头审理的参加人和审理要点记入笔录，经核对无误后，由执法人员和参加人签名或者盖章。"},{"i":18,"n":"第十八条","txt":"专利法第五十九条第一款所称的“发明或者实用新型专利权的保护范围以其权利要求的内容为准”，是指专利权的保护范围应当以其权利要求记载的技术特征所确定的范围为准，也包括与记载的技术特征相等同的特征所确定的范围。等同特征是指与记载的技术特征以基本相同的手段，实现基本相同的功能，达到基本相同的效果，并且所属领域的普通技术人员无需经过创造性劳动就能够联想到的特征。"},{"i":19,"n":"第十九条","txt":"除达成调解协议或者请求人撤回请求之外，管理专利工作的部门处理专利侵权纠纷应当制作处理决定书，写明以下内容： （一）当事人的姓名或者名称、地址； （二）当事人陈述的事实和理由； （三）认定侵权行为是否成立的理由和依据； （四）处理决定认定侵权行为成立并需要责令侵权人立即停止侵权行为的，应当明确写明责令被请求人立即停止的侵权行为的类型、对象和范围；认定侵权行为不成立的，应当驳回请求人的请求； （五）不服处理决定提起行政诉讼的途径和期限。 处理决定书应当加盖管理专利工作的部门的公章。"},{"i":20,"n":"第二十条","txt":"管理专利工作的部门或者人民法院作出认定侵权成立并责令侵权人立即停止侵权行为的处理决定或者判决之后，被请求人就同一专利权再次作出相同类型的侵权行为，专利权人或者利害关系人请求处理的，管理专利工作的部门可以直接作出责令立即停止侵权行为的处理决定。"},{"i":21,"n":"第二十一条","txt":"管理专利工作的部门处理专利侵权纠纷，应当自立案之日起3个月内结案。案件特别复杂需要延长期限的，应当由管理专利工作的部门负责人批准。经批准延长的期限，最多不超过1个月。 案件处理过程中的公告、鉴定、中止等时间不计入前款所述案件办理期限。"},{"i":22,"n":"第二十二条","txt":"请求管理专利工作的部门调解专利纠纷的，应当提交请求书。 请求书应当记载以下内容： （一）请求人的姓名或者名称、地址，法定代表人或者主要负责人的姓名、职务，委托代理人的，代理人的姓名和代理机构的名称、地址； （二）被请求人的姓名或者名称、地址； （三）请求调解的具体事项和理由。 单独请求调解侵犯专利权赔偿数额的，应当提交有关管理专利工作的部门作出的认定侵权行为成立的处理决定书副本。"},{"i":23,"n":"第二十三条","txt":"管理专利工作的部门收到调解请求书后，应当及时将请求书副本通过寄交、直接送交或者其他方式送达被请求人，要求其在收到之日起15日内提交意见陈述书。"},{"i":24,"n":"第二十四条","txt":"被请求人提交意见陈述书并同意进行调解的，管理专利工作的部门应当在收到意见陈述书之日起5个工作日内立案，并通知请求人和被请求人进行调解的时间和地点。 被请求人逾期未提交意见陈述书，或者在意见陈述书中表示不接受调解的，管理专利工作的部门不予立案，并通知请求人。"},{"i":25,"n":"第二十五条","txt":"管理专利工作的部门调解专利纠纷可以邀请有关单位或者个人协助，被邀请的单位或者个人应当协助进行调解。"},{"i":26,"n":"第二十六条","txt":"当事人经调解达成协议的，由管理专利工作的部门制作调解协议书，加盖其公章，并由双方当事人签名或者盖章；未能达成协议的，管理专利工作的部门以撤销案件的方式结案，并通知双方当事人。"},{"i":27,"n":"第二十七条","txt":"因专利申请权或者专利权的归属纠纷请求调解的，当事人可以持管理专利工作的部门的受理通知书请求国家知识产权局中止该专利申请或者专利权的有关程序。 经调解达成协议的，当事人应当持调解协议书向国家知识产权局办理恢复手续；达不成协议的，当事人应当持管理专利工作的部门出具的撤销案件通知书向国家知识产权局办理恢复手续。自请求中止之日起满1年未请求延长中止的，国家知识产权局自行恢复有关程序。"},{"i":28,"n":"第二十八条","txt":"管理专利工作的部门发现或者接受举报、投诉发现涉嫌假冒专利行为的，应当自发现之日起5个工作日内或者收到举报、投诉之日起10个工作日内立案，并指定两名或者两名以上执法人员进行调查。"},{"i":29,"n":"第二十九条","txt":"查处假冒专利行为由行为发生地的管理专利工作的部门管辖。 管理专利工作的部门对管辖权发生争议的，由其共同的上级人民政府管理专利工作的部门指定管辖；无共同上级人民政府管理专利工作的部门的，由国家知识产权局指定管辖。"},{"i":30,"n":"第三十条","txt":"管理专利工作的部门查封、扣押涉嫌假冒专利产品的，应当经其负责人批准。查封、扣押时，应当向当事人出具有关通知书。 管理专利工作的部门查封、扣押涉嫌假冒专利产品，应当当场清点，制作笔录和清单，由当事人和执法人员签名或者盖章。当事人拒绝签名或者盖章的，由执法人员在笔录上注明。清单应当交当事人一份。"},{"i":31,"n":"第三十一条","txt":"案件调查终结，经管理专利工作的部门负责人批准，根据案件情况分别作如下处理： （一）假冒专利行为成立应当予以处罚的，依法给予行政处罚； （二）假冒专利行为轻微并已及时改正的，免予处罚； （三）假冒专利行为不成立的，依法撤销案件； （四）涉嫌犯罪的，依法移送公安机关。"},{"i":32,"n":"第三十二条","txt":"管理专利工作的部门作出行政处罚决定前，应当告知当事人作出处罚决定的事实、理由和依据，并告知当事人依法享有的权利。 管理专利工作的部门作出较大数额罚款的决定之前，应当告知当事人有要求举行听证的权利。当事人提出听证要求的，应当依法组织听证。"},{"i":33,"n":"第三十三条","txt":"当事人有权进行陈述和申辩，管理专利工作的部门不得因当事人申辩而加重行政处罚。 管理专利工作的部门对当事人提出的事实、理由和证据应当进行核实。当事人提出的事实属实、理由成立的，管理专利工作的部门应当予以采纳。"},{"i":34,"n":"第三十四条","txt":"对情节复杂或者重大违法行为给予较重的行政处罚的，应当由管理专利工作的部门负责人集体讨论决定。"},{"i":35,"n":"第三十五条","txt":"经调查，假冒专利行为成立应当予以处罚的，管理专利工作的部门应当制作处罚决定书，写明以下内容： （一）当事人的姓名或者名称、地址； （二）认定假冒专利行为成立的证据、理由和依据； （三）处罚的内容以及履行方式； （四）不服处罚决定申请行政复议和提起行政诉讼的途径和期限。 处罚决定书应当加盖管理专利工作的部门的公章。"},{"i":36,"n":"第三十六条","txt":"管理专利工作的部门查处假冒专利案件，应当自立案之日起1个月内结案。案件特别复杂需要延长期限的，应当由管理专利工作的部门负责人批准。经批准延长的期限，最多不超过15日。 案件处理过程中听证、公告等时间不计入前款所述案件办理期限。"},{"i":37,"n":"第三十七条","txt":"在专利侵权纠纷处理过程中，当事人因客观原因不能自行收集部分证据的，可以书面请求管理专利工作的部门调查取证。管理专利工作的部门根据情况决定是否调查收集有关证据。 在处理专利侵权纠纷、查处假冒专利行为过程中，管理专利工作的部门可以根据需要依职权调查收集有关证据。 执法人员调查收集有关证据时，应当向当事人或者有关人员出示其行政执法证件。当事人和有关人员应当协助、配合，如实反映情况，不得拒绝、阻挠。"},{"i":38,"n":"第三十八条","txt":"管理专利工作的部门调查收集证据可以查阅、复制与案件有关的合同、账册等有关文件；询问当事人和证人；采用测量、拍照、摄像等方式进行现场勘验。涉嫌侵犯制造方法专利权的，管理专利工作的部门可以要求被调查人进行现场演示。 管理专利工作的部门调查收集证据应当制作笔录。笔录应当由执法人员、被调查的单位或者个人签名或者盖章。被调查的单位或者个人拒绝签名或者盖章的，由执法人员在笔录上注明。"},{"i":39,"n":"第三十九条","txt":"管理专利工作的部门调查收集证据可以采取抽样取证的方式。 涉及产品专利的，可以从涉嫌侵权的产品中抽取一部分作为样品；涉及方法专利的，可以从涉嫌依照该方法直接获得的产品中抽取一部分作为样品。被抽取样品的数量应当以能够证明事实为限。 管理专利工作的部门进行抽样取证应当制作笔录和清单，写明被抽取样品的名称、特征、数量以及保存地点，由执法人员、被调查的单位或者个人签字或者盖章。被调查的单位或者个人拒绝签名或者盖章的，由执法人员在笔录上注明。清单应当交被调查人一份。"},{"i":40,"n":"第四十条","txt":"在证据可能灭失或者以后难以取得，又无法进行抽样取证的情况下，管理专利工作的部门可以进行登记保存，并在7日内作出决定。 经登记保存的证据，被调查的单位或者个人不得销毁或者转移。 管理专利工作的部门进行登记保存应当制作笔录和清单，写明被登记保存证据的名称、特征、数量以及保存地点，由执法人员、被调查的单位或者个人签名或者盖章。被调查的单位或者个人拒绝签名或者盖章的，由执法人员在笔录上注明。清单应当交被调查人一份。"},{"i":41,"n":"第四十一条","txt":"管理专利工作的部门需要委托其他管理专利工作的部门协助调查收集证据的，应当提出明确的要求。接受委托的部门应当及时、认真地协助调查收集证据，并尽快回复。"},{"i":42,"n":"第四十二条","txt":"海关对被扣留的侵权嫌疑货物进行调查，请求管理专利工作的部门提供协助的，管理专利工作的部门应当依法予以协助。 管理专利工作的部门处理涉及进出口货物的专利案件的，可以请求海关提供协助。"},{"i":43,"n":"第四十三条","txt":"管理专利工作的部门认定专利侵权行为成立，作出处理决定，责令侵权人立即停止侵权行为的，应当采取下列制止侵权行为的措施： （一）侵权人制造专利侵权产品的，责令其立即停止制造行为，销毁制造侵权产品的专用设备、模具，并且不得销售、使用尚未售出的侵权产品或者以任何其他形式将其投放市场；侵权产品难以保存的，责令侵权人销毁该产品； （二）侵权人未经专利权人许可使用专利方法的，责令侵权人立即停止使用行为，销毁实施专利方法的专用设备、模具，并且不得销售、使用尚未售出的依照专利方法所直接获得的侵权产品或者以任何其他形式将其投放市场；侵权产品难以保存的，责令侵权人销毁该产品； （三）侵权人销售专利侵权产品或者依照专利方法直接获得的侵权产品的，责令其立即停止销售行为，并且不得使用尚未售出的侵权产品或者以任何其他形式将其投放市场；尚未售出的侵权产品难以保存的，责令侵权人销毁该产品； （四）侵权人许诺销售专利侵权"},{"i":44,"n":"第四十四条","txt":"管理专利工作的部门作出认定专利侵权行为成立并责令侵权人立即停止侵权行为的处理决定后，被请求人向人民法院提起行政诉讼的，在诉讼期间不停止决定的执行。 侵权人对管理专利工作的部门作出的认定侵权行为成立的处理决定期满不起诉又不停止侵权行为的，管理专利工作的部门可以申请人民法院强制执行。"},{"i":45,"n":"第四十五条","txt":"管理专利工作的部门认定假冒专利行为成立的，应当责令行为人采取下列改正措施： （一）在未被授予专利权的产品或者其包装上标注专利标识、专利权被宣告无效后或者终止后继续在产品或者其包装上标注专利标识或者未经许可在产品或者产品包装上标注他人的专利号的，立即停止标注行为，消除尚未售出的产品或者其包装上的专利标识；产品上的专利标识难以消除的，销毁该产品或者包装； （二）销售第（一）项所述产品的，立即停止销售行为； （三）在产品说明书等材料中将未被授予专利权的技术或者设计称为专利技术或者专利设计，将专利申请称为专利，或者未经许可使用他人的专利号，使公众将所涉及的技术或者设计误认为是他人的专利技术或者专利设计的，立即停止发放该材料，销毁尚未发出的材料，并消除影响； （四）伪造或者变造专利证书、专利文件或者专利申请文件的，立即停止伪造或者变造行为，销毁伪造或者变造的专利证书、专利文件或者专利申请文件，并"},{"i":46,"n":"第四十六条","txt":"管理专利工作的部门作出认定专利侵权行为成立并责令侵权人立即停止侵权行为的决定，或者认定假冒专利行为成立并作出处罚决定的，应当自作出决定之日起20个工作日内予以公开，通过政府网站等途径及时发布执法信息。"},{"i":47,"n":"第四十七条","txt":"管理专利工作的部门认定假冒专利行为成立的，可以按照下列方式确定行为人的违法所得： （一）销售假冒专利的产品的，以产品销售价格乘以所销售产品的数量作为其违法所得； （二）订立假冒专利的合同的，以收取的费用作为其违法所得。"},{"i":48,"n":"第四十八条","txt":"管理专利工作的部门作出处罚决定后，当事人申请行政复议或者向人民法院提起行政诉讼的，在行政复议或者诉讼期间不停止决定的执行。"},{"i":49,"n":"第四十九条","txt":"假冒专利行为的行为人应当自收到处罚决定书之日起15日内，到指定的银行缴纳处罚决定书写明的罚款；到期不缴纳的，每日按罚款数额的百分之三加处罚款。"},{"i":50,"n":"第五十条","txt":"拒绝、阻碍管理专利工作的部门依法执行公务的，由公安机关根据《中华人民共和国治安管理处罚法》的规定给予处罚；情节严重构成犯罪的，由司法机关依法追究刑事责任。"},{"i":51,"n":"第五十一条","txt":"管理专利工作的部门可以通过寄交、直接送交、留置送达、公告送达或者其他方式送达有关法律文书和材料。"},{"i":52,"n":"第五十二条","txt":"本办法由国家知识产权局负责解释。"},{"i":53,"n":"第五十三条","txt":"本办法自2011年2月1日起施行。2001年12月17日国家知识产权局令第十九号发布的《专利行政执法办法》同时废止。"}],"zhuanlifeiyongjibenxinxidaimaguifan":[],"zhuanlifeiyongjibenxinxidaimaguifan-2":[],"zhishichanquanhangyebiaozhunbiaogegeshihedaimabiaobfae64":[],"zhishichanquanhangyebiaozhunbiaogegeshiguize":[],"guanyuzhuanlidianzishenqingdeguiding-2":[{"i":1,"n":"第一条","txt":"为了规范与通过互联网传输并以电子文件形式提出的专利申请（以下简称专利电子申请）有关的程序和要求，方便申请人提交专利申请，提高专利审批效率，推进电子政务建设，依照《中华人民共和国专利法实施细则》（以下简称专利法实施细则）第二条和第十五条第二款，制定本规定。"},{"i":2,"n":"第二条","txt":"提出专利电子申请的，应当事先与国家知识产权局签订《专利电子申请系统用户注册协议》（以下简称用户协议）。 开办专利电子申请代理业务的专利代理机构，应当以该专利代理机构名义与国家知识产权局签订用户协议。 申请人委托已与国家知识产权局签订用户协议的专利代理机构办理专利电子申请业务的，无须另行与国家知识产权局签订用户协议。"},{"i":3,"n":"第三条","txt":"申请人有两人以上且未委托专利代理机构的，以提交电子申请的申请人为代表人。"},{"i":4,"n":"第四条","txt":"发明、实用新型和外观设计专利申请均可以采用电子文件形式提出。 依照专利法实施细则第一百零一条第二款的规定进入中国国家阶段的专利申请，可以采用电子文件形式提交。 依照专利法实施细则第一百零一条第一款的规定向国家知识产权局提出专利国际申请的，不适用本规定。"},{"i":5,"n":"第五条","txt":"申请专利的发明创造涉及国家安全或者重大利益需要保密的，应当以纸件形式提出专利申请。 申请人以电子文件形式提出专利申请后，国家知识产权局认为该专利申请需要保密的，应当将该专利申请转为纸件形式继续审查并通知申请人。申请人在后续程序中应当以纸件形式递交各种文件。 依照专利法实施细则第八条第二款第（一）项直接向外国申请专利或者向有关国外机构提交专利国际申请的，申请人向国家知识产权局提出的保密审查请求和技术方案应当以纸件形式提出。"},{"i":6,"n":"第六条","txt":"提交专利电子申请和相关文件的，应当遵守规定的文件格式、数据标准、操作规范和传输方式。专利电子申请和相关文件未能被国家知识产权局专利电子申请系统正常接收的，视为未提交。"},{"i":7,"n":"第七条","txt":"申请人办理专利电子申请各种手续的，应当以电子文件形式提交相关文件。除另有规定外，国家知识产权局不接受申请人以纸件形式提交的相关文件。不符合本款规定的，相关文件视为未提交。 以纸件形式提出专利申请并被受理后，除涉及国家安全或者重大利益需要保密的专利申请外，申请人可以请求将纸件申请转为专利电子申请。 特殊情形下需要将专利电子申请转为纸件申请的，申请人应当提出请求，经国家知识产权局审批并办理相关手续后可以转为纸件申请。"},{"i":8,"n":"第八条","txt":"申请人办理专利电子申请的各种手续的，对专利法及其实施细则或者专利审查指南中规定的应当以原件形式提交的相关文件，申请人可以提交原件的电子扫描文件。国家知识产权局认为必要时，可以要求申请人在指定期限内提交原件。 申请人在提出专利电子申请时请求减缴或者缓缴专利法实施细则规定的各种费用需要提交有关证明文件的，应当在提出专利申请时提交证明文件原件的电子扫描文件。未提交电子扫描文件的，视为未提交有关证明文件。"},{"i":9,"n":"第九条","txt":"采用电子文件形式向国家知识产权局提交的各种文件，以国家知识产权局专利电子申请系统收到电子文件之日为递交日。 对于专利电子申请，国家知识产权局以电子文件形式向申请人发出的各种通知书、决定或者其他文件，自文件发出之日起满15日，推定为申请人收到文件之日。"},{"i":10,"n":"第十条","txt":"专利法及其实施细则和专利审查指南中关于专利申请和相关文件的所有规定，除专门针对以纸件形式提交的专利申请和相关文件的规定之外，均适用于专利电子申请。"},{"i":11,"n":"第十一条","txt":"本规定由国家知识产权局负责解释。"},{"i":12,"n":"第十二条","txt":"本规定自2010年10月1日起施行。2004年2月12日国家知识产权局令第三十五号发布的《关于电子专利申请的规定》同时废止。"}],"guanyuzhuanlidianzishenqingdeguiding":[{"i":1,"n":"第一条","txt":"为了规范与通过互联网传输并以电子文件形式提出的专利申请（以下简称专利电子申请）有关的程序和要求，方便申请人提交专利申请，提高专利审批效率，推进电子政务建设，依照《中华人民共和国专利法实施细则》（以下简称专利法实施细则）第二条和第十五条第二款，制定本规定。"},{"i":2,"n":"第二条","txt":"提出专利电子申请的，应当事先与国家知识产权局签订《专利电子申请系统用户注册协议》（以下简称用户协议）。 开办专利电子申请代理业务的专利代理机构，应当以该专利代理机构名义与国家知识产权局签订用户协议。 申请人委托已与国家知识产权局签订用户协议的专利代理机构办理专利电子申请业务的，无须另行与国家知识产权局签订用户协议。"},{"i":3,"n":"第三条","txt":"申请人有两人以上且未委托专利代理机构的，以提交电子申请的申请人为代表人。"},{"i":4,"n":"第四条","txt":"发明、实用新型和外观设计专利申请均可以采用电子文件形式提出。 依照专利法实施细则第一百零一条第二款的规定进入中国国家阶段的专利申请，可以采用电子文件形式提交。 依照专利法实施细则第一百零一条第一款的规定向国家知识产权局提出专利国际申请的，不适用本规定。"},{"i":5,"n":"第五条","txt":"申请专利的发明创造涉及国家安全或者重大利益需要保密的，应当以纸件形式提出专利申请。 申请人以电子文件形式提出专利申请后，国家知识产权局认为该专利申请需要保密的，应当将该专利申请转为纸件形式继续审查并通知申请人。申请人在后续程序中应当以纸件形式递交各种文件。 依照专利法实施细则第八条第二款第（一）项直接向外国申请专利或者向有关国外机构提交专利国际申请的，申请人向国家知识产权局提出的保密审查请求和技术方案应当以纸件形式提出。"},{"i":6,"n":"第六条","txt":"提交专利电子申请和相关文件的，应当遵守规定的文件格式、数据标准、操作规范和传输方式。专利电子申请和相关文件未能被国家知识产权局专利电子申请系统正常接收的，视为未提交。"},{"i":7,"n":"第七条","txt":"申请人办理专利电子申请各种手续的，应当以电子文件形式提交相关文件。除另有规定外，国家知识产权局不接受申请人以纸件形式提交的相关文件。不符合本款规定的，相关文件视为未提交。 以纸件形式提出专利申请并被受理后，除涉及国家安全或者重大利益需要保密的专利申请外，申请人可以请求将纸件申请转为专利电子申请。 特殊情形下需要将专利电子申请转为纸件申请的，申请人应当提出请求，经国家知识产权局审批并办理相关手续后可以转为纸件申请。"},{"i":8,"n":"第八条","txt":"申请人办理专利电子申请的各种手续的，对专利法及其实施细则或者专利审查指南中规定的应当以原件形式提交的相关文件，申请人可以提交原件的电子扫描文件。国家知识产权局认为必要时，可以要求申请人在指定期限内提交原件。 申请人在提出专利电子申请时请求减缴或者缓缴专利法实施细则规定的各种费用需要提交有关证明文件的，应当在提出专利申请时提交证明文件原件的电子扫描文件。未提交电子扫描文件的，视为未提交有关证明文件。"},{"i":9,"n":"第九条","txt":"采用电子文件形式向国家知识产权局提交的各种文件，以国家知识产权局专利电子申请系统收到电子文件之日为递交日。 对于专利电子申请，国家知识产权局以电子文件形式向申请人发出的各种通知书、决定或者其他文件，自文件发出之日起满15日，推定为申请人收到文件之日。"},{"i":10,"n":"第十条","txt":"专利法及其实施细则和专利审查指南中关于专利申请和相关文件的所有规定，除专门针对以纸件形式提交的专利申请和相关文件的规定之外，均适用于专利电子申请。"},{"i":11,"n":"第十一条","txt":"本规定由国家知识产权局负责解释。"},{"i":12,"n":"第十二条","txt":"本规定自2010年10月1日起施行。2004年2月12日国家知识产权局令第三十五号发布的《关于电子专利申请的规定》同时废止。"}],"guanyutaiwantongbaozhuanlishenqingderuoganguiding-2":[{"i":1,"n":"第一条","txt":"为了方便台湾同胞向国家知识产权局申请专利，制定本规定。"},{"i":2,"n":"第二条","txt":"台湾地区申请人（以下简称申请人）在台湾地区专利主管机构第一次提出发明或者实用新型专利申请之日起十二个月内，或者第一次提出外观设计专利申请之日起六个月内，又在国家知识产权局就相同主题提出专利申请的，可以要求享有其台湾地区在先申请的优先权（以下简称台湾地区优先权）。 申请人根据前款规定要求台湾地区优先权的，其在先申请的申请日应当在2010年9月12日（含当日）以后。"},{"i":3,"n":"第三条","txt":"申请人可以在一件申请中要求一项或者多项台湾地区优先权；要求多项台湾地区优先权的，该申请的台湾地区优先权期限从最早的在先申请的申请日起计算。"},{"i":4,"n":"第四条","txt":"申请人要求台湾地区优先权的，应当在向国家知识产权局提出专利申请的同时在请求书中声明，并且在三个月内提交由台湾地区专利主管机构出具的在先申请文件的副本；未在请求书中声明或者期满未提交在先申请文件副本的，视为未要求台湾地区优先权。 申请人在请求书中声明要求台湾地区优先权的，应当写明在先申请的申请日和申请号，并写明原受理机构为“台湾地区”。"},{"i":5,"n":"第五条","txt":"申请人要求一项或者多项台湾地区优先权而在请求书的声明中未写明或者错写其中某件在先申请的申请日、申请号和原受理机构名称中的一项或者两项内容，但申请人已在规定的期限内提交了在先申请文件副本的，国家知识产权局应当通知申请人补正；申请人期满未答复或者补正后仍不符合规定的，视为未要求该项台湾地区优先权。"},{"i":6,"n":"第六条","txt":"申请人要求多项台湾地区优先权的，应当提交全部在先申请文件副本。 在先申请文件副本至少应当表明原受理机构、申请人、申请日、申请号。在先申请文件副本不符合规定的，国家知识产权局应当通知申请人补正；申请人期满未答复或者补正后仍不符合规定的，视为未提交该在先申请文件副本。 国家知识产权局依据有关协议，通过电子交换途径获得在先申请文件副本的，视为申请人提交了符合规定的在先申请文件副本。 申请人已向国家知识产权局提交过在先申请文件副本，需要再次提交的，可以仅提交该副本的题录，但应当注明在先申请文件副本的原件所在申请案卷的申请号。"},{"i":7,"n":"第七条","txt":"要求台湾地区优先权的申请人与在先申请文件副本中记载的申请人不一致的，应当在向国家知识产权局提出专利申请之日起三个月内提交台湾地区优先权转让证明或者有关说明；期满未提交或者提交的文件不符合规定的，视为未要求台湾地区优先权。"},{"i":8,"n":"第八条","txt":"申请人要求台湾地区优先权后，可以撤回其全部或者其中某一项或者几项台湾地区优先权要求。 申请人撤回其台湾地区优先权要求的，应当提交全体申请人签字或者盖章的撤回台湾地区优先权声明；撤回台湾地区优先权声明不符合规定的，视为未提出撤回台湾地区优先权声明。 申请人撤回其台湾地区优先权要求导致该申请的最早台湾地区优先权日变更，且自该台湾地区优先权日起算的各种期限尚未届满的，其台湾地区优先权期限应当自变更后的最早台湾地区优先权日或者申请日起算；撤回台湾地区优先权的声明是在变更前的最早台湾地区优先权日起十五个月之后到达国家知识产权局的，则在后专利申请的公布期限仍按照变更前的最早台湾地区优先权日起算。"},{"i":9,"n":"第九条","txt":"要求台湾地区优先权的，应当在缴纳申请费的同时，根据专利法实施细则第九十三条的规定缴纳台湾地区优先权要求费；期满未缴纳或者未缴足的，视为未要求台湾地区优先权。"},{"i":10,"n":"第十条","txt":"被视为未要求台湾地区优先权并属于下列情形之一的，申请人可以根据专利法实施细则第六条的规定请求恢复要求台湾地区优先权的权利： （一）由于未在指定期限内办理补正手续导致视为未要求台湾地区优先权的； （二）要求台湾地区优先权声明中至少一项内容填写正确，但未在规定的期限内提交在先申请文件副本或者台湾地区优先权转让证明文件或者有关说明的； （三）要求台湾地区优先权声明中至少一项内容填写正确，但未在规定的期限内缴纳或者缴足台湾地区优先权要求费的； （四）分案申请的原申请要求了台湾地区优先权的。 除上述情形外，其他原因造成被视为未要求台湾地区优先权的，不予恢复。"},{"i":11,"n":"第十一条","txt":"申请人提出的专利申请文件中，含有与现行法律、法规、规章相抵触的词句的，国家知识产权局应当通知申请人在两个月内删除或者修改，期满不答复的，其申请被视为撤回；申请人拒绝删除、修改或者修改后仍不符合规定的，应当驳回该专利申请。明显不涉及技术内容的词句，国家知识产权局可以依职权删除并通知申请人；申请人不同意删除的，应当驳回该专利申请。"},{"i":12,"n":"第十二条","txt":"国家知识产权局依申请人请求出具申请文件副本的，应当先根据本规定第十一条对申请文件用语进行审查；申请文件中含有与现行法律、法规、规章相抵触的词句的，在初审合格之前不予办理。"},{"i":13,"n":"第十三条","txt":"申请人不愿公布其地址的，可在“申请人地址”栏中注明“中国台湾”。"},{"i":14,"n":"第十四条","txt":"本规定自2010年11月22日起施行。原中国专利局1993年3月29日颁布的《关于受理台胞专利申请的规定》（国专发法字〔1993〕第63号）和1993年4月23日颁布的《关于台胞申请专利手续中若干问题的处理办法》（国专发审字〔1993〕第69号）同时废止。"}],"guanyutaiwantongbaozhuanlishenqingderuoganguiding":[{"i":1,"n":"第一条","txt":"为了方便台湾同胞向国家知识产权局申请专利，制定本规定。"},{"i":2,"n":"第二条","txt":"台湾地区申请人（以下简称申请人）在台湾地区专利主管机构第一次提出发明或者实用新型专利申请之日起十二个月内，或者第一次提出外观设计专利申请之日起六个月内，又在国家知识产权局就相同主题提出专利申请的，可以要求享有其台湾地区在先申请的优先权（以下简称台湾地区优先权）。 申请人根据前款规定要求台湾地区优先权的，其在先申请的申请日应当在2010年9月12日（含当日）以后。"},{"i":3,"n":"第三条","txt":"申请人可以在一件申请中要求一项或者多项台湾地区优先权；要求多项台湾地区优先权的，该申请的台湾地区优先权期限从最早的在先申请的申请日起计算。"},{"i":4,"n":"第四条","txt":"申请人要求台湾地区优先权的，应当在向国家知识产权局提出专利申请的同时在请求书中声明，并且在三个月内提交由台湾地区专利主管机构出具的在先申请文件的副本；未在请求书中声明或者期满未提交在先申请文件副本的，视为未要求台湾地区优先权。 申请人在请求书中声明要求台湾地区优先权的，应当写明在先申请的申请日和申请号，并写明原受理机构为“台湾地区”。"},{"i":5,"n":"第五条","txt":"申请人要求一项或者多项台湾地区优先权而在请求书的声明中未写明或者错写其中某件在先申请的申请日、申请号和原受理机构名称中的一项或者两项内容，但申请人已在规定的期限内提交了在先申请文件副本的，国家知识产权局应当通知申请人补正；申请人期满未答复或者补正后仍不符合规定的，视为未要求该项台湾地区优先权。"},{"i":6,"n":"第六条","txt":"申请人要求多项台湾地区优先权的，应当提交全部在先申请文件副本。 在先申请文件副本至少应当表明原受理机构、申请人、申请日、申请号。在先申请文件副本不符合规定的，国家知识产权局应当通知申请人补正；申请人期满未答复或者补正后仍不符合规定的，视为未提交该在先申请文件副本。 国家知识产权局依据有关协议，通过电子交换途径获得在先申请文件副本的，视为申请人提交了符合规定的在先申请文件副本。 申请人已向国家知识产权局提交过在先申请文件副本，需要再次提交的，可以仅提交该副本的题录，但应当注明在先申请文件副本的原件所在申请案卷的申请号。"},{"i":7,"n":"第七条","txt":"要求台湾地区优先权的申请人与在先申请文件副本中记载的申请人不一致的，应当在向国家知识产权局提出专利申请之日起三个月内提交台湾地区优先权转让证明或者有关说明；期满未提交或者提交的文件不符合规定的，视为未要求台湾地区优先权。"},{"i":8,"n":"第八条","txt":"申请人要求台湾地区优先权后，可以撤回其全部或者其中某一项或者几项台湾地区优先权要求。 申请人撤回其台湾地区优先权要求的，应当提交全体申请人签字或者盖章的撤回台湾地区优先权声明；撤回台湾地区优先权声明不符合规定的，视为未提出撤回台湾地区优先权声明。 申请人撤回其台湾地区优先权要求导致该申请的最早台湾地区优先权日变更，且自该台湾地区优先权日起算的各种期限尚未届满的，其台湾地区优先权期限应当自变更后的最早台湾地区优先权日或者申请日起算；撤回台湾地区优先权的声明是在变更前的最早台湾地区优先权日起十五个月之后到达国家知识产权局的，则在后专利申请的公布期限仍按照变更前的最早台湾地区优先权日起算。"},{"i":9,"n":"第九条","txt":"要求台湾地区优先权的，应当在缴纳申请费的同时，根据专利法实施细则第九十三条的规定缴纳台湾地区优先权要求费；期满未缴纳或者未缴足的，视为未要求台湾地区优先权。"},{"i":10,"n":"第十条","txt":"被视为未要求台湾地区优先权并属于下列情形之一的，申请人可以根据专利法实施细则第六条的规定请求恢复要求台湾地区优先权的权利： （一）由于未在指定期限内办理补正手续导致视为未要求台湾地区优先权的； （二）要求台湾地区优先权声明中至少一项内容填写正确，但未在规定的期限内提交在先申请文件副本或者台湾地区优先权转让证明文件或者有关说明的； （三）要求台湾地区优先权声明中至少一项内容填写正确，但未在规定的期限内缴纳或者缴足台湾地区优先权要求费的； （四）分案申请的原申请要求了台湾地区优先权的。 除上述情形外，其他原因造成被视为未要求台湾地区优先权的，不予恢复。"},{"i":11,"n":"第十一条","txt":"申请人提出的专利申请文件中，含有与现行法律、法规、规章相抵触的词句的，国家知识产权局应当通知申请人在两个月内删除或者修改，期满不答复的，其申请被视为撤回；申请人拒绝删除、修改或者修改后仍不符合规定的，应当驳回该专利申请。明显不涉及技术内容的词句，国家知识产权局可以依职权删除并通知申请人；申请人不同意删除的，应当驳回该专利申请。"},{"i":12,"n":"第十二条","txt":"国家知识产权局依申请人请求出具申请文件副本的，应当先根据本规定第十一条对申请文件用语进行审查； 申请文件中含有与现行法律、法规、规章相抵触的词句的，在初审合格之前不予办理。"},{"i":13,"n":"第十三条","txt":"申请人不愿公布其地址的，可在“申请人地址”栏中注明“中国台湾”。"},{"i":14,"n":"第十四条","txt":"本规定自2010年11月22日起施行。原中国专利局1993年3月29日颁布的《关于受理台胞专利申请的规定》（国专发法字〔1993〕第63号）和1993年4月23日颁布的《关于台胞申请专利手续中若干问题的处理办法》（国专发审字〔1993〕第69号）同时废止。"}],"guanyuzaixianggangtebiexingzhengquzhishichanquanshbc2567-2":[],"guanyuzaixianggangtebiexingzhengquzhishichanquanshbc2567":[],"guanyuguifanzhuanlishenqingxingweideruoganguiding":[{"i":1,"n":"第一条","txt":"为了规范申请专利的行为，维护正常的专利工作秩序，依据专利法、专利法实施细则和专利代理条例制定本规定。"},{"i":2,"n":"第二条","txt":"提交或者代理提交专利申请的，应当遵照法律、法规和规章的有关规定，恪守诚实信用原则，不得从事非正常申请专利的行为。"},{"i":3,"n":"第三条","txt":"本规定所称非正常申请专利的行为是指： （一）同一单位或者个人提交多件内容明显相同的专利申请，或者指使他人提交多件内容明显相同的专利申请； （二）同一单位或者个人提交多件明显抄袭现有技术或者现有设计的专利申请，或者指使他人提交多件明显抄袭现有技术或者现有设计的专利申请； （三）专利代理机构代理提交本条第（一）项或者第（二）项所述类型的专利申请。"},{"i":4,"n":"第四条","txt":"国家知识产权局对非正常申请专利的行为，除依据专利法及其实施细则的规定对提交的专利申请进行处理之外，可以视情节采取下列处理措施： （一）不予减缓专利费用；已经减缓的，全部或者部分追缴； （二）在国家知识产权局政府网站以及《中国知识产权报》上予以通报； （三）在国家知识产权局的专利申请数量统计中扣除非正常申请专利的数量； （四）建议各地人民政府管理专利工作的部门不予资助或者奖励；已经资助或者奖励的，建议全部或者部分追还 （五）建议中华全国专利代理人协会对从事非正常申请专利行为的专利代理机构以及专利代理人采取行业自律措施，必要时建议专利代理惩戒委员会根据《专利代理惩戒规则（暂行）》的规定给予相应惩戒； （六）通过非正常申请专利的行为骗取资助和奖励，情节严重构成犯罪的，依法移送有关机关追究刑事责任。"},{"i":5,"n":"第五条","txt":"国家知识产权局采取本规定第四条所列处理措施前，应当给予当事人陈述意见的机会。"},{"i":6,"n":"第六条","txt":"各地人民政府管理专利工作的部门应当引导公众和专利代理机构依法提交专利申请。 专利代办处发现非正常申请专利行为的，应当及时报告国家知识产权局。"},{"i":7,"n":"第七条","txt":"本规定自2007年10月1日起施行。"}],"shangbiaoyinzhiguanlibanfa-2":[{"i":1,"n":"第一条","txt":"为了加强商标印制管理，保护注册商标专用权，维护社会主义市场经济秩序，根据《中华人民共和国商标法》、《中华人民共和国商标法实施条例》（以下分别简称《商标法》、《商标法实施条例》）的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"以印刷、印染、制版、刻字、织字、晒蚀、印铁、铸模、冲压、烫印、贴花等方式制作商标标识的，应当遵守本办法。"},{"i":3,"n":"第三条","txt":"商标印制委托人委托商标印制单位印制商标的，应当出示营业执照副本或者合法的营业证明或者身份证明。"},{"i":4,"n":"第四条","txt":"商标印制委托人委托印制注册商标的，应当出示《商标注册证》，并另行提供一份复印件。 签订商标使用许可合同使用他人注册商标，被许可人需印制商标的，还应当出示商标使用许可合同文本并提供一份复印件；商标注册人单独授权被许可人印制商标的，还应当出示授权书并提供一份复印件。"},{"i":5,"n":"第五条","txt":"委托印制注册商标的，商标印制委托人提供的有关证明文件及商标图样应当符合下列要求： （一）所印制的商标样稿应当与《商标注册证》上的商标图样相同； （二）被许可人印制商标标识的，应有明确的授权书，或其所提供的《商标使用许可合同》含有许可人允许其印制商标标识的内容； （三）被许可人的商标标识样稿应当标明被许可人的企业名称和地址；其注册标记的使用符合《商标法实施条例》的有关规定。"},{"i":6,"n":"第六条","txt":"委托印制未注册商标的，商标印制委托人提供的商标图样应当符合下列要求： （一）所印制的商标不得违反《商标法》第十条的规定； （二）所印制的商标不得标注“注册商标”字样或者使用注册标记。"},{"i":7,"n":"第七条","txt":"商标印制单位应当对商标印制委托人提供的证明文件和商标图样进行核查。 商标印制委托人未提供本办法第三条、第四条所规定的证明文件，或者其要求印制的商标标识不符合本办法第五条、第六条规定的，商标印制单位不得承接印制。"},{"i":8,"n":"第八条","txt":"商标印制单位承印符合本办法规定的商标印制业务的，商标印制业务管理人员应当按照要求填写《商标印制业务登记表》，载明商标印制委托人所提供的证明文件的主要内容，《商标印制业务登记表》中的图样应当由商标印制单位业务主管人员加盖骑缝章。 商标标识印制完毕，商标印制单位应当在15天内提取标识样品，连同《商标印制业务登记表》、《商标注册证》复印件、商标使用许可合同复印件、商标印制授权书复印件等一并造册存档。"},{"i":9,"n":"第九条","txt":"商标印制单位应当建立商标标识出入库制度，商标标识出入库应当登记台帐。废次标识应当集中进行销毁，不得流入社会。"},{"i":10,"n":"第十条","txt":"商标印制档案及商标标识出入库台帐应当存档备查，存查期为两年。"},{"i":11,"n":"第十一条","txt":"商标印制单位违反本办法第七条至第十条规定的，由所在地市场监督管理部门责令其限期改正，并视其情节予以警告，处以非法所得额三倍以下的罚款，但最高不超过三万元，没有违法所得的，可以处以一万元以下的罚款。"},{"i":12,"n":"第十二条","txt":"擅自设立商标印刷企业或者擅自从事商标印刷经营活动的，由所在地或者行为地市场监督管理部门依照《印刷业管理条例》的有关规定予以处理。"},{"i":13,"n":"第十三条","txt":"商标印制单位违反第七条规定承接印制业务，且印制的商标与他人注册商标相同或者近似的，属于《商标法实施条例》第七十五条所述的商标侵权行为，由所在地或者行为地市场监督管理部门依《商标法》的有关规定予以处理。"},{"i":14,"n":"第十四条","txt":"商标印制单位的违法行为构成犯罪的，所在地或者行为地市场监督管理部门应及时将案件移送司法机关追究刑事责任。"},{"i":15,"n":"第十五条","txt":"本办法所称“商标印制”是指印刷、制作商标标识的行为。 本办法所称“商标标识”是指与商品配套一同进入流通领域的带有商标的有形载体，包括注册商标标识和未注册商标标识。 本办法所称“商标印制委托人”是指要求印制商标标识的商标注册人、未注册商标使用人、注册商标被许可使用人以及符合《商标法》规定的其他商标使用人。 本办法所称“商标印制单位”是指依法登记从事商标印制业务的企业和个体工商户。 本办法所称《商标注册证》包括国家知识产权局所发的有关变更、续展、转让等证明文件。"},{"i":16,"n":"第十六条","txt":"本办法自2004年9月1日起施行。国家工商行政管理局1996年9月5日发布的《商标印制管理办法》同时废止。"}],"shangbiaopingshenguize-2":[{"i":1,"n":"第一条","txt":"为规范商标评审程序，根据《中华人民共和国商标法》（以下简称商标法）和《中华人民共和国商标法实施条例》（以下简称实施条例），制定本规则。"},{"i":2,"n":"第二条","txt":"根据商标法及实施条例的规定，国家工商行政管理总局商标评审委员会（以下简称商标评审委员会）负责处理下列商标评审案件： （一）不服国家工商行政管理总局商标局（以下简称商标局）驳回商标注册申请决定，依照商标法第三十四条规定申请复审的案件； （二）不服商标局不予注册决定，依照商标法第三十五条第三款规定申请复审的案件； （三）对已经注册的商标，依照商标法第四十四条第一款、第四十五条第一款规定请求无效宣告的案件； （四）不服商标局宣告注册商标无效决定，依照商标法第四十四条第二款规定申请复审的案件； （五）不服商标局撤销或者不予撤销注册商标决定，依照商标法第五十四条规定申请复审的案件。 在商标评审程序中，前款第（一）项所指请求复审的商标统称为申请商标，第（二）项所指请求复审的商标统称为被异议商标，第（三）项所指请求无效宣告的商标统称为争议商标，第（四）、（五）项所指请求复审的商标统称为复审商标。本规"},{"i":3,"n":"第三条","txt":"当事人参加商标评审活动，可以以书面方式或者数据电文方式办理。 数据电文方式办理的具体办法由商标评审委员会另行制定。"},{"i":4,"n":"第四条","txt":"商标评审委员会审理商标评审案件实行书面审理，但依照实施条例第六十条规定决定进行口头审理的除外。 口头审理的具体办法由商标评审委员会另行制定。"},{"i":5,"n":"第五条","txt":"商标评审委员会根据商标法、实施条例和本规则做出的决定和裁定，应当以书面方式或者数据电文方式送达有关当事人，并说明理由。"},{"i":6,"n":"第六条","txt":"除本规则另有规定外，商标评审委员会审理商标评审案件实行合议制度，由三名以上的单数商标评审人员组成合议组进行审理。 合议组审理案件，实行少数服从多数的原则。"},{"i":7,"n":"第七条","txt":"当事人或者利害关系人依照实施条例第七条的规定申请商标评审人员回避的，应当以书面方式办理，并说明理由。"},{"i":8,"n":"第八条","txt":"在商标评审期间，当事人有权依法处分自己的商标权和与商标评审有关的权利。在不损害社会公共利益、第三方权利的前提下，当事人之间可以自行或者经调解以书面方式达成和解。 对于当事人达成和解的案件，商标评审委员会可以结案，也可以做出决定或者裁定。"},{"i":9,"n":"第九条","txt":"商标评审案件的共同申请人和共有商标的当事人办理商标评审事宜，应当依照实施条例第十六条第一款的规定确定一个代表人。 代表人参与评审的行为对其所代表的当事人发生效力，但代表人变更、放弃评审请求或者承认对方当事人评审请求的，应当有被代表的当事人书面授权。 商标评审委员会的文件应当送达代表人。"},{"i":10,"n":"第十条","txt":"外国人或者外国企业办理商标评审事宜，在中国有经常居所或者营业所的，可以委托依法设立的商标代理机构办理，也可以直接办理；在中国没有经常居所或者营业所的，应当委托依法设立的商标代理机构办理。"},{"i":11,"n":"第十一条","txt":"代理权限发生变更、代理关系解除或者变更代理人的，当事人应当及时书面告知商标评审委员会。"},{"i":12,"n":"第十二条","txt":"当事人及其代理人可以申请查阅本案有关材料。"},{"i":13,"n":"第十三条","txt":"申请商标评审，应当符合下列条件： （一）申请人须有合法的主体资格； （二）在法定期限内提出； （三）属于商标评审委员会的评审范围； （四）依法提交符合规定的申请书及有关材料； （五）有明确的评审请求、事实、理由和法律依据； （六）依法缴纳评审费用。"},{"i":14,"n":"第十四条","txt":"申请商标评审，应当向商标评审委员会提交申请书；有被申请人的，应当按照被申请人的数量提交相应份数的副本；评审商标发生转让、移转、变更，已向商标局提出申请但是尚未核准公告的，当事人应当提供相应的证明文件；基于商标局的决定书申请复审的，还应当同时附送商标局的决定书。"},{"i":15,"n":"第十五条","txt":"申请书应当载明下列事项： （一）申请人的名称、通信地址、联系人和联系电话。评审申请有被申请人的，应当载明被申请人的名称和地址。委托商标代理机构办理商标评审事宜的，还应当载明商标代理机构的名称、地址、联系人和联系电话； （二）评审商标及其申请号或者初步审定号、注册号和刊登该商标的《商标公告》的期号； （三）明确的评审请求和所依据的事实、理由及法律依据。"},{"i":16,"n":"第十六条","txt":"商标评审申请不符合本规则第十三条第（一）、（二）、（三）、（六）项规定条件之一的，商标评审委员会不予受理，书面通知申请人，并说明理由。"},{"i":17,"n":"第十七条","txt":"商标评审申请不符合本规则第十三条第（四）、（五）项规定条件之一的，或者未按照实施条例和本规则规定提交有关证明文件的，或者有其他需要补正情形的，商标评审委员会应当向申请人发出补正通知，申请人应当自收到补正通知之日起三十日内补正。 经补正仍不符合规定的，商标评审委员会不予受理，书面通知申请人，并说明理由。未在规定期限内补正的，依照实施条例第五十七条规定，视为申请人撤回评审申请，商标评审委员会应当书面通知申请人。"},{"i":18,"n":"第十八条","txt":"商标评审申请经审查符合受理条件的，商标评审委员会应当在三十日内向申请人发出《受理通知书》。"},{"i":19,"n":"第十九条","txt":"商标评审委员会已经受理的商标评审申请，有下列情形之一的，属于不符合受理条件，应当依照实施条例第五十七条规定予以驳回： （一）违反实施条例第六十二条规定，申请人撤回商标评审申请后，又以相同的事实和理由再次提出评审申请的； （二）违反实施条例第六十二条规定，对商标评审委员会已经做出的裁定或者决定，以相同的事实和理由再次提出评审申请的； （三）其他不符合受理条件的情形。 对经不予注册复审程序予以核准注册的商标提起宣告注册商标无效的，不受前款第（二）项规定限制。 商标评审委员会驳回商标评审申请，应当书面通知申请人，并说明理由。"},{"i":20,"n":"第二十条","txt":"当事人参加评审活动，应当按照对方当事人的数量，提交相应份数的申请书、答辩书、意见书、质证意见及证据材料副本，副本内容应当与正本内容相同。不符合前述要求且经补正仍不符合要求的，依照本规则第十七条第二款的规定，不予受理评审申请，或者视为未提交相关材料。"},{"i":21,"n":"第二十一条","txt":"评审申请有被申请人的，商标评审委员会受理后，应当及时将申请书副本及有关证据材料送达被申请人。被申请人应当自收到申请材料之日起三十日内向商标评审委员会提交答辩书及其副本；未在规定期限内答辩的，不影响商标评审委员会的评审。 商标评审委员会审理不服商标局不予注册决定的复审案件，应当通知原异议人参加并提出意见。原异议人应当在收到申请材料之日起三十日内向商标评审委员会提交意见书及其副本；未在规定期限内提出意见的，不影响案件审理。"},{"i":22,"n":"第二十二条","txt":"被申请人参加答辩和原异议人参加不予注册复审程序应当有合法的主体资格。 商标评审答辩书、意见书及有关证据材料应当按照规定的格式和要求填写、提供。 不符合第二款规定或者有其他需要补正情形的，商标评审委员会向被申请人或者原异议人发出补正通知，被申请人或者原异议人应当自收到补正通知之日起三十日内补正。经补正仍不符合规定或者未在法定期限内补正的，视为未答辩或者未提出意见，不影响商标评审委员会的评审。"},{"i":23,"n":"第二十三条","txt":"当事人需要在提出评审申请或者答辩后补充有关证据材料的，应当在申请书或者答辩书中声明，并自提交申请书或者答辩书之日起三个月内一次性提交；未在申请书或者答辩书中声明或者期满未提交的，视为放弃补充证据材料。但是，在期满后生成或者当事人有其他正当理由未能在期满前提交的证据，在期满后提交的，商标评审委员会将证据交对方当事人并质证后可以采信。 对当事人在法定期限内提供的证据材料，有对方当事人的，商标评审委员会应当将该证据材料副本送达给对方当事人。当事人应当在收到证据材料副本之日起三十日内进行质证。"},{"i":24,"n":"第二十四条","txt":"当事人应当对其提交的证据材料逐一分类编号和制作目录清单，对证据材料的来源、待证的具体事实作简要说明，并签名盖章。 商标评审委员会收到当事人提交的证据材料后，应当按目录清单核对证据材料，并由经办人员在回执上签收，注明提交日期。"},{"i":25,"n":"第二十五条","txt":"当事人名称或者通信地址等事项发生变更的，应当及时通知商标评审委员会，并依需要提供相应的证明文件。"},{"i":26,"n":"第二十六条","txt":"在商标评审程序中，当事人的商标发生转让、移转的，受让人或者承继人应当及时以书面方式声明承受相关主体地位，参加后续评审程序并承担相应的评审后果。 未书面声明且不影响评审案件审理的，商标评审委员会可以将受让人或者承继人列为当事人做出决定或者裁定。"},{"i":27,"n":"第二十七条","txt":"商标评审委员会审理商标评审案件实行合议制度。但有下列情形之一的案件，可以由商标评审人员一人独任评审： （一）仅涉及商标法第三十条和第三十一条所指在先商标权利冲突的案件中，评审时权利冲突已消除的； （二）被请求撤销或者无效宣告的商标已经丧失专用权的； （三）依照本规则第三十二条规定应当予以结案的； （四）其他可以独任评审的案件。"},{"i":28,"n":"第二十八条","txt":"当事人或者利害关系人依照实施条例第七条和本规则第七条的规定对商标评审人员提出回避申请的，被申请回避的商标评审人员在商标评审委员会做出是否回避的决定前，应当暂停参与本案的审理工作。 商标评审委员会在做出决定、裁定后收到当事人或者利害关系人提出的回避申请的，不影响评审决定、裁定的有效性。但评审人员确实存在需要回避的情形的，商标评审委员会应当依法做出处理。"},{"i":29,"n":"第二十九条","txt":"商标评审委员会审理商标评审案件，应当依照实施条例第五十二条、第五十三条、第五十四条、第五十五条、第五十六条的规定予以审理。"},{"i":30,"n":"第三十条","txt":"经不予注册复审程序予以核准注册的商标，原异议人向商标评审委员会请求无效宣告的，商标评审委员会应当另行组成合议组进行审理。"},{"i":31,"n":"第三十一条","txt":"依照商标法第三十五条第四款、第四十五条第三款和实施条例第十一条第（五）项的规定，需要等待在先权利案件审理结果的，商标评审委员会可以决定暂缓审理该商标评审案件。"},{"i":32,"n":"第三十二条","txt":"有下列情形之一的，终止评审，予以结案： （一）申请人死亡或者终止后没有继承人或者继承人放弃评审权利的； （二）申请人撤回评审申请的； （三）当事人自行或者经调解达成和解协议，可以结案的； （四）其他应当终止评审的情形。 商标评审委员会予以结案，应当书面通知有关当事人，并说明理由。"},{"i":33,"n":"第三十三条","txt":"合议组审理案件应当制作合议笔录，并由合议组成员签名。合议组成员有不同意见的，应当如实记入合议笔录。 经审理终结的案件，商标评审委员会依法做出决定、裁定。"},{"i":34,"n":"第三十四条","txt":"商标评审委员会做出的决定、裁定应当载明下列内容： （一）当事人的评审请求、争议的事实、理由和证据； （二）决定或者裁定认定的事实、理由和适用的法律依据； （三）决定或者裁定结论； （四）可以供当事人选用的后续程序和时限； （五）决定或者裁定做出的日期。 决定、裁定由合议组成员署名，加盖商标评审委员会印章。"},{"i":35,"n":"第三十五条","txt":"对商标评审委员会做出的决定、裁定，当事人不服向人民法院起诉的，应当在向人民法院递交起诉状的同时或者至迟十五日内将该起诉状副本抄送或者另行将起诉信息书面告知商标评审委员会。 除商标评审委员会做出的准予初步审定或者予以核准注册的决定外，商标评审委员会自发出决定、裁定之日起四个月内未收到来自人民法院应诉通知或者当事人提交的起诉状副本、书面起诉通知的，该决定、裁定移送商标局执行。 商标评审委员会自收到当事人提交的起诉状副本或者书面起诉通知之日起四个月内未收到来自人民法院应诉通知的，相关决定、裁定移送商标局执行。"},{"i":36,"n":"第三十六条","txt":"在一审行政诉讼程序中，若因商标评审决定、裁定所引证的商标已经丧失在先权利导致决定、裁定事实认定、法律适用发生变化的，在原告撤诉的情况下，商标评审委员会可以撤回原决定或者裁定，并依据新的事实，重新做出商标评审决定或者裁定。 商标评审决定、裁定送达当事人后，商标评审委员会发现存在文字错误等非实质性错误的，可以向评审当事人发送更正通知书对错误内容进行更正。"},{"i":37,"n":"第三十七条","txt":"商标评审决定、裁定经人民法院生效判决撤销的，商标评审委员会应当重新组成合议组，及时审理，并做出重审决定、裁定。 重审程序中，商标评审委员会对当事人新提出的评审请求和法律依据不列入重审范围；对当事人补充提交的足以影响案件审理结果的证据可以予以采信，有对方当事人的，应当送达对方当事人予以质证。"},{"i":38,"n":"第三十八条","txt":"当事人对自己提出的评审请求所依据的事实或者反驳对方评审请求所依据的事实有责任提供证据加以证明。 证据包括书证、物证、视听资料、电子数据、证人证言、鉴定意见、当事人的陈述等。 没有证据或者证据不足以证明当事人的事实主张的，由负有举证责任的当事人承担不利后果。 一方当事人对另一方当事人陈述的案件事实明确表示承认的，另一方当事人无需举证，但商标评审委员会认为确有必要举证的除外。 当事人委托代理人参加评审的，代理人的承认视为当事人的承认。但未经特别授权的代理人对事实的承认直接导致承认对方评审请求的除外；当事人在场但对其代理人的承认不作否认表示的，视为当事人的承认。"},{"i":39,"n":"第三十九条","txt":"下列事实，当事人无需举证证明： （一）众所周知的事实； （二）自然规律及定理； （三）根据法律规定或者已知事实和日常生活经验法则，能推定出的另一事实； （四）已为人民法院发生法律效力的裁判所确认的事实； （五）已为仲裁机构的生效裁决所确认的事实； （六）已为有效公证文书所证明的事实。 前款（一）、（三）、（四）、（五）、（六）项，有相反证据足以推翻的除外。"},{"i":40,"n":"第四十条","txt":"当事人向商标评审委员会提供书证的，应当提供原件，包括原本、正本和副本。提供原件有困难的，可以提供相应的复印件、照片、节录本；提供由有关部门保管的书证原件的复制件、影印件或者抄录件的，应当注明出处，经该部门核对无异后加盖其印章。 当事人向商标评审委员会提供物证的，应当提供原物。提供原物有困难的，可以提供相应的复制件或者证明该物证的照片、录像等其他证据；原物为数量较多的种类物的，可以提供其中的一部分。 一方当事人对另一方当事人所提书证、物证的复制件、照片、录像等存在怀疑并有相应证据支持的，或者商标评审委员会认为有必要的，被质疑的当事人应当提供或者出示有关证据的原件或者经公证的复印件。"},{"i":41,"n":"第四十一条","txt":"当事人向商标评审委员会提供的证据系在中华人民共和国领域外形成，或者在香港、澳门、台湾地区形成，对方当事人对该证据的真实性存在怀疑并有相应证据支持的，或者商标评审委员会认为必要的，应当依照有关规定办理相应的公证认证手续。"},{"i":42,"n":"第四十二条","txt":"当事人向商标评审委员会提供外文书证或者外文说明资料，应当附有中文译文。未提交中文译文的，该外文证据视为未提交。 对方当事人对译文具体内容有异议的，应当对有异议的部分提交中文译文。必要时，可以委托双方当事人认可的单位对全文，或者所使用或者有异议的部分进行翻译。 双方当事人对委托翻译达不成协议的，商标评审委员会可以指定专业翻译单位对全文，或者所使用的或者有异议的部分进行翻译。委托翻译所需费用由双方当事人各承担50％；拒绝支付翻译费用的，视为其承认对方提交的译文。"},{"i":43,"n":"第四十三条","txt":"对单一证据有无证明力和证明力大小可以从下列方面进行审核认定： （一）证据是否原件、原物，复印件、复制品与原件、原物是否相符； （二）证据与本案事实是否相关； （三）证据的形式、来源是否符合法律规定； （四）证据的内容是否真实； （五）证人或者提供证据的人，与当事人有无利害关系。"},{"i":44,"n":"第四十四条","txt":"评审人员对案件的全部证据，应当从各证据与案件事实的关联程度、各证据之间的联系等方面进行综合审查判断。 有对方当事人的，未经交换质证的证据不应当予以采信。"},{"i":45,"n":"第四十五条","txt":"下列证据不能单独作为认定案件事实的依据： （一）未成年人所作的与其年龄和智力状况不相适应的证言； （二）与一方当事人有亲属关系、隶属关系或者其他密切关系的证人所作的对该当事人有利的证言，或者与一方当事人有不利关系的证人所作的对该当事人不利的证言； （三）应当参加口头审理作证而无正当理由不参加的证人证言； （四）难以识别是否经过修改的视听资料； （五）无法与原件、原物核对的复制件或者复制品； （六）经一方当事人或者他人改动，对方当事人不予认可的证据材料； （七）其他不能单独作为认定案件事实依据的证据材料。"},{"i":46,"n":"第四十六条","txt":"一方当事人提出的下列证据，对方当事人提出异议但没有足以反驳的相反证据的，商标评审委员会应当确认其证明力： （一）书证原件或者与书证原件核对无误的复印件、照片、副本、节录本； （二）物证原物或者与物证原物核对无误的复制件、照片、录像资料等； （三）有其他证据佐证并以合法手段取得的、无疑点的视听资料或者与视听资料核对无误的复制件。"},{"i":47,"n":"第四十七条","txt":"一方当事人委托鉴定部门做出的鉴定结论，另一方当事人没有足以反驳的相反证据和理由的，可以确认其证明力。"},{"i":48,"n":"第四十八条","txt":"一方当事人提出的证据，另一方当事人认可或者提出的相反证据不足以反驳的，商标评审委员会可以确认其证明力。 一方当事人提出的证据，另一方当事人有异议并提出反驳证据，对方当事人对反驳证据认可的，可以确认反驳证据的证明力。"},{"i":49,"n":"第四十九条","txt":"双方当事人对同一事实分别举出相反的证据，但都没有足够的依据否定对方证据的，商标评审委员会应当结合案件情况，判断一方提供证据的证明力是否明显大于另一方提供证据的证明力，并对证明力较大的证据予以确认。 因证据的证明力无法判断导致争议事实难以认定的，商标评审委员会应当依据举证责任分配原则做出判断。"},{"i":50,"n":"第五十条","txt":"评审程序中，当事人在申请书、答辩书、陈述及其委托代理人的代理词中承认的对己方不利的事实和认可的证据，商标评审委员会应当予以确认，但当事人反悔并有相反证据足以推翻的除外。"},{"i":51,"n":"第五十一条","txt":"商标评审委员会就数个证据对同一事实的证明力，可以依照下列原则认定： （一）国家机关以及其他职能部门依职权制作的公文文书优于其他书证； （二）鉴定结论、档案材料以及经过公证或者登记的书证优于其他书证、视听资料和证人证言； （三）原件、原物优于复制件、复制品； （四）法定鉴定部门的鉴定结论优于其他鉴定部门的鉴定结论； （五）原始证据优于传来证据； （六）其他证人证言优于与当事人有亲属关系或者其他密切关系的证人提供的对该当事人有利的证言； （七）参加口头审理作证的证人证言优于未参加口头审理作证的证人证言； （八）数个种类不同、内容一致的证据优于一个孤立的证据。"},{"i":52,"n":"第五十二条","txt":"期间包括法定期间和商标评审委员会指定的期间。期间应当依照实施条例第十二条的规定计算。"},{"i":53,"n":"第五十三条","txt":"当事人向商标评审委员会提交的文件或者材料的日期，直接递交的，以递交日为准；邮寄的，以寄出的邮戳日为准；邮戳日不清晰或者没有邮戳的，以商标评审委员会实际收到日为准，但是当事人能够提出实际邮戳日证据的除外。通过邮政企业以外的快递企业递交的，以快递企业收寄日为准；收寄日不明确的，以商标评审委员会实际收到日为准，但是当事人能够提出实际收寄日证据的除外。以数据电文方式提交的，以进入商标评审委员会电子系统的日期为准。 当事人向商标评审委员会邮寄文件，应当使用给据邮件。 当事人向商标评审委员会提交文件，应当在文件中标明商标申请号或者注册号、申请人名称。提交的文件内容，以书面方式提交的，以商标评审委员会所存档案记录为准；以数据电文方式提交的，以商标评审委员会数据库记录为准，但是当事人确有证据证明商标评审委员会档案、数据库记录有错误的除外。"},{"i":54,"n":"第五十四条","txt":"商标评审委员会的各种文件，可以通过邮寄、直接递交、数据电文或者其他方式送达当事人；以数据电文方式送达当事人的，应当经当事人同意。当事人委托商标代理机构的，文件送达商标代理机构视为送达当事人。 商标评审委员会向当事人送达各种文件的日期，邮寄的，以当事人收到的邮戳日为准；邮戳日不清晰或者没有邮戳的，自文件发出之日起满十五日，视为送达当事人，但当事人能够证明实际收到日的除外；直接递交的，以递交日为准。以数据电文方式送达的，自文件发出之日满十五日，视为送达当事人；文件通过上述方式无法送达的，可以通过公告方式送达当事人，自公告发布之日起满三十日，该文件视为已经送达。 商标评审委员会向当事人邮寄送达文件被退回后通过公告送达的，后续文件均采取公告送达方式，但当事人在公告送达后明确告知通信地址的除外。"},{"i":55,"n":"第五十五条","txt":"依照实施条例第五条第三款的规定，商标评审案件的被申请人或者原异议人是在中国没有经常居所或者营业所的外国人或者外国企业的，由该评审商标注册申请书中载明的国内接收人负责接收商标评审程序的有关法律文件；商标评审委员会将有关法律文件送达该国内接收人，视为送达当事人。 依照前款规定无法确定国内接收人的，由商标局原审程序中的或者最后一个申请办理该商标相关事宜的商标代理机构承担商标评审程序中有关法律文件的签收及转达义务；商标评审委员会将有关法律文件送达该商标代理机构。商标代理机构在有关法律文件送达之前已经与国外当事人解除商标代理关系的，应当以书面形式向商标评审委员会说明有关情况，并自收到文件之日起十日内将有关法律文件交回商标评审委员会，由商标评审委员会另行送达。 马德里国际注册商标涉及国际局转发相关书件的，应当提交相应的送达证据。未提交的，应当书面说明原因，自国际局发文之日起满十五日视为送达。 上述"},{"i":56,"n":"第五十六条","txt":"从事商标评审工作的国家机关工作人员玩忽职守、滥用职权、徇私舞弊，违法办理商标评审事项，收受当事人财物，牟取不正当利益的，依法给予处分。"},{"i":57,"n":"第五十七条","txt":"对于当事人不服商标局做出的驳回商标注册申请决定在2014年5月1日以前向商标评审委员会提出复审申请，商标评审委员会于2014年5月1日以后（含5月1日，下同）审理的案件，适用修改后的商标法。 对于当事人不服商标局做出的异议裁定在2014年5月1日以前向商标评审委员会提出复审申请，商标评审委员会于2014年5月1日以后审理的案件，当事人提出异议和复审的主体资格适用修改前的商标法，其他程序问题和实体问题适用修改后的商标法。 对于已经注册的商标，当事人在2014年5月1日以前向商标评审委员会提出争议和撤销复审申请，商标评审委员会于2014年5月1日以后审理的案件，相关程序问题适用修改后的商标法，实体问题适用修改前的商标法。 对于当事人在2014年5月1日以前向商标评审委员会提出申请的商标评审案件，应当自2014年5月1日起开始计算审理期限。"},{"i":58,"n":"第五十八条","txt":"办理商标评审事宜的文书格式，由商标评审委员会制定并公布。"},{"i":59,"n":"第五十九条","txt":"本规则由国家工商行政管理总局负责解释。"},{"i":60,"n":"第六十条","txt":"本规则自2014年6月1日起施行。"}],"guojiazhishichanquanjuxingzhengfuyiguicheng-2":[{"i":1,"n":"第一条","txt":"为了防止和纠正违法或者不当的具体行政行为，保护公民、法人和其他组织的合法权益，保障和监督国家知识产权局依法行使职权，根据《中华人民共和国行政复议法》和《中华人民共和国行政复议法实施条例》，制定本规程。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织认为国家知识产权局的具体行政行为侵犯其合法权益的，可以依照本规程向国家知识产权局申请行政复议。"},{"i":3,"n":"第三条","txt":"国家知识产权局负责法制工作的机构（以下称“行政复议机构”）具体办理行政复议事项，履行下列职责： （一）受理行政复议申请； （二）向有关部门及人员调查取证，调阅有关文档和资料； （三）审查具体行政行为是否合法与适当； （四）办理一并请求的行政赔偿事项； （五）拟订、制作和发送行政复议法律文书； （六）办理因不服行政复议决定提起行政诉讼的应诉事项； （七）督促行政复议决定的履行； （八）办理行政复议、行政应诉案件统计和重大行政复议决定备案事项； （九）研究行政复议工作中发现的问题，及时向有关部门提出行政复议意见或者建议。"},{"i":4,"n":"第四条","txt":"除本规程第五条另有规定外，有下列情形之一的，可以依法申请行政复议： （一）对国家知识产权局作出的有关专利申请、专利权的具体行政行为不服的； （二）对国家知识产权局作出的有关集成电路布图设计登记申请、布图设计专有权的具体行政行为不服的； （三）对国家知识产权局专利复审委员会作出的有关专利复审、无效的程序性决定不服的； （四）对国家知识产权局作出的有关专利代理管理的具体行政行为不服的； （五）认为国家知识产权局作出的其他具体行政行为侵犯其合法权益的。"},{"i":5,"n":"第五条","txt":"对下列情形之一，不能申请行政复议： （一）专利申请人对驳回专利申请的决定不服的； （二）复审请求人对复审请求审查决定不服的； （三）专利权人或者无效宣告请求人对无效宣告请求审查决定不服的； （四）专利权人或者专利实施强制许可的被许可人对强制许可使用费的裁决不服的； （五）国际申请的申请人对国家知识产权局作为国际申请的受理单位、国际检索单位和国际初步审查单位所作决定不服的； （六）集成电路布图设计登记申请人对驳回登记申请的决定不服的； （七）集成电路布图设计登记申请人对复审决定不服的； （八）集成电路布图设计权利人对撤销布图设计登记的决定不服的； （九）集成电路布图设计权利人、非自愿许可取得人对非自愿许可报酬的裁决不服的； （十）集成电路布图设计权利人、被控侵权人对集成电路布图设计专有权侵权纠纷处理决定不服的； （十一）法律、法规规定的其他不能申请行政复议的情形。"},{"i":6,"n":"第六条","txt":"依照本规程申请行政复议的公民、法人或者其他组织是复议申请人。 在具体行政行为作出时其权利或者利益受到损害的其他利害关系人可以申请行政复议，也可以作为第三人参加行政复议。"},{"i":7,"n":"第七条","txt":"复议申请人、第三人可以委托代理人代为参加行政复议。"},{"i":8,"n":"第八条","txt":"公民、法人或者其他组织认为国家知识产权局的具体行政行为侵犯其合法权益的，可以自知道该具体行政行为之日起60日内提出行政复议申请。 因不可抗力或者其他正当理由耽误前款所述期限的，该期限自障碍消除之日起继续计算。"},{"i":9,"n":"第九条","txt":"有权申请行政复议的公民、法人或者其他组织向人民法院提起行政诉讼，人民法院已经依法受理的，不得向国家知识产权局申请行政复议。 向国家知识产权局申请行政复议，行政复议机构已经依法受理的，在法定行政复议期限内不得向人民法院提起行政诉讼。 国家知识产权局受理行政复议申请后，发现在受理前或者受理后当事人向人民法院提起行政诉讼并且人民法院已经依法受理的，驳回行政复议申请。"},{"i":10,"n":"第十条","txt":"行政复议申请应当符合下列条件： （一）复议申请人是认为具体行政行为侵犯其合法权益的专利申请人、专利权人、集成电路布图设计登记申请人、集成电路布图设计权利人或者其他利害关系人； （二）有具体的行政复议请求和理由； （三）属于行政复议的范围； （四）在法定申请期限内提出。"},{"i":11,"n":"第十一条","txt":"申请行政复议应当提交行政复议申请书一式两份，并附具必要的证据材料。被申请复议的具体行政行为以书面形式作出的，应当附具该文书或者其复印件。 委托代理人的，应当附具授权委托书。"},{"i":12,"n":"第十二条","txt":"行政复议申请书应当载明下列内容： （一）复议申请人的姓名或者名称、通信地址、联系电话； （二）具体的行政复议请求； （三）申请行政复议的主要事实和理由； （四）复议申请人的签名或者盖章； （五）申请行政复议的日期。"},{"i":13,"n":"第十三条","txt":"行政复议申请书可以使用国家知识产权局制作的标准表格。 行政复议申请书可以手写或者打印。"},{"i":14,"n":"第十四条","txt":"行政复议申请书应当以邮寄、传真或者当面递交等方式向行政复议机构提交。"},{"i":15,"n":"第十五条","txt":"行政复议机构自收到行政复议申请书之日起5日内，根据情况分别作出如下处理： （一）行政复议申请符合本规程规定的，予以受理，并向复议申请人发送受理通知书； （二）行政复议申请不符合本规程规定的，决定不予受理并书面告知理由； （三）行政复议申请书不符合本规程第十一条、第十二条规定的，通知复议申请人在指定期限内补正；期满未补正的，视为放弃行政复议申请。"},{"i":16,"n":"第十六条","txt":"在审理行政复议案件过程中，行政复议机构可以向有关部门和人员调查情况，也可应请求听取复议申请人或者第三人的口头意见。"},{"i":17,"n":"第十七条","txt":"行政复议机构应当自受理行政复议申请之日起7日内将行政复议申请书副本转交有关部门。该部门应当自收到行政复议申请书副本之日起10日内提出维持、撤销或者变更原具体行政行为的书面答复意见，并提交当时作出具体行政行为的证据、依据和其他有关材料。期满未提出答复意见的，不影响行政复议决定的作出。 复议申请人、第三人可以查阅前款所述书面答复意见以及作出具体行政行为所依据的证据、依据和其他有关材料，但涉及保密内容的除外。"},{"i":18,"n":"第十八条","txt":"行政复议决定作出之前，复议申请人可以要求撤回行政复议申请。准予撤回的，行政复议程序终止。"},{"i":19,"n":"第十九条","txt":"行政复议期间，具体行政行为原则上不停止执行。行政复议机构认为需要停止执行的，应当向有关部门发出停止执行通知书，并通知复议申请人及第三人。"},{"i":20,"n":"第二十条","txt":"审理行政复议案件，以法律、行政法规、部门规章为依据。"},{"i":21,"n":"第二十一条","txt":"具体行政行为认定事实清楚，证据确凿，适用依据正确，程序合法，内容适当的，应当决定维持。"},{"i":22,"n":"第二十二条","txt":"被申请人不履行法定职责的，应当决定其在一定期限内履行法定职责。"},{"i":23,"n":"第二十三条","txt":"具体行政行为有下列情形之一的，应当决定撤销、变更该具体行政行为或者确认该具体行政行为违法，并可以决定由被申请人重新作出具体行政行为： （一）主要事实不清，证据不足的； （二）适用依据错误的； （三）违反法定程序的； （四）超越或者滥用职权的； （五）具体行政行为明显不当的； （六）出现新证据，撤销或者变更原具体行政行为更为合理的。"},{"i":24,"n":"第二十四条","txt":"具体行政行为有下列情形之一的，可以决定变更该具体行政行为： （一）认定事实清楚，证据确凿，程序合法，但是明显不当或者适用依据错误的； （二）认定事实不清，证据不足，经行政复议程序审理查明事实清楚，证据确凿的。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，应当驳回行政复议申请并书面告知理由： （一）复议申请人认为被申请人不履行法定职责而申请行政复议，行政复议机构受理后发现被申请人没有相应法定职责或者在受理前已经履行法定职责的； （二）行政复议机构受理行政复议申请后，发现该行政复议申请不符合受理条件的。"},{"i":26,"n":"第二十六条","txt":"复议申请人申请行政复议时可以一并提出行政赔偿请求。行政复议机构依据国家赔偿法的规定对行政赔偿请求进行审理，在行政复议决定中对赔偿请求一并作出决定。"},{"i":27,"n":"第二十七条","txt":"行政复议决定应当自受理行政复议申请之日起60日内作出，但是情况复杂不能在规定期限内作出的，经审批后可以延长期限，并通知复议申请人和第三人。延长的期限最多不得超过30日。"},{"i":28,"n":"第二十八条","txt":"行政复议决定以国家知识产权局的名义作出。行政复议决定书应当加盖国家知识产权局行政复议专用章。"},{"i":29,"n":"第二十九条","txt":"行政复议期间，行政复议机构发现相关行政行为违法或者需要做好善后工作的，可以制作行政复议意见书。有关部门应当自收到行政复议意见书之日起60日内将纠正相关行政违法行为或者做好善后工作的情况通报行政复议机构。 行政复议期间，行政复议机构发现法律、法规、规章实施中带有普遍性的问题，可以制作行政复议建议书，向有关部门提出完善制度和改进行政执法的建议。"},{"i":30,"n":"第三十条","txt":"期间开始之日不计算在期间内。期间届满的最后一日是节假日的，以节假日后的第一日为期间届满的日期。本规程中有关“5日”、“7日”、“10日”的规定是指工作日，不含节假日。"},{"i":31,"n":"第三十一条","txt":"行政复议决定书直接送达的，复议申请人在送达回证上的签收日期为送达日期。行政复议决定书邮寄送达的，自交付邮寄之日起满15日视为送达。 行政复议决定书一经送达，即发生法律效力。"},{"i":32,"n":"第三十二条","txt":"复议申请人或者第三人委托代理人的，行政复议决定书除送交代理人外，还应当按国内的通讯地址送交复议申请人和第三人。"},{"i":33,"n":"第三十三条","txt":"外国人、外国企业或者外国其他组织向国家知识产权局申请行政复议，适用本规程。"},{"i":34,"n":"第三十四条","txt":"行政复议不收取费用。"},{"i":35,"n":"第三十五条","txt":"本规程自2012年9月1日起施行。2002年7月25日国家知识产权局令第二十四号发布的《国家知识产权局行政复议规程》同时废止。"}],"guojiazhishichanquanjuxingzhengfuyiguicheng":[{"i":1,"n":"第一条","txt":"为了防止和纠正违法或者不当的具体行政行为，保护公民、法人和其他组织的合法权益，保障和监督国家知识产权局依法行使职权，根据《中华人民共和国行政复议法》和《中华人民共和国行政复议法实施条例》，制定本规程。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织认为国家知识产权局的具体行政行为侵犯其合法权益的，可以依照本规程向国家知识产权局申请行政复议。"},{"i":3,"n":"第三条","txt":"国家知识产权局负责法制工作的机构（以下称“行政复议机构”）具体办理行政复议事项，履行下列职责： （一）受理行政复议申请； （二）向有关部门及人员调查取证，调阅有关文档和资料； （三）审查具体行政行为是否合法与适当； （四）办理一并请求的行政赔偿事项； （五）拟订、制作和发送行政复议法律文书； （六）办理因不服行政复议决定提起行政诉讼的应诉事项； （七）督促行政复议决定的履行； （八）办理行政复议、行政应诉案件统计和重大行政复议决定备案事项； （九）研究行政复议工作中发现的问题，及时向有关部门提出行政复议意见或者建议。"},{"i":4,"n":"第四条","txt":"除本规程第五条另有规定外，有下列情形之一的，可以依法申请行政复议： （一）对国家知识产权局作出的有关专利申请、专利权的具体行政行为不服的； （二）对国家知识产权局作出的有关集成电路布图设计登记申请、布图设计专有权的具体行政行为不服的； （三）对国家知识产权局专利复审委员会作出的有关专利复审、无效的程序性决定不服的； （四）对国家知识产权局作出的有关专利代理管理的具体行政行为不服的； （五）认为国家知识产权局作出的其他具体行政行为侵犯其合法权益的。"},{"i":5,"n":"第五条","txt":"对下列情形之一，不能申请行政复议： （一）专利申请人对驳回专利申请的决定不服的； （二）复审请求人对复审请求审查决定不服的； （三）专利权人或者无效宣告请求人对无效宣告请求审查决定不服的； （四）专利权人或者专利实施强制许可的被许可人对强制许可使用费的裁决不服的； （五）国际申请的申请人对国家知识产权局作为国际申请的受理单位、国际检索单位和国际初步审查单位所作决定不服的； （六）集成电路布图设计登记申请人对驳回登记申请的决定不服的； （七）集成电路布图设计登记申请人对复审决定不服的； （八）集成电路布图设计权利人对撤销布图设计登记的决定不服的； （九）集成电路布图设计权利人、非自愿许可取得人对非自愿许可报酬的裁决不服的； （十）集成电路布图设计权利人、被控侵权人对集成电路布图设计专有权侵权纠纷处理决定不服的； （十一）法律、法规规定的其他不能申请行政复议的情形。"},{"i":6,"n":"第六条","txt":"依照本规程申请行政复议的公民、法人或者其他组织是复议申请人。 在具体行政行为作出时其权利或者利益受到损害的其他利害关系人可以申请行政复议，也可以作为第三人参加行政复议。"},{"i":7,"n":"第七条","txt":"复议申请人、第三人可以委托代理人代为参加行政复议。"},{"i":8,"n":"第八条","txt":"公民、法人或者其他组织认为国家知识产权局的具体行政行为侵犯其合法权益的，可以自知道该具体行政行为之日起60日内提出行政复议申请。 因不可抗力或者其他正当理由耽误前款所述期限的，该期限自障碍消除之日起继续计算。"},{"i":9,"n":"第九条","txt":"有权申请行政复议的公民、法人或者其他组织向人民法院提起行政诉讼，人民法院已经依法受理的，不得向国家知识产权局申请行政复议。 向国家知识产权局申请行政复议，行政复议机构已经依法受理的，在法定行政复议期限内不得向人民法院提起行政诉讼。 国家知识产权局受理行政复议申请后，发现在受理前或者受理后当事人向人民法院提起行政诉讼并且人民法院已经依法受理的，驳回行政复议申请。"},{"i":10,"n":"第十条","txt":"行政复议申请应当符合下列条件： （一）复议申请人是认为具体行政行为侵犯其合法权益的专利申请人、专利权人、集成电路布图设计登记申请人、集成电路布图设计权利人或者其他利害关系人； （二）有具体的行政复议请求和理由； （三）属于行政复议的范围； （四）在法定申请期限内提出。"},{"i":11,"n":"第十一条","txt":"申请行政复议应当提交行政复议申请书一式两份，并附具必要的证据材料。被申请复议的具体行政行为以书面形式作出的，应当附具该文书或者其复印件。 委托代理人的，应当附具授权委托书。"},{"i":12,"n":"第十二条","txt":"行政复议申请书应当载明下列内容： （一）复议申请人的姓名或者名称、通信地址、联系电话； （二）具体的行政复议请求； （三）申请行政复议的主要事实和理由； （四）复议申请人的签名或者盖章； （五）申请行政复议的日期。"},{"i":13,"n":"第十三条","txt":"行政复议申请书可以使用国家知识产权局制作的标准表格。 行政复议申请书可以手写或者打印。"},{"i":14,"n":"第十四条","txt":"行政复议申请书应当以邮寄、传真或者当面递交等方式向行政复议机构提交。"},{"i":15,"n":"第十五条","txt":"行政复议机构自收到行政复议申请书之日起5日内，根据情况分别作出如下处理： （一）行政复议申请符合本规程规定的，予以受理，并向复议申请人发送受理通知书； （二）行政复议申请不符合本规程规定的，决定不予受理并书面告知理由； （三）行政复议申请书不符合本规程第十一条、第十二条规定的，通知复议申请人在指定期限内补正；期满未补正的，视为放弃行政复议申请。"},{"i":16,"n":"第十六条","txt":"在审理行政复议案件过程中，行政复议机构可以向有关部门和人员调查情况，也可应请求听取复议申请人或者第三人的口头意见。"},{"i":17,"n":"第十七条","txt":"行政复议机构应当自受理行政复议申请之日起7日内将行政复议申请书副本转交有关部门。该部门应当自收到行政复议申请书副本之日起10日内提出维持、撤销或者变更原具体行政行为的书面答复意见，并提交当时作出具体行政行为的证据、依据和其他有关材料。期满未提出答复意见的，不影响行政复议决定的作出。 复议申请人、第三人可以查阅前款所述书面答复意见以及作出具体行政行为所依据的证据、依据和其他有关材料，但涉及保密内容的除外。"},{"i":18,"n":"第十八条","txt":"行政复议决定作出之前，复议申请人可以要求撤回行政复议申请。准予撤回的，行政复议程序终止。"},{"i":19,"n":"第十九条","txt":"行政复议期间，具体行政行为原则上不停止执行。行政复议机构认为需要停止执行的，应当向有关部门发出停止执行通知书，并通知复议申请人及第三人。"},{"i":20,"n":"第二十条","txt":"审理行政复议案件，以法律、行政法规、部门规章为依据。"},{"i":21,"n":"第二十一条","txt":"具体行政行为认定事实清楚，证据确凿，适用依据正确，程序合法，内容适当的，应当决定维持。"},{"i":22,"n":"第二十二条","txt":"被申请人不履行法定职责的，应当决定其在一定期限内履行法定职责。"},{"i":23,"n":"第二十三条","txt":"具体行政行为有下列情形之一的，应当决定撤销、变更该具体行政行为或者确认该具体行政行为违法，并可以决定由被申请人重新作出具体行政行为： （一）主要事实不清，证据不足的； （二）适用依据错误的； （三）违反法定程序的； （四）超越或者滥用职权的； （五）具体行政行为明显不当的； （六）出现新证据，撤销或者变更原具体行政行为更为合理的。"},{"i":24,"n":"第二十四条","txt":"具体行政行为有下列情形之一的，可以决定变更该具体行政行为： （一）认定事实清楚，证据确凿，程序合法，但是明显不当或者适用依据错误的； （二）认定事实不清，证据不足，经行政复议程序审理查明事实清楚，证据确凿的。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，应当驳回行政复议申请并书面告知理由： （一）复议申请人认为被申请人不履行法定职责而申请行政复议，行政复议机构受理后发现被申请人没有相应法定职责或者在受理前已经履行法定职责的； （二）行政复议机构受理行政复议申请后，发现该行政复议申请不符合受理条件的。"},{"i":26,"n":"第二十六条","txt":"复议申请人申请行政复议时可以一并提出行政赔偿请求。行政复议机构依据国家赔偿法的规定对行政赔偿请求进行审理，在行政复议决定中对赔偿请求一并作出决定。"},{"i":27,"n":"第二十七条","txt":"行政复议决定应当自受理行政复议申请之日起60日内作出，但是情况复杂不能在规定期限内作出的，经审批后可以延长期限，并通知复议申请人和第三人。延长的期限最多不得超过30日。"},{"i":28,"n":"第二十八条","txt":"行政复议决定以国家知识产权局的名义作出。行政复议决定书应当加盖国家知识产权局行政复议专用章。"},{"i":29,"n":"第二十九条","txt":"行政复议期间，行政复议机构发现相关行政行为违法或者需要做好善后工作的，可以制作行政复议意见书。有关部门应当自收到行政复议意见书之日起60日内将纠正相关行政违法行为或者做好善后工作的情况通报行政复议机构。 行政复议期间，行政复议机构发现法律、法规、规章实施中带有普遍性的问题，可以制作行政复议建议书，向有关部门提出完善制度和改进行政执法的建议。"},{"i":30,"n":"第三十条","txt":"期间开始之日不计算在期间内。期间届满的最后一日是节假日的，以节假日后的第一日为期间届满的日期。本规程中有关“5日”、“7日”、“10日”的规定是指工作日，不含节假日。"},{"i":31,"n":"第三十一条","txt":"行政复议决定书直接送达的，复议申请人在送达回证上的签收日期为送达日期。行政复议决定书邮寄送达的，自交付邮寄之日起满15日视为送达。 行政复议决定书一经送达，即发生法律效力。"},{"i":32,"n":"第三十二条","txt":"复议申请人或者第三人委托代理人的，行政复议决定书除送交代理人外，还应当按国内的通讯地址送交复议申请人和第三人。"},{"i":33,"n":"第三十三条","txt":"外国人、外国企业或者外国其他组织向国家知识产权局申请行政复议，适用本规程。"},{"i":34,"n":"第三十四条","txt":"行政复议不收取费用。"},{"i":35,"n":"第三十五条","txt":"本规程自2012年9月1日起施行。2002年7月25日国家知识产权局令第二十四号发布的《国家知识产权局行政复议规程》同时废止。"}],"guojiazhishichanquanjuguifanxingwenjianzhidinghegu109618-2":[{"i":1,"n":"第一条","txt":"为了规范国家知识产权局规范性文件的制定工作，加强对规范性文件的管理，促进依法行政，根据《中共中央 国务院关于印发〈法治政府建设实施纲要（2015-2020年）〉的通知》（中发〔2015〕36号）、《国务院关于加强法治政府建设的意见》（国发〔2010〕33号）等要求，结合国家知识产权局实际情况，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称规范性文件，是指部门规章以外的，国家知识产权局依照法定职权和规定程序单独或者牵头会同有关部门制定的，涉及公民、法人或者其他组织的权利义务，具有普遍约束力并且在一定期限内反复适用的文件，不包括规范内部事务、通报具体情况、处理具体事项以及单纯转发的文件。"},{"i":3,"n":"第三条","txt":"国家知识产权局规范性文件的起草、审查、批准、发布、备案、清理，适用本办法。"},{"i":4,"n":"第四条","txt":"制定规范性文件应当坚持公开、效能和权责统一原则。"},{"i":5,"n":"第五条","txt":"规范性文件应当符合法律、行政法规、部门规章的规定，不得设定行政许可、行政处罚、行政强制等事项，不得减损公民、法人或者其他组织合法权益或者增加其义务。涉及公民、法人或者其他组织权利义务的规范性文件，应当按照法定要求和程序予以公布，未经公布不得作为行政管理依据。"},{"i":6,"n":"第六条","txt":"局业务司（部）负责职责范围内的规范性文件的起草、清理等工作；条法司负责规范性文件的合法性审查、备案、组织清理等工作。 条法司在开展规范性文件的合法性审查、备案、清理等工作时，应当充分发挥公职律师、法律顾问的作用。"},{"i":7,"n":"第七条","txt":"规范性文件由相关业务司（部）负责起草。涉及局内多个司（部）业务的，由牵头司（部）负责组织相关业务司（部）起草并对不同的意见进行协调。起草时，应当有起草司（部）法治联络员参与。 起草规范性文件草案时应当同时起草草案说明。规范性文件涉及重大事项的，还应当同时起草解读方案及解读材料。"},{"i":8,"n":"第八条","txt":"规范性文件的名称应当根据具体内容确定，一般使用“办法”“规定”“通知”“决定”“意见”等名称。规范性文件的内容应当明确具体、逻辑严密、具有可操作性；文字应当准确、规范、简洁。"},{"i":9,"n":"第九条","txt":"规范性文件草案应当根据内容需要明确制定目的和依据、适用范围、管理部门和施行日期等内容。 草案还应当明确列明因该文件施行而失效或者废止的文件的名称、文号；仅涉及部分条款失效或者废止的，应当列明相关条款。 草案说明应当包括下列内容： （一）制定该文件的必要性和可行性； （二）所依据的法律、行政法规、部门规章和有关文件； （三）拟解决的主要问题以及采取的主要措施； （四）征求意见及对意见的采纳情况； （五）其他需要说明的问题。"},{"i":10,"n":"第十条","txt":"起草司（部）应当深入开展调查研究，根据实际需要征求局内相关部门（单位）、地方知识产权局、社会公众和有关专家的意见。 起草对公民、法人或者其他组织的权利义务产生直接影响的规范性文件，起草司（部）应当向社会公布规范性文件草案，征求社会各界意见。 征求意见可以采取书面、网上公开或者召开座谈会、论证会、听证会等形式。 起草司（部）应当根据征求意见的情况，对规范性文件征求意见稿进行修改，形成规范性文件草案送审稿，并在草案说明中对征求意见及采纳情况进行说明。"},{"i":11,"n":"第十一条","txt":"规范性文件起草工作完成后，在报请批准或者审议前，起草司（部）应当将草案送审稿、草案说明和其他必要材料提交条法司进行合法性审查。未经合法性审查或者经审查不合法的，不得提交批准或者审议。"},{"i":12,"n":"第十二条","txt":"条法司收到草案送审稿及相关材料后，一般应当在5个工作日内提出合法性审查意见。 合法性审查的内容包括： （一）是否与法律、行政法规、部门规章相抵触； （二）是否与我国加入的国际条约相抵触； （三）是否属于国家知识产权局的法定职权范围； （四）其他需要审查的事项。"},{"i":13,"n":"第十三条","txt":"经审查无异议，条法司应当作出合法性审查通过的审查意见。 草案送审稿存在合法性问题，不符合本办法要求的，条法司应当作出合法性审查不予通过的审查意见并说明理由。起草司（部）应当根据合法性审查意见对草案进行修改或者对制定规范性文件的必要性、可行性等进行重新论证。"},{"i":14,"n":"第十四条","txt":"规范性文件草案应当提交局长或者分管副局长批准，涉及重大事项的应当经局务会审议通过。 将规范性文件草案提交批准或者提请局务会审议时应当附具草案说明和合法性审查意见书。局务会对规范性文件草案进行审议时，由起草司（部）就起草情况、解读方案及解读材料作说明，条法司就合法性审查情况作说明。 规范性文件经批准或者审议通过后，由起草司（部）正式行文，按照局公文办理程序报请局长或者分管副局长签发。"},{"i":15,"n":"第十五条","txt":"规范性文件应当以局发文或者办公室发文形式发布。局办公室应当对规范性文件统一登记、统一编号、统一印发。 除规范性文件涉及国家秘密需要保密外，起草司（部）应当在规范性文件发布后，及时在局政府网站上全文公开。有解读材料的，相关解读材料应当于文件公开后3个工作日内在局政府网站上公布。"},{"i":16,"n":"第十六条","txt":"规范性文件发布后，局办公室和起草部门应当主动监测职责范围内的政务舆情，及时了解社会关切，有针对性地做好说明工作。"},{"i":17,"n":"第十七条","txt":"自规范性文件发布之日起5个工作日内，起草司（部）应当将文件报送条法司备案。"},{"i":18,"n":"第十八条","txt":"报送规范性文件备案，应当提交纸件和电子件形式的备案表、规范性文件正式发布文本和草案说明。 规范性文件有法律、行政法规、部门规章以外制定依据的，报送备案时，应当同时附具该制定依据。 规范性文件包含宣布其他规范性文件失效或者废止的内容的，报送备案时，应当同时附具该失效或者废止的规范性文件。"},{"i":19,"n":"第十九条","txt":"条法司应当建立规范性文件备案数据库，将所有规范性文件纳入数据库进行统一管理。"},{"i":20,"n":"第二十条","txt":"规范性文件的全面清理工作应当每隔2年开展一次。 起草司（部）应当对其负责起草的所有规范性文件提出明确清理意见。规范性文件的起草涉及多个司（部）的，由牵头起草司（部）商相关司（部）后提出清理意见。 清理工作完成后，由条法司拟定继续有效、需要修改、宣布失效和废止的规范性文件目录，按照规范性文件批准发布程序及时向社会公布。"},{"i":21,"n":"第二十一条","txt":"规范性文件有下列情形之一的，应予宣布失效： （一）适用期已过； （二）调整对象已消失或者规定的事项、任务已完成，实际上已经失效。"},{"i":22,"n":"第二十二条","txt":"规范性文件有下列情形之一的，应予废止： （一）主要内容与现行法律、行政法规、部门规章以及国家政策相抵触； （二）主要内容已经不能适应经济社会发展需要； （三）主要内容已被新的法律、行政法规、部门规章或者规范性文件代替； （四）主要依据的法律、行政法规、部门规章和国务院规范性文件已废止或者失效。"},{"i":23,"n":"第二十三条","txt":"规范性文件有下列情形之一的，应予修改： （一）个别条款与现行法律、行政法规、部门规章和国家政策不一致，但基本适应经济社会发展需要、有必要继续实施； （二）规范性文件之间对同一事项规定不一致； （三）主要依据的法律、行政法规、部门规章和国务院规范性文件已经修改； （四）个别条款不能适应经济社会发展需要。 规范性文件修改的程序参照本办法第二章至第五章的规定。"},{"i":24,"n":"第二十四条","txt":"规范性文件有具体实施期限的，应当在正文中明确规定有效期限。名称冠以“暂行”“试行”的，有效期限一般不得超过2年。有效期限届满，规范性文件自动失效。 规范性文件在有效期届满后需要继续实施的，应当在有效期届满前1个月作必要修改后重新发布。"},{"i":25,"n":"第二十五条","txt":"本办法由国家知识产权局负责解释。"},{"i":26,"n":"第二十六条","txt":"本办法自2017年2月1日起施行。"}],"guojiazhishichanquanjuguifanxingwenjianzhidinghegu109618":[{"i":1,"n":"第一条","txt":"为了规范国家知识产权局规范性文件的制定工作，加强对规范性文件的管理，促进依法行政，根据《中共中央 国务院关于印发〈法治政府建设实施纲要（2015-2020年）〉的通知》（中发〔2015〕36号）、《国务院关于加强法治政府建设的意见》（国发〔2010〕33号）等要求，结合国家知识产权局实际情况，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称规范性文件，是指部门规章以外的，国家知识产权局依照法定职权和规定程序单独或者牵头会同有关部门制定的，涉及公民、法人或者其他组织的权利义务，具有普遍约束力并且在一定期限内反复适用的文件，不包括规范内部事务、通报具体情况、处理具体事项以及单纯转发的文件。"},{"i":3,"n":"第三条","txt":"国家知识产权局规范性文件的起草、审查、批准、发布、备案、清理，适用本办法。"},{"i":4,"n":"第四条","txt":"制定规范性文件应当坚持公开、效能和权责统一原则。"},{"i":5,"n":"第五条","txt":"规范性文件应当符合法律、行政法规、部门规章的规定，不得设定行政许可、行政处罚、行政强制等事项，不得减损公民、法人或者其他组织合法权益或者增加其义务。涉及公民、法人或者其他组织权利义务的规范性文件，应当按照法定要求和程序予以公布，未经公布不得作为行政管理依据。"},{"i":6,"n":"第六条","txt":"局业务司（部）负责职责范围内的规范性文件的起草、清理等工作；条法司负责规范性文件的合法性审查、备案、组织清理等工作。 条法司在开展规范性文件的合法性审查、备案、清理等工作时，应当充分发挥公职律师、法律顾问的作用。"},{"i":7,"n":"第七条","txt":"规范性文件由相关业务司（部）负责起草。涉及局内多个司（部）业务的，由牵头司（部）负责组织相关业务司（部）起草并对不同的意见进行协调。起草时，应当有起草司（部）法治联络员参与。 起草规范性文件草案时应当同时起草草案说明。规范性文件涉及重大事项的，还应当同时起草解读方案及解读材料。"},{"i":8,"n":"第八条","txt":"规范性文件的名称应当根据具体内容确定，一般使用“办法”“规定”“通知”“决定”“意见”等名称。规范性文件的内容应当明确具体、逻辑严密、具有可操作性；文字应当准确、规范、简洁。"},{"i":9,"n":"第九条","txt":"规范性文件草案应当根据内容需要明确制定目的和依据、适用范围、管理部门和施行日期等内容。 草案还应当明确列明因该文件施行而失效或者废止的文件的名称、文号；仅涉及部分条款失效或者废止的，应当列明相关条款。 草案说明应当包括下列内容： （一）制定该文件的必要性和可行性； （二）所依据的法律、行政法规、部门规章和有关文件； （三）拟解决的主要问题以及采取的主要措施； （四）征求意见及对意见的采纳情况； （五）其他需要说明的问题。"},{"i":10,"n":"第十条","txt":"起草司（部）应当深入开展调查研究，根据实际需要征求局内相关部门（单位）、地方知识产权局、社会公众和有关专家的意见。 起草对公民、法人或者其他组织的权利义务产生直接影响的规范性文件，起草司（部）应当向社会公布规范性文件草案，征求社会各界意见。 征求意见可以采取书面、网上公开或者召开座谈会、论证会、听证会等形式。 起草司（部）应当根据征求意见的情况，对规范性文件征求意见稿进行修改，形成规范性文件草案送审稿，并在草案说明中对征求意见及采纳情况进行说明。"},{"i":11,"n":"第十一条","txt":"规范性文件起草工作完成后，在报请批准或者审议前，起草司（部）应当将草案送审稿、草案说明和其他必要材料提交条法司进行合法性审查。未经合法性审查或者经审查不合法的，不得提交批准或者审议。"},{"i":12,"n":"第十二条","txt":"条法司收到草案送审稿及相关材料后，一般应当在5个工作日内提出合法性审查意见。 合法性审查的内容包括： （一）是否与法律、行政法规、部门规章相抵触； （二）是否与我国加入的国际条约相抵触； （三）是否属于国家知识产权局的法定职权范围； （四）其他需要审查的事项。"},{"i":13,"n":"第十三条","txt":"经审查无异议，条法司应当作出合法性审查通过的审查意见。 草案送审稿存在合法性问题，不符合本办法要求的，条法司应当作出合法性审查不予通过的审查意见并说明理由。起草司（部）应当根据合法性审查意见对草案进行修改或者对制定规范性文件的必要性、可行性等进行重新论证。"},{"i":14,"n":"第十四条","txt":"规范性文件草案应当提交局长或者分管副局长批准，涉及重大事项的应当经局务会审议通过。 将规范性文件草案提交批准或者提请局务会审议时应当附具草案说明和合法性审查意见书。局务会对规范性文件草案进行审议时，由起草司（部）就起草情况、解读方案及解读材料作说明，条法司就合法性审查情况作说明。 规范性文件经批准或者审议通过后，由起草司（部）正式行文，按照局公文办理程序报请局长或者分管副局长签发。"},{"i":15,"n":"第十五条","txt":"规范性文件应当以局发文或者办公室发文形式发布。局办公室应当对规范性文件统一登记、统一编号、统一印发。 除规范性文件涉及国家秘密需要保密外，起草司（部）应当在规范性文件发布后，及时在局政府网站上全文公开。有解读材料的，相关解读材料应当于文件公开后3个工作日内在局政府网站上公布。"},{"i":16,"n":"第十六条","txt":"规范性文件发布后，局办公室和起草部门应当主动监测职责范围内的政务舆情，及时了解社会关切，有针对性地做好说明工作。"},{"i":17,"n":"第十七条","txt":"自规范性文件发布之日起5个工作日内，起草司（部）应当将文件报送条法司备案。"},{"i":18,"n":"第十八条","txt":"报送规范性文件备案，应当提交纸件和电子件形式的备案表、规范性文件正式发布文本和草案说明。 规范性文件有法律、行政法规、部门规章以外制定依据的，报送备案时，应当同时附具该制定依据。 规范性文件包含宣布其他规范性文件失效或者废止的内容的，报送备案时，应当同时附具该失效或者废止的规范性文件。"},{"i":19,"n":"第十九条","txt":"条法司应当建立规范性文件备案数据库，将所有规范性文件纳入数据库进行统一管理。"},{"i":20,"n":"第二十条","txt":"规范性文件的全面清理工作应当每隔2年开展一次。 起草司（部）应当对其负责起草的所有规范性文件提出明确清理意见。规范性文件的起草涉及多个司（部）的，由牵头起草司（部）商相关司（部）后提出清理意见。 清理工作完成后，由条法司拟定继续有效、需要修改、宣布失效和废止的规范性文件目录，按照规范性文件批准发布程序及时向社会公布。"},{"i":21,"n":"第二十一条","txt":"规范性文件有下列情形之一的，应予宣布失效： （一）适用期已过； （二）调整对象已消失或者规定的事项、任务已完成，实际上已经失效。"},{"i":22,"n":"第二十二条","txt":"规范性文件有下列情形之一的，应予废止： （一）主要内容与现行法律、行政法规、部门规章以及国家政策相抵触； （二）主要内容已经不能适应经济社会发展需要； （三）主要内容已被新的法律、行政法规、部门规章或者规范性文件代替； （四）主要依据的法律、行政法规、部门规章和国务院规范性文件已废止或者失效。"},{"i":23,"n":"第二十三条","txt":"规范性文件有下列情形之一的，应予修改： （一）个别条款与现行法律、行政法规、部门规章和国家政策不一致，但基本适应经济社会发展需要、有必要继续实施； （二）规范性文件之间对同一事项规定不一致； （三）主要依据的法律、行政法规、部门规章和国务院规范性文件已经修改； （四）个别条款不能适应经济社会发展需要。 规范性文件修改的程序参照本办法第二章至第五章的规定。"},{"i":24,"n":"第二十四条","txt":"规范性文件有具体实施期限的，应当在正文中明确规定有效期限。名称冠以“暂行”“试行”的，有效期限一般不得超过2年。有效期限届满，规范性文件自动失效。 规范性文件在有效期届满后需要继续实施的，应当在有效期届满前1个月作必要修改后重新发布。"},{"i":25,"n":"第二十五条","txt":"本办法由国家知识产权局负责解释。"},{"i":26,"n":"第二十六条","txt":"本办法自2017年2月1日起施行。"}],"dilibiaozhichanpinbaohuguiding-2":[{"i":1,"n":"第一条","txt":"为了有效保护我国的地理标志产品，规范地理标志产品名称和专用标志的使用，保证地理标志产品的质量和特色，根据《中华人民共和国产品质量法》、《中华人民共和国标准化法》、《中华人民共和国进出口商品检验法》等有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称地理标志产品，是指产自特定地域，所具有的质量、声誉或其他特性本质上取决于该产地的自然因素和人文因素，经审核批准以地理名称进行命名的产品。地理标志产品包括： （一）来自本地区的种植、养殖产品。 （二）原材料全部来自本地区或部分来自其他地区，并在本地区按照特定工艺生产和加工的产品。"},{"i":3,"n":"第三条","txt":"本规定适用于对地理标志产品的申请受理、审核批准、地理标志专用标志注册登记和监督管理工作。"},{"i":4,"n":"第四条","txt":"国家质量监督检验检疫总局（以下简称“国家质检总局”）统一管理全国的地理标志产品保护工作。各地出入境检验检疫局和质量技术监督局（以下简称各地质检机构）依照职能开展地理标志产品保护工作。"},{"i":5,"n":"第五条","txt":"申请地理标志产品保护，应依照本规定经审核批准。使用地理标志产品专用标志，必须依照本规定经注册登记，并接受监督管理。"},{"i":6,"n":"第六条","txt":"地理标志产品保护遵循申请自愿，受理及批准公开的原则。"},{"i":7,"n":"第七条","txt":"申请地理标志保护的产品应当符合安全、卫生、环保的要求，对环境、生态、资源可能产生危害的产品，不予受理和保护。"},{"i":8,"n":"第八条","txt":"地理标志产品保护申请，由当地县级以上人民政府指定的地理标志产品保护申请机构或人民政府认定的协会和企业（以下简称申请人）提出，并征求相关部门意见。"},{"i":9,"n":"第九条","txt":"申请保护的产品在县域范围内的，由县级人民政府提出产地范围的建议;跨县域范围的，由地市级人民政府提出产地范围的建议;跨地市范围的，由省级人民政府提出产地范围的建议。"},{"i":10,"n":"第十条","txt":"申请人应提交以下资料： （一）有关地方政府关于划定地理标志产品产地范围的建议。 （二）有关地方政府成立申请机构或认定协会、企业作为申请人的文件。 （三）地理标志产品的证明材料，包括： 1.地理标志产品保护申请书; 2.产品名称、类别、产地范围及地理特征的说明; 3.产品的理化、感官等质量特色及其与产地的自然因素和人文因素之间关系的说明; 4.产品生产技术规范（包括产品加工工艺、安全卫生要求、加工设备的技术要求等）; 5.产品的知名度，产品生产、销售情况及历史渊源的说明; （四）拟申请的地理标志产品的技术标准。"},{"i":11,"n":"第十一条","txt":"出口企业的地理标志产品的保护申请向本辖区内出入境检验检疫部门提出;按地域提出的地理标志产品的保护申请和其他地理标志产品的保护申请向当地（县级或县级以上）质量技术监督部门提出。"},{"i":12,"n":"第十二条","txt":"省级质量技术监督局和直属出入境检验检疫局，按照分工，分别负责对拟申报的地理标志产品的保护申请提出初审意见，并将相关文件、资料上报国家质检总局。"},{"i":13,"n":"第十三条","txt":"国家质检总局对收到的申请进行形式审查。审查合格的，由国家质检总局在国家质检总局公报、政府网站等媒体上向社会发布受理公告;审查不合格的，应书面告知申请人。"},{"i":14,"n":"第十四条","txt":"有关单位和个人对申请有异议的，可在公告后的2个月内向国家质检总局提出。"},{"i":15,"n":"第十五条","txt":"国家质检总局按照地理标志产品的特点设立相应的专家审查委员会，负责地理标志产品保护申请的技术审查工作。"},{"i":16,"n":"第十六条","txt":"国家质检总局组织专家审查委员会对没有异议或者有异议但被驳回的申请进行技术审查，审查合格的，由国家质检总局发布批准该产品获得地理标志产品保护的公告。"},{"i":17,"n":"第十七条","txt":"拟保护的地理标志产品，应根据产品的类别、范围、知名度、产品的生产销售等方面的因素，分别制订相应的国家标准、地方标准或管理规范。"},{"i":18,"n":"第十八条","txt":"国家标准化行政主管部门组织草拟并发布地理标志保护产品的国家标准;省级地方人民政府标准化行政主管部门组织草拟并发布地理标志保护产品的地方标准。"},{"i":19,"n":"第十九条","txt":"地理标志保护产品的质量检验由省级质量技术监督部门、直属出入境检验检疫部门指定的检验机构承担。必要时，国家质检总局将组织予以复检。"},{"i":20,"n":"第二十条","txt":"地理标志产品产地范围内的生产者使用地理标志产品专用标志，应向当地质量技术监督局或出入境检验检疫局提出申请，并提交以下资料： （一）地理标志产品专用标志使用申请书。 （二）由当地政府主管部门出具的产品产自特定地域的证明。 （三）有关产品质量检验机构出具的检验报告。 上述申请经省级质量技术监督局或直属出入境检验检疫局审核，并经国家质检总局审查合格注册登记后，发布公告，生产者即可在其产品上使用地理标志产品专用标志，获得地理标志产品保护。"},{"i":21,"n":"第二十一条","txt":"各地质检机构依法对地理标志保护产品实施保护。对于擅自使用或伪造地理标志名称及专用标志的;不符合地理标志产品标准和管理规范要求而使用该地理标志产品的名称的;或者使用与专用标志相近、易产生误解的名称或标识及可能误导消费者的文字或图案标志，使消费者将该产品误认为地理标志保护产品的行为，质量技术监督部门和出入境检验检疫部门将依法进行查处。社会团体、企业和个人可监督、举报。"},{"i":22,"n":"第二十二条","txt":"各地质检机构对地理标志产品的产地范围，产品名称，原材料，生产技术工艺，质量特色，质量等级、数量、包装、标识，产品专用标志的印刷、发放、数量、使用情况，产品生产环境、生产设备，产品的标准符合性等方面进行日常监督管理。"},{"i":23,"n":"第二十三条","txt":"获准使用地理标志产品专用标志资格的生产者，未按相应标准和管理规范组织生产的，或者在2年内未在受保护的地理标志产品上使用专用标志的，国家质检总局将注销其地理标志产品专用标志使用注册登记，停止其使用地理标志产品专用标志并对外公告。"},{"i":24,"n":"第二十四条","txt":"违反本规定的，由质量技术监督行政部门和出入境检验检疫部门依据《中华人民共和国产品质量法》、《中华人民共和国标准化法》、《中华人民共和国进出口商品检验法》等有关法律予以行政处罚。"},{"i":25,"n":"第二十五条","txt":"从事地理标志产品保护工作的人员应忠于职守，秉公办事，不得滥用职权、以权谋私，不得泄露技术秘密。违反以上规定的，予以行政纪律处分;构成犯罪的依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"国家质检总局接受国外地理标志产品在中华人民共和国的注册并实施保护。具体办法另外规定。"},{"i":27,"n":"第二十七条","txt":"本规定由国家质检总局负责解释。"},{"i":28,"n":"第二十八条","txt":"本规定自2005年7月15日起施行。原国家质量技术监督局公布的《原产地域产品保护规定》同时废止。原国家出入境检验检疫局公布的《原产地标记管理规定》、《原产地标记管理规定实施办法》中关于地理标志的内容与本规定不一致的，以本规定为准。"}],"zhanhuizhishichanquanbaohubanfa-2":[{"i":1,"n":"第一条","txt":"为加强展会期间知识产权保护，维护会展业秩序，推动会展业的健康发展，根据《中华人民共和国对外贸易法》、《中华人民共和国专利法》、《中华人民共和国商标法》和《中华人民共和国著作权法》及相关行政法规等制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内举办的各类经济技术贸易展览会、展销会、博览会、交易会、展示会等活动中有关专利、商标、版权的保护。"},{"i":3,"n":"第三条","txt":"展会管理部门应加强对展会期间知识产权保护的协调、监督、 检查，维护展会的正常交易秩序。"},{"i":4,"n":"第四条","txt":"展会主办方应当依法维护知识产权权利人的合法权益。展会主办方在招商招展时，应加强对参展方有关知识产权的保护和对参展项目（包括展品、展板及相关宣传资料等）的知识产权状况的审查。在展会期间，展会主办方应当积极配合知识产权行政管理部门的知识产权保护工作。 展会主办方可通过与参展方签订参展期间知识产权保护条款或合同的形式，加强展会知识产权保护工作。"},{"i":5,"n":"第五条","txt":"参展方应当合法参展，不得侵犯他人知识产权，并应对知识产权行政管理部门或司法部门的调查予以配合。"},{"i":6,"n":"第六条","txt":"展会时间在三天以上（含三天），展会管理部门认为有必要的，展会主办方应在展会期间设立知识产权投诉机构。设立投诉机构的，展会举办地知识产权行政管理部门应当派员进驻，并依法对侵权案件进行处理。 未设立投诉机构的，展会举办地知识产权行政管理部门应当加强对展会知识产权保护的指导、监督和有关案件的处理，展会主办方应当将展会举办地的相关知识产权行政管理部门的联系人、联系方式等在展会场馆的显著位置予以公示。"},{"i":7,"n":"第七条","txt":"展会知识产权投诉机构应由展会主办方、展会管理部门、专利、商标、版权等知识产权行政管理部门的人员组成，其职责包括： （一）接受知识产权权利人的投诉，暂停涉嫌侵犯知识产权的展品在展会期间展出； （二）将有关投诉材料移交相关知识产权行政管理部门； （三）协调和督促投诉的处理； （四）对展会知识产权保护信息进行统计和分析； （五）其他相关事项。"},{"i":8,"n":"第八条","txt":"知识产权权利人可以向展会知识产权投诉机构投诉也可直接向知识产权行政管理部门投诉。权利人向投诉机构投诉的，应当提交以下材料： （一）合法有效的知识产权权属证明：涉及专利的，应当提交专利证书、专利公告文本、专利权人的身份证明、专利法律状态证明；涉及商标的，应当提交商标注册证明文件，并由投诉人签章确认，商标权利人身份证明；涉及著作权的，应当提交著作权权利证明、著作权人身份证明； （二）涉嫌侵权当事人的基本信息； （三）涉嫌侵权的理由和证据； （四）委托代理人投诉的，应提交授权委托书。"},{"i":9,"n":"第九条","txt":"不符合本办法第八条规定的，展会知识产权投诉机构应当及时通知投诉人或者请求人补充有关材料。未予补充的，不予接受。"},{"i":10,"n":"第十条","txt":"投诉人提交虚假投诉材料或其他因投诉不实给被投诉人带来损失的，应当承担相应法律责任。"},{"i":11,"n":"第十一条","txt":"展会知识产权投诉机构在收到符合本办法第八条规定的投诉材料后，应于24小时内将其移交有关知识产权行政管理部门。"},{"i":12,"n":"第十二条","txt":"地方知识产权行政管理部门受理投诉或者处理请求的，应当通知展会主办方，并及时通知被投诉人或者被请求人。"},{"i":13,"n":"第十三条","txt":"在处理侵犯知识产权的投诉或者请求程序中，地方知识产权行政管理部门可以根据展会的展期指定被投诉人或者被请求人的答辩期限。"},{"i":14,"n":"第十四条","txt":"被投诉人或者被请求人提交答辩书后，除非有必要作进一步调查，地方知识产权行政管理部门应当及时作出决定并送交双方当事人。 被投诉人或者被请求人逾期未提交答辩书的，不影响地方知识产权行政管理部门作出决定。"},{"i":15,"n":"第十五条","txt":"展会结束后，相关知识产权行政管理部门应当及时将有关处理结果通告展会主办方。展会主办方应当做好展会知识产权保护的统计分析工作，并将有关情况及时报展会管理部门。"},{"i":16,"n":"第十六条","txt":"展会投诉机构需要地方知识产权局协助的，地方知识产权局应当积极配合，参与展会知识产权保护工作。地方知识产权局在展会期间的工作可以包括： （一）接受展会投诉机构移交的关于涉嫌侵犯专利权的投诉，依照专利法律法规的有关规定进行处理； （二）受理展出项目涉嫌侵犯专利权的专利侵权纠纷处理请求，依照专利法第五十七条的规定进行处理； （三）受理展出项目涉嫌假冒他人专利和冒充专利的举报，或者依职权查处展出项目中假冒他人专利和冒充专利的行为，依据专利法第五十八条和第五十九条的规定进行处罚。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，地方知识产权局对侵犯专利权的投诉或者处理请求不予受理： （一）投诉人或者请求人已经向人民法院提起专利侵权诉讼的； （二）专利权正处于无效宣告请求程序之中的； （三）专利权存在权属纠纷，正处于人民法院的审理程序或者管理专利工作的部门的调解程序之中的； （四）专利权已经终止，专利权人正在办理权利恢复的。"},{"i":18,"n":"第十八条","txt":"地方知识产权局在通知被投诉人或者被请求人时，可以即行调查取证，查阅、复制与案件有关的文件，询问当事人，采用拍照、摄像等方式进行现场勘验，也可以抽样取证。 地方知识产权局收集证据应当制作笔录，由承办人员、被调查取证的当事人签名盖章。被调查取证的当事人拒绝签名盖章的，应当在笔录上注明原因；有其他人在现场的，也可同时由其他人签名。"},{"i":19,"n":"第十九条","txt":"展会投诉机构需要地方工商行政管理部门协助的，地方工商行政管理部门应当积极配合，参与展会知识产权保护工作。地方工商行政管理部门在展会期间的工作可以包括： （一）接受展会投诉机构移交的关于涉嫌侵犯商标权的投诉，依照商标法律法规的有关规定进行处理； （二）受理符合商标法第五十二条规定的侵犯商标专用权的投诉； （三）依职权查处商标违法案件。"},{"i":20,"n":"第二十条","txt":"有下列情形之一的，地方工商行政管理部门对侵犯商标专用权的投诉或者处理请求不予受理： （一）投诉人或者请求人已经向人民法院提起商标侵权诉讼的； （二）商标权已经无效或者被撤销的。"},{"i":21,"n":"第二十一条","txt":"地方工商行政管理部门决定受理后，可以根据商标法律法规等相关规定进行调查和处理。"},{"i":22,"n":"第二十二条","txt":"展会投诉机构需要地方著作权行政管理部门协助的，地方著作权行政管理部门应当积极配合，参与展会知识产权保护工作。地方著作权行政管理部门在展会期间的工作可以包括： （一）接受展会投诉机构移交的关于涉嫌侵犯著作权的投诉，依照著作权法律法规的有关规定进行处理； （二）受理符合著作权法第四十七条规定的侵犯著作权的投诉，根据著作权法的有关规定进行处罚。"},{"i":23,"n":"第二十三条","txt":"地方著作权行政管理部门在受理投诉或请求后，可以采取以下手段收集证据： （一）查阅、复制与涉嫌侵权行为有关的文件档案、帐簿和其他书面材料； （二）对涉嫌侵权复制品进行抽样取证； （三）对涉嫌侵权复制品进行登记保存。"},{"i":24,"n":"第二十四条","txt":"对涉嫌侵犯知识产权的投诉，地方知识产权行政管理部门认定侵权成立的，应会同会展管理部门依法对参展方进行处理。"},{"i":25,"n":"第二十五条","txt":"对涉嫌侵犯发明或者实用新型专利权的处理请求，地方知识产权局认定侵权成立的，应当依据专利法第十一条第一款关于禁止许诺销售行为的规定以及专利法第五十七条关于责令侵权人立即停止侵权行为的规定作出处理决定，责令被请求人从展会上撤出侵权展品，销毁介绍侵权展品的宣传材料，更换介绍侵权项目的展板。 对涉嫌侵犯外观设计专利权的处理请求，被请求人在展会上销售其展品，地方知识产权局认定侵权成立的，应当依据专利法第十一条第二款关于禁止销售行为的规定以及第五十七条关于责令侵权人立即停止侵权行为的规定作出处理决定，责令被请求人从展会上撤出侵权展品。"},{"i":26,"n":"第二十六条","txt":"在展会期间假冒他人专利或以非专利产品冒充专利产品，以非专利方法冒充专利方法的，地方知识产权局应当依据专利法第五十八条和第五十九条规定进行处罚。"},{"i":27,"n":"第二十七条","txt":"对有关商标案件的处理请求，地方工商行政管理部门认定侵权成立的，应当根据《商标法》、《商标法实施条例》等相关规定进行处罚。"},{"i":28,"n":"第二十八条","txt":"对侵犯著作权及相关权利的处理请求，地方著作权行政管理部门认定侵权成立的，应当根据著作权法第四十七条的规定进行处罚，没收、销毁侵权展品及介绍侵权展品的宣传材料，更换介绍展出项目的展板。"},{"i":29,"n":"第二十九条","txt":"经调查，被投诉或者被请求的展出项目已经由人民法院或者知识产权行政管理部门作出判定侵权成立的判决或者决定并发生法律效力的，地方知识产权行政管理部门可以直接作出第二十六条、第二十七条、第二十八条和第二十九条所述的处理决定。"},{"i":30,"n":"第三十条","txt":"请求人除请求制止被请求人的侵权展出行为之外，还请求制止同一被请求人的其他侵犯知识产权行为的，地方知识产权行政管理部门对发生在其管辖地域之内的涉嫌侵权行为，可以依照相关知识产权法律法规以及规章的规定进行处理。"},{"i":31,"n":"第三十一条","txt":"参展方侵权成立的，展会管理部门可依法对有关参展方予以公告；参展方连续两次以上侵权行为成立的，展会主办方应禁止有关参展方参加下一届展会。"},{"i":32,"n":"第三十二条","txt":"主办方对展会知识产权保护不力的，展会管理部门应对主办方给予警告，并视情节依法对其再次举办相关展会的申请不予批准。"},{"i":33,"n":"第三十三条","txt":"展会结束时案件尚未处理完毕的，案件的有关事实和证据可经展会主办方确认，由展会举办地知识产权行政管理部门在15个工作日内移交有管辖权的知识产权行政管理部门依法处理。"},{"i":34,"n":"第三十四条","txt":"本办法中的知识产权行政管理部门是指专利、商标和版权行政管理部门；本办法中的展会管理部门是指展会的审批或者登记部门。"},{"i":35,"n":"第三十五条","txt":"本办法自2006年3月1日起实施。"}],"shixingxiugaihoudezhuanlifashishixizedeguodubanfa-2":[{"i":1,"n":"第一条","txt":"为了保障2010年1月9日公布的《国务院关于修改〈中华人民共和国专利法实施细则〉的决定》的施行，依照立法法第八十四条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"修改前的专利法实施细则的规定适用于申请日在2010年2月1日前（不含该日）的专利申请以及根据该专利申请授予的专利权；修改后的专利法实施细则的规定适用于申请日在2010年2月1日以后（含该日，下同）的专利申请以及根据该专利申请授予的专利权；但本办法以下各条对申请日在2010年2月1日前的专利申请以及根据该申请授予的专利权的特殊规定除外。"},{"i":3,"n":"第三条","txt":"2010年2月1日以后以不符合专利法第二十三条第三款的规定为理由提出无效宣告请求的，对该无效宣告请求的审查适用修改后的专利法实施细则第六十六条第三款的规定。"},{"i":4,"n":"第四条","txt":"2010年2月1日以后提出无效宣告请求的，对该无效宣告请求的审查适用修改后的专利法实施细则第七十二条第二款的规定。"},{"i":5,"n":"第五条","txt":"专利国际申请的申请人在2010年2月1日以后办理进入中国国家阶段手续的，该国际申请适用修改后的专利法实施细则第十章的规定。"},{"i":6,"n":"第六条","txt":"在2010年2月1日以后请求国家知识产权局中止有关程序的，适用修改后的专利法实施细则第九十三条和第九十九条的规定，不再缴纳中止程序请求费。 在2010年2月1日以后请求退还多缴、重缴、错缴的专利费用的，适用修改后的专利法实施细则第九十四条第四款的规定。 在2010年2月1日以后缴纳申请费、公布印刷费和申请附加费的，适用修改后的专利法实施细则第九十五条的规定。 在2010年2月1日以后办理授予专利权的登记手续的，适用修改后的专利法实施细则第九十三条和第九十七条的规定，不再缴纳申请维持费。"},{"i":7,"n":"第七条","txt":"本办法自2010年2月1日起施行。"}],"shixingxiugaihoudezhuanlifashishixizedeguodubanfa":[{"i":1,"n":"第一条","txt":"为了保障2010年1月9日公布的《国务院关于修改〈中华人民共和国专利法实施细则〉的决定》的施行，依照立法法第八十四条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"修改前的专利法实施细则的规定适用于申请日在2010年2月1日前（不含该日）的专利申请以及根据该专利申请授予的专利权；修改后的专利法实施细则的规定适用于申请日在2010年2月1日以后（含该日，下同）的专利申请以及根据该专利申请授予的专利权；但本办法以下各条对申请日在2010年2月1日前的专利申请以及根据该申请授予的专利权的特殊规定除外。"},{"i":3,"n":"第三条","txt":"2010年2月1日以后以不符合专利法第二十三条第三款的规定为理由提出无效宣告请求的，对该无效宣告请求的审查适用修改后的专利法实施细则第六十六条第三款的规定。"},{"i":4,"n":"第四条","txt":"2010年2月1日以后提出无效宣告请求的，对该无效宣告请求的审查适用修改后的专利法实施细则第七十二条第二款的规定。"},{"i":5,"n":"第五条","txt":"专利国际申请的申请人在2010年2月1日以后办理进入中国国家阶段手续的，该国际申请适用修改后的专利法实施细则第十章的规定。"},{"i":6,"n":"第六条","txt":"在2010年2月1日以后请求国家知识产权局中止有关程序的，适用修改后的专利法实施细则第九十三条和第九十九条的规定，不再缴纳中止程序请求费。 在2010年2月1日以后请求退还多缴、重缴、错缴的专利费用的，适用修改后的专利法实施细则第九十四条第四款的规定。 在2010年2月1日以后缴纳申请费、公布印刷费和申请附加费的，适用修改后的专利法实施细则第九十五条的规定。 在2010年2月1日以后办理授予专利权的登记手续的，适用修改后的专利法实施细则第九十三条和第九十七条的规定，不再缴纳申请维持费。"},{"i":7,"n":"第七条","txt":"本办法自2010年2月1日起施行。"}],"shixingxiugaihoudezhuanlifadeguodubanfa-2":[{"i":1,"n":"第一条","txt":"为了保障2008年12月27日公布的《全国人民代表大会常务委员会关于修改〈中华人民共和国专利法〉的决定》的施行，依照立法法第八十四条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"修改前的专利法的规定适用于申请日在2009年10月1日前（不含该日，下同）的专利申请以及根据该专利申请授予的专利权；修改后的专利法的规定适用于申请日在2009年10月1日以后（含该日，下同）的专利申请以及根据该专利申请授予的专利权；但本办法以下各条对申请日在2009年10月1日前的专利申请以及根据该申请授予的专利权的特殊规定除外。 前款所述申请日的含义依照专利法实施细则的有关规定理解。"},{"i":3,"n":"第三条","txt":"2009年10月1日以后请求给予实施专利的强制许可的，适用修改后的专利法第六章的规定。"},{"i":4,"n":"第四条","txt":"管理专利工作的部门对发生在2009年10月1日以后的涉嫌侵犯专利权行为进行处理的，适用修改后的专利法第十一条、第六十二条、第六十九条、第七十条的规定。"},{"i":5,"n":"第五条","txt":"管理专利工作的部门对发生在2009年10月1日以后的涉嫌假冒专利行为进行查处的，适用修改后的专利法第六十三条、第六十四条的规定。"},{"i":6,"n":"第六条","txt":"专利权人在2009年10月1日以后标明专利标识的，适用修改后的专利法第十七条的规定。"},{"i":7,"n":"第七条","txt":"在中国没有经常居所或者营业所的外国人、外国企业或者外国其他组织在2009年10月1日以后委托或者变更专利代理机构的，适用修改后的专利法第十九条的规定。"},{"i":8,"n":"第八条","txt":"本办法自2009年10月1日起施行。"}],"shixingxiugaihoudezhuanlifadeguodubanfa":[{"i":1,"n":"第一条","txt":"为了保障2008年12月27日公布的《全国人民代表大会常务委员会关于修改〈中华人民共和国专利法〉的决定》的施行，依照立法法第八十四条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"修改前的专利法的规定适用于申请日在2009年10月1日前（不含该日，下同）的专利申请以及根据该专利申请授予的专利权；修改后的专利法的规定适用于申请日在2009年10月1日以后（含该日，下同）的专利申请以及根据该专利申请授予的专利权；但本办法以下各条对申请日在2009年10月1日前的专利申请以及根据该申请授予的专利权的特殊规定除外。 前款所述申请日的含义依照专利法实施细则的有关规定理解。"},{"i":3,"n":"第三条","txt":"2009年10月1日以后请求给予实施专利的强制许可的，适用修改后的专利法第六章的规定。"},{"i":4,"n":"第四条","txt":"管理专利工作的部门对发生在2009年10月1日以后的涉嫌侵犯专利权行为进行处理的，适用修改后的专利法第十一条、第六十二条、第六十九条、第七十条的规定。"},{"i":5,"n":"第五条","txt":"管理专利工作的部门对发生在2009年10月1日以后的涉嫌假冒专利行为进行查处的，适用修改后的专利法第六十三条、第六十四条的规定。"},{"i":6,"n":"第六条","txt":"专利权人在2009年10月1日以后标明专利标识的，适用修改后的专利法第十七条的规定。"},{"i":7,"n":"第七条","txt":"在中国没有经常居所或者营业所的外国人、外国企业或者外国其他组织在2009年10月1日以后委托或者变更专利代理机构的，适用修改后的专利法第十九条的规定。"},{"i":8,"n":"第八条","txt":"本办法自2009年10月1日起施行。"}],"hegansuanhehuoanjisuanxuliebiaohexuliebiaodianziwe75c00b":[],"yongyuzhuanlichengxudeshengwucailiaobaocangbanfa-2":[{"i":1,"n":"第一条","txt":"为了规范用于专利程序的生物材料的保藏和提供样品的程序，根据《中华人民共和国专利法》和《中华人民共和国专利法实施细则》（以下简称专利法实施细则），制定本办法。"},{"i":2,"n":"第二条","txt":"生物材料保藏单位负责保藏用于专利程序的生物材料以及向有权获得样品的单位或者个人提供所保藏的生物材料样品。"},{"i":3,"n":"第三条","txt":"在中国没有经常居所或者营业所的外国人、外国企业或者外国其他组织根据本办法办理相关事务的，应当委托依法设立的专利代理机构办理。"},{"i":4,"n":"第四条","txt":"专利申请人依照专利法实施细则第二十四条提交生物材料保藏时，应当向保藏单位提交该生物材料，并附具保藏请求书写明下列事项： （一） 请求保藏的生物材料是用于专利程序的目的，并保证在本办法第九条规定的保藏期间内不撤回该保藏； （二） 专利申请人的姓名或者名称和地址； （三） 详细叙述该生物材料的培养、保藏和进行存活性检验所需的条件；保藏两种以上生物材料的混合培养物时，应当说明其组分以及至少一种能检查各个组分存在的方法； （四） 专利申请人给予该生物材料的识别符号，以及对该生物材料的分类命名或者科学描述； （五） 写明生物材料具有或者可能具有危及健康或者环境的特性，或者写明专利申请人不知道该生物材料具有此种特性。"},{"i":5,"n":"第五条","txt":"保藏单位对请求保藏的生物材料的生物特性不承担复核的义务。专利申请人要求对该生物材料的生物特性和分类命名进行复核检验的，应当在提交保藏生物材料时与保藏单位另行签订合同。"},{"i":6,"n":"第六条","txt":"保藏单位收到生物材料和保藏请求书后，应当向专利申请人出具经保藏单位盖章和负责人签字的书面保藏证明。保藏证明应当包括下列各项： （一） 保藏单位的名称和地址； （二） 专利申请人的姓名或者名称和地址； （三） 收到生物材料的日期； （四） 专利申请人给予该生物材料的识别符号，以及对该生物材料的分类命名或者科学描述； （五） 保藏单位给予的保藏编号。"},{"i":7,"n":"第七条","txt":"有下列情形之一的，保藏单位对生物材料不予保藏，并应当通知专利申请人： （一）该生物材料不属于保藏单位接受保藏的生物材料种类； （二）该生物材料的性质特殊，保藏单位的技术条件无法进行保藏； （三）保藏单位在收到保藏请求时，有其他理由无法接受该生物材料。"},{"i":8,"n":"第八条","txt":"保藏单位收到生物材料以及保藏请求后应当及时进行存活性检验，并向专利申请人出具经保藏单位盖章和负责人签字的书面存活证明。存活证明应当记载该生物材料是否存活，并应当包括下列各项： （一）保藏单位的名称和地址； （二）专利申请人的姓名或者名称和地址； （三）收到生物材料的日期； （四）保藏单位给予的保藏编号； （五）存活性检验的日期。 在保藏期间内，应专利申请人或者专利权人随时提出的请求，保藏单位应当对该生物材料进行存活性检验并向其出具经保藏单位盖章和负责人签字的书面存活证明。"},{"i":9,"n":"第九条","txt":"用于专利程序的生物材料的保藏期限至少30年，自保藏单位收到生物材料之日起计算。保藏单位在保藏期限届满前收到提供生物材料样品请求的，自请求日起至少应当再保藏5年。在保藏期间内，保藏单位应当采取一切必要的措施保持其保藏的生物材料存活和不受污染。"},{"i":10,"n":"第十条","txt":"涉及保藏的生物材料的专利申请公布前，保藏单位对其保藏的生物材料以及相关信息负有保密责任，不得向任何第三方提供该生物材料的样品和信息。"},{"i":11,"n":"第十一条","txt":"生物材料在保藏期间内发生死亡或者污染等情况的，保藏单位应当及时通知专利申请人或者专利权人。专利申请人或者专利权人在收到上述通知之日起4个月内重新提交与原保藏的生物材料相同的生物材料的，保藏单位予以继续保藏。"},{"i":12,"n":"第十二条","txt":"在保藏期间内，应保藏生物材料的专利申请人或者专利权人或者经其允许的任何单位或者个人的请求，保藏单位应当向其提供该生物材料的样品。 专利申请权或者专利权发生转让的，请求提供生物材料样品的权利以及允许他人获得生物材料样品的权利一并转让。 专利申请权或者专利权发生转让的，受让人应当及时通知保藏单位该专利申请权或者专利权的转让情况。"},{"i":13,"n":"第十三条","txt":"《国际承认用于专利程序的微生物保藏布达佩斯条约》缔约方专利局正在审查的专利申请或者已经授予的专利权涉及保藏单位所保藏的生物材料，该专利局为其专利程序的目的要求保藏单位提供该生物材料样品的，保藏单位应当向其提供。"},{"i":14,"n":"第十四条","txt":"国家知识产权局收到请求人依照专利法实施细则第二十五条提出的请求后，应当核实下列事项： （一）涉及该保藏生物材料的专利申请已经向国家知识产权局提交，并且该申请的主题包括该生物材料或者其利用； （二）所述专利申请已经公布或者授权； （三）请求人已经按照专利法实施细则第二十五条的规定作出保证。 国家知识产权局应当将该请求和有关文件的副本转送专利申请人或者专利权人，要求其在指定期限内就是否同意向请求人提供样品提出意见。专利申请人或者专利权人不同意向请求人提供样品的，应当说明理由并提交必要的证据；逾期不提出意见的，视为同意向请求人提供样品。 国家知识产权局应当综合考虑核实的情况以及专利申请人或者专利权人提出的意见，确定是否向请求人出具其有权获得生物材料样品的证明。"},{"i":15,"n":"第十五条","txt":"除本办法第十二条和第十三条规定的情形外，请求提供生物材料样品的单位或者个人向保藏单位提交提供样品请求书以及国家知识产权局根据本办法第十四条所出具的证明的，保藏单位应当向其提供生物材料样品。"},{"i":16,"n":"第十六条","txt":"保藏单位依照本办法提供生物材料样品，获得生物材料样品的人使用生物材料样品的，还应当遵守国家有关生物安全、出入境管理等法律法规的规定。"},{"i":17,"n":"第十七条","txt":"保藏单位依照本办法向专利申请人或者专利权人之外的其他单位或者个人提供生物材料样品的，应当及时通知专利申请人或者专利权人。"},{"i":18,"n":"第十八条","txt":"自本办法第九条规定的保藏期限届满之日起1年内，专利申请人或者专利权人可以取回所保藏的生物材料或者与保藏单位协商处置该生物材料。专利申请人或者专利权人在该期限内不取回也不进行处置的，保藏单位有权处置该生物材料。"},{"i":19,"n":"第十九条","txt":"保藏单位确定的接受保藏的生物材料种类以及收费标准应当予以公布，并报国家知识产权局备案。"},{"i":20,"n":"第二十条","txt":"本办法自2015年3月1日起施行。1985年3月12日中华人民共和国专利局公告第八号发布的《中国微生物菌种保藏管理委员会普通微生物中心用于专利程序的微生物保藏办法》和《中国典型培养物中心用于专利程序的微生物保藏办法》同时废止。"}],"yongyuzhuanlichengxudeshengwucailiaobaocangbanfa":[{"i":1,"n":"第一条","txt":"为了规范用于专利程序的生物材料的保藏和提供样品的程序，根据《中华人民共和国专利法》和《中华人民共和国专利法实施细则》（以下简称专利法实施细则），制定本办法。"},{"i":2,"n":"第二条","txt":"生物材料保藏单位负责保藏用于专利程序的生物材料以及向有权获得样品的单位或者个人提供所保藏的生物材料样品。"},{"i":3,"n":"第三条","txt":"在中国没有经常居所或者营业所的外国人、外国企业或者外国其他组织根据本办法办理相关事务的，应当委托依法设立的专利代理机构办理。"},{"i":4,"n":"第四条","txt":"专利申请人依照专利法实施细则第二十四条提交生物材料保藏时，应当向保藏单位提交该生物材料，并附具保藏请求书写明下列事项： （一） 请求保藏的生物材料是用于专利程序的目的，并保证在本办法第九条规定的保藏期间内不撤回该保藏； （二） 专利申请人的姓名或者名称和地址； （三） 详细叙述该生物材料的培养、保藏和进行存活性检验所需的条件；保藏两种以上生物材料的混合培养物时，应当说明其组分以及至少一种能检查各个组分存在的方法； （四） 专利申请人给予该生物材料的识别符号，以及对该生物材料的分类命名或者科学描述； （五） 写明生物材料具有或者可能具有危及健康或者环境的特性，或者写明专利申请人不知道该生物材料具有此种特性。"},{"i":5,"n":"第五条","txt":"保藏单位对请求保藏的生物材料的生物特性不承担复核的义务。专利申请人要求对该生物材料的生物特性和分类命名进行复核检验的，应当在提交保藏生物材料时与保藏单位另行签订合同。"},{"i":6,"n":"第六条","txt":"保藏单位收到生物材料和保藏请求书后，应当向专利申请人出具经保藏单位盖章和负责人签字的书面保藏证明。保藏证明应当包括下列各项： （一） 保藏单位的名称和地址； （二） 专利申请人的姓名或者名称和地址； （三） 收到生物材料的日期； （四） 专利申请人给予该生物材料的识别符号，以及对该生物材料的分类命名或者科学描述； （五） 保藏单位给予的保藏编号。"},{"i":7,"n":"第七条","txt":"有下列情形之一的，保藏单位对生物材料不予保藏，并应当通知专利申请人： （一）该生物材料不属于保藏单位接受保藏的生物材料种类； （二）该生物材料的性质特殊，保藏单位的技术条件无法进行保藏； （三）保藏单位在收到保藏请求时，有其他理由无法接受该生物材料。"},{"i":8,"n":"第八条","txt":"保藏单位收到生物材料以及保藏请求后应当及时进行存活性检验，并向专利申请人出具经保藏单位盖章和负责人签字的书面存活证明。存活证明应当记载该生物材料是否存活，并应当包括下列各项： （一）保藏单位的名称和地址； （二）专利申请人的姓名或者名称和地址； （三）收到生物材料的日期； （四）保藏单位给予的保藏编号； （五）存活性检验的日期。 在保藏期间内，应专利申请人或者专利权人随时提出的请求，保藏单位应当对该生物材料进行存活性检验并向其出具经保藏单位盖章和负责人签字的书面存活证明。"},{"i":9,"n":"第九条","txt":"用于专利程序的生物材料的保藏期限至少30年，自保藏单位收到生物材料之日起计算。保藏单位在保藏期限届满前收到提供生物材料样品请求的，自请求日起至少应当再保藏5年。在保藏期间内，保藏单位应当采取一切必要的措施保持其保藏的生物材料存活和不受污染。"},{"i":10,"n":"第十条","txt":"涉及保藏的生物材料的专利申请公布前，保藏单位对其保藏的生物材料以及相关信息负有保密责任，不得向任何第三方提供该生物材料的样品和信息。"},{"i":11,"n":"第十一条","txt":"生物材料在保藏期间内发生死亡或者污染等情况的，保藏单位应当及时通知专利申请人或者专利权人。专利申请人或者专利权人在收到上述通知之日起4个月内重新提交与原保藏的生物材料相同的生物材料的，保藏单位予以继续保藏。"},{"i":12,"n":"第十二条","txt":"在保藏期间内，应保藏生物材料的专利申请人或者专利权人或者经其允许的任何单位或者个人的请求，保藏单位应当向其提供该生物材料的样品。 专利申请权或者专利权发生转让的，请求提供生物材料样品的权利以及允许他人获得生物材料样品的权利一并转让。 专利申请权或者专利权发生转让的，受让人应当及时通知保藏单位该专利申请权或者专利权的转让情况。"},{"i":13,"n":"第十三条","txt":"《国际承认用于专利程序的微生物保藏布达佩斯条约》缔约方专利局正在审查的专利申请或者已经授予的专利权涉及保藏单位所保藏的生物材料，该专利局为其专利程序的目的要求保藏单位提供该生物材料样品的，保藏单位应当向其提供。"},{"i":14,"n":"第十四条","txt":"国家知识产权局收到请求人依照专利法实施细则第二十五条提出的请求后，应当核实下列事项： （一）涉及该保藏生物材料的专利申请已经向国家知识产权局提交，并且该申请的主题包括该生物材料或者其利用； （二）所述专利申请已经公布或者授权； （三）请求人已经按照专利法实施细则第二十五条的规定作出保证。 国家知识产权局应当将该请求和有关文件的副本转送专利申请人或者专利权人，要求其在指定期限内就是否同意向请求人提供样品提出意见。专利申请人或者专利权人不同意向请求人提供样品的，应当说明理由并提交必要的证据；逾期不提出意见的，视为同意向请求人提供样品。 国家知识产权局应当综合考虑核实的情况以及专利申请人或者专利权人提出的意见，确定是否向请求人出具其有权获得生物材料样品的证明。"},{"i":15,"n":"第十五条","txt":"除本办法第十二条和第十三条规定的情形外，请求提供生物材料样品的单位或者个人向保藏单位提交提供样品请求书以及国家知识产权局根据本办法第十四条所出具的证明的，保藏单位应当向其提供生物材料样品。"},{"i":16,"n":"第十六条","txt":"保藏单位依照本办法提供生物材料样品，获得生物材料样品的人使用生物材料样品的，还应当遵守国家有关生物安全、出入境管理等法律法规的规定。"},{"i":17,"n":"第十七条","txt":"保藏单位依照本办法向专利申请人或者专利权人之外的其他单位或者个人提供生物材料样品的，应当及时通知专利申请人或者专利权人。"},{"i":18,"n":"第十八条","txt":"自本办法第九条规定的保藏期限届满之日起1年内，专利申请人或者专利权人可以取回所保藏的生物材料或者与保藏单位协商处置该生物材料。专利申请人或者专利权人在该期限内不取回也不进行处置的，保藏单位有权处置该生物材料。"},{"i":19,"n":"第十九条","txt":"保藏单位确定的接受保藏的生物材料种类以及收费标准应当予以公布，并报国家知识产权局备案。"},{"i":20,"n":"第二十条","txt":"本办法自2015年3月1日起施行。1985年3月12日中华人民共和国专利局公告第八号发布的《中国微生物菌种保藏管理委员会普通微生物中心用于专利程序的微生物保藏办法》和《中国典型培养物中心用于专利程序的微生物保藏办法》同时废止。"}],"biaogegeshihedaimabiaozhundi1bufen":[],"biaogegeshihedaimabiaozhun":[],"guifanshangbiaoshenqingzhucexingweiruoganguiding-2":[{"i":1,"n":"第一条","txt":"为了规范商标申请注册行为，规制恶意商标申请，维护商标注册管理秩序，保护社会公共利益，根据《中华人民共和国商标法》（以下简称商标法）和《中华人民共和国商标法实施条例》（以下简称商标法实施条例），制定本规定。"},{"i":2,"n":"第二条","txt":"申请商标注册，应当遵守法律、行政法规和部门规章的规定，具有取得商标专用权的实际需要。"},{"i":3,"n":"第三条","txt":"申请商标注册应当遵循诚实信用原则。不得有下列行为： （一）属于商标法第四条规定的不以使用为目的恶意申请商标注册的； （二）属于商标法第十三条规定，复制、摹仿或者翻译他人驰名商标的； （三）属于商标法第十五条规定，代理人、代表人未经授权申请注册被代理人或者被代表人商标的；基于合同、业务往来关系或者其他关系明知他人在先使用的商标存在而申请注册该商标的； （四）属于商标法第三十二条规定，损害他人现有的在先权利或者以不正当手段抢先注册他人已经使用并有一定影响的商标的； （五）以欺骗或者其他不正当手段申请商标注册的； （六）其他违反诚实信用原则，违背公序良俗，或者有其他不良影响的。"},{"i":4,"n":"第四条","txt":"商标代理机构应当遵循诚实信用原则。知道或者应当知道委托人申请商标注册属于下列情形之一的，不得接受其委托： （一）属于商标法第四条规定的不以使用为目的恶意申请商标注册的； （二）属于商标法第十五条规定的； （三）属于商标法第三十二条规定的。 商标代理机构除对其代理服务申请商标注册外，不得申请注册其他商标，不得以不正当手段扰乱商标代理市场秩序。"},{"i":5,"n":"第五条","txt":"对申请注册的商标，商标注册部门发现属于违反商标法第四条规定的不以使用为目的的恶意商标注册申请，应当依法驳回，不予公告。 具体审查规程由商标注册部门根据商标法和商标法实施条例另行制定。"},{"i":6,"n":"第六条","txt":"对初步审定公告的商标，在公告期内，因违反本规定的理由被提出异议的，商标注册部门经审查认为异议理由成立，应当依法作出不予注册决定。 对申请驳回复审和不予注册复审的商标，商标注册部门经审理认为属于违反本规定情形的，应当依法作出驳回或者不予注册的决定。"},{"i":7,"n":"第七条","txt":"对已注册的商标，因违反本规定的理由，在法定期限内被提出宣告注册商标无效申请的，商标注册部门经审理认为宣告无效理由成立，应当依法作出宣告注册商标无效的裁定。 对已注册的商标，商标注册部门发现属于违反本规定情形的，应当依据商标法第四十四条规定，宣告该注册商标无效。"},{"i":8,"n":"第八条","txt":"商标注册部门在判断商标注册申请是否属于违反商标法第四条规定时，可以综合考虑以下因素： （一）申请人或者与其存在关联关系的自然人、法人、其他组织申请注册商标数量、指定使用的类别、商标交易情况等； （二）申请人所在行业、经营状况等； （三）申请人被已生效的行政决定或者裁定、司法判决认定曾从事商标恶意注册行为、侵犯他人注册商标专用权行为的情况； （四）申请注册的商标与他人有一定知名度的商标相同或者近似的情况； （五）申请注册的商标与知名人物姓名、企业字号、企业名称简称或者其他商业标识等相同或者近似的情况； （六）商标注册部门认为应当考虑的其他因素。"},{"i":9,"n":"第九条","txt":"商标转让情况不影响商标注册部门对违反本规定第三条情形的认定。"},{"i":10,"n":"第十条","txt":"注册商标没有正当理由连续三年不使用的，任何单位或者个人可以向商标注册部门申请撤销该注册商标。商标注册部门受理后应当通知商标注册人，限其自收到通知之日起两个月内提交该商标在撤销申请提出前使用的证据材料或者说明不使用的正当理由；期满未提供使用的证据材料或者证据材料无效并没有正当理由的，由商标注册部门撤销其注册商标。"},{"i":11,"n":"第十一条","txt":"商标注册部门作出本规定第五条、第六条、第七条所述决定或者裁定后，予以公布。"},{"i":12,"n":"第十二条","txt":"对违反本规定第三条恶意申请商标注册的申请人，依据商标法第六十八条第四款的规定，由申请人所在地或者违法行为发生地县级以上市场监督管理部门根据情节给予警告、罚款等行政处罚。有违法所得的，可以处违法所得三倍最高不超过三万元的罚款；没有违法所得的，可以处一万元以下的罚款。"},{"i":13,"n":"第十三条","txt":"对违反本规定第四条的商标代理机构，依据商标法第六十八条的规定，由行为人所在地或者违法行为发生地县级以上市场监督管理部门责令限期改正，给予警告，处一万元以上十万元以下的罚款；对直接负责的主管人员和其他直接责任人员给予警告，处五千元以上五万元以下的罚款；构成犯罪的，依法追究刑事责任。情节严重的，知识产权管理部门可以决定停止受理该商标代理机构办理商标代理业务，予以公告。"},{"i":14,"n":"第十四条","txt":"作出行政处罚决定的政府部门应当依法将处罚信息通过国家企业信用信息公示系统向社会公示。"},{"i":15,"n":"第十五条","txt":"对违反本规定第四条的商标代理机构，由知识产权管理部门对其负责人进行整改约谈。"},{"i":16,"n":"第十六条","txt":"知识产权管理部门、市场监督管理部门应当积极引导申请人依法申请商标注册、商标代理机构依法从事商标代理业务，规范生产经营活动中使用注册商标的行为。 知识产权管理部门应当进一步畅通商标申请渠道、优化商标注册流程，提升商标公共服务水平，为申请人直接申请注册商标提供便利化服务。"},{"i":17,"n":"第十七条","txt":"知识产权管理部门应当健全内部监督制度，对从事商标注册工作的国家机关工作人员执行法律、行政法规和遵守纪律的情况加强监督检查。 从事商标注册工作的国家机关工作人员玩忽职守、滥用职权、徇私舞弊，违法办理商标注册事项，收受当事人财物，牟取不正当利益的，应当依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":18,"n":"第十八条","txt":"商标代理行业组织应当完善行业自律规范，加强行业自律，对违反行业自律规范的会员实行惩戒，并及时向社会公布。"},{"i":19,"n":"第十九条","txt":"本规定自2019年12月1日起施行。"}],"caiyonggonglibiaoshiriqideguifan":[],"caiyonggonglibiaoshiriqideguifan-2":[],"jitishangbiaozhengmingshangbiaozhuceheguanlibanfa-2":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国商标法》（以下简称商标法）第三条的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"集体商标、证明商标的注册和管理，依照商标法、《中华人民共和国商标法实施条例》（以下简称实施条例）和本办法的有关规定进行。"},{"i":3,"n":"第三条","txt":"本办法有关商品的规定，适用于服务。"},{"i":4,"n":"第四条","txt":"申请集体商标注册的，应当附送主体资格证明文件并应当详细说明该集体组织成员的名称和地址；以地理标志作为集体商标申请注册的，应当附送主体资格证明文件并应当详细说明其所具有的或者其委托的机构具有的专业技术人员、专业检测设备等情况，以表明其具有监督使用该地理标志商品的特定品质的能力。 申请以地理标志作为集体商标注册的团体、协会或者其他组织，应当由来自该地理标志标示的地区范围内的成员组成。"},{"i":5,"n":"第五条","txt":"申请证明商标注册的，应当附送主体资格证明文件并应当详细说明其所具有的或者其委托的机构具有的专业技术人员、专业检测设备等情况，以表明其具有监督该证明商标所证明的特定商品品质的能力。"},{"i":6,"n":"第六条","txt":"申请以地理标志作为集体商标、证明商标注册的，还应当附送管辖该地理标志所标示地区的人民政府或者行业主管部门的批准文件。 外国人或者外国企业申请以地理标志作为集体商标、证明商标注册的，申请人应当提供该地理标志以其名义在其原属国受法律保护的证明。"},{"i":7,"n":"第七条","txt":"以地理标志作为集体商标、证明商标注册的，应当在申请书件中说明下列内容： （一）该地理标志所标示的商品的特定质量、信誉或者其他特征； （二）该商品的特定质量、信誉或者其他特征与该地理标志所标示的地区的自然因素和人文因素的关系； （三）该地理标志所标示的地区的范围。"},{"i":8,"n":"第八条","txt":"作为集体商标、证明商标申请注册的地理标志，可以是该地理标志标示地区的名称，也可以是能够标示某商品来源于该地区的其他可视性标志。 前款所称地区无需与该地区的现行行政区划名称、范围完全一致。"},{"i":9,"n":"第九条","txt":"多个葡萄酒地理标志构成同音字或者同形字的，在这些地理标志能够彼此区分且不误导公众的情况下，每个地理标志都可以作为集体商标或者证明商标申请注册。"},{"i":10,"n":"第十条","txt":"集体商标的使用管理规则应当包括： （一）使用集体商标的宗旨； （二）使用该集体商标的商品的品质； （三）使用该集体商标的手续； （四）使用该集体商标的权利、义务； （五）成员违反其使用管理规则应当承担的责任； （六）注册人对使用该集体商标商品的检验监督制度。"},{"i":11,"n":"第十一条","txt":"证明商标的使用管理规则应当包括： （一）使用证明商标的宗旨； （二）该证明商标证明的商品的特定品质； （三）使用该证明商标的条件； （四）使用该证明商标的手续； （五）使用该证明商标的权利、义务； （六）使用人违反该使用管理规则应当承担的责任； （七）注册人对使用该证明商标商品的检验监督制度。"},{"i":12,"n":"第十二条","txt":"使用他人作为集体商标、证明商标注册的葡萄酒、烈性酒地理标志标示并非来源于该地理标志所标示地区的葡萄酒、烈性酒，即使同时标出了商品的真正来源地，或者使用的是翻译文字，或者伴有诸如某某“种”、某某“型”、某某“式”、某某“类”等表述的，适用商标法第十六条的规定。"},{"i":13,"n":"第十三条","txt":"集体商标、证明商标的初步审定公告的内容，应当包括该商标的使用管理规则的全文或者摘要。 集体商标、证明商标注册人对使用管理规则的任何修改，应报经商标局审查核准，并自公告之日起生效。"},{"i":14,"n":"第十四条","txt":"集体商标注册人的成员发生变化的，注册人应当向商标局申请变更注册事项，由商标局公告。"},{"i":15,"n":"第十五条","txt":"证明商标注册人准许他人使用其商标的，注册人应当在一年内报商标局备案，由商标局公告。"},{"i":16,"n":"第十六条","txt":"申请转让集体商标、证明商标的，受让人应当具备相应的主体资格，并符合商标法、实施条例和本办法的规定。 集体商标、证明商标发生移转的，权利继受人应当具备相应的主体资格，并符合商标法、实施条例和本办法的规定。"},{"i":17,"n":"第十七条","txt":"集体商标注册人的集体成员，在履行该集体商标使用管理规则规定的手续后，可以使用该集体商标。 集体商标不得许可非集体成员使用。"},{"i":18,"n":"第十八条","txt":"凡符合证明商标使用管理规则规定条件的，在履行该证明商标使用管理规则规定的手续后，可以使用该证明商标，注册人不得拒绝办理手续。 实施条例第六条第二款中的正当使用该地理标志是指正当使用该地理标志中的地名。"},{"i":19,"n":"第十九条","txt":"使用集体商标的，注册人应发给使用人《集体商标使用证》；使用证明商标的，注册人应发给使用人《证明商标使用证》。"},{"i":20,"n":"第二十条","txt":"证明商标的注册人不得在自己提供的商品上使用该证明商标。"},{"i":21,"n":"第二十一条","txt":"集体商标、证明商标注册人没有对该商标的使用进行有效管理或者控制，致使该商标使用的商品达不到其使用管理规则的要求，对消费者造成损害的，由工商行政管理部门责令限期改正；拒不改正的，处以违法所得三倍以下的罚款，但最高不超过三万元；没有违法所得的，处以一万元以下的罚款。"},{"i":22,"n":"第二十二条","txt":"违反实施条例第六条、本办法第十四条、第十五条、第十七条、第十八条、第二十条规定的，由工商行政管理部门责令限期改正；拒不改正的，处以违法所得三倍以下的罚款，但最高不超过三万元；没有违法所得的，处以一万元以下的罚款。"},{"i":23,"n":"第二十三条","txt":"本办法自2003年6月1日起施行。国家工商行政管理局1994年12月30日发布的《集体商标、证明商标注册和管理办法》同时废止。"}],"jichengdianlubutushejibaohutiaolishishixize-2":[{"i":1,"n":"第一条","txt":"宗旨 为了保护集成电路布图设计（以下简称布图设计）专有权，促进我国集成电路技术的进步与创新，根据《集成电路布图设计保护条例》（以下简称条例），制定本实施细则（以下简称本细则）。"},{"i":2,"n":"第二条","txt":"登记机构 条例所称的国务院知识产权行政部门是指国家知识产权局。"},{"i":3,"n":"第三条","txt":"办理手续需用的形式 条例和本细则规定的各种文件，应当以书面形式或者以国家知识产权局规定的其他形式办理。"},{"i":4,"n":"第四条","txt":"代理机构 中国单位或者个人在国内申请布图设计登记和办理其他与布图设计有关的事务的，可以委托专利代理机构办理。 在中国没有经常居所或者营业所的外国人、外国企业或者外国其他组织在中国申请布图设计登记和办理其他与布图设计有关的事务的，应当委托国家知识产权局指定的专利代理机构办理。"},{"i":5,"n":"第五条","txt":"申请文件和申请日的确定 向国家知识产权局申请布图设计登记的，应当提交布图设计登记申请表和该布图设计的复制件或者图样；布图设计在申请日以前已投入商业利用的，还应当提交含有该布图设计的集成电路样品。 国家知识产权局收到前款所述布图设计申请文件之日为申请日。如果申请文件是邮寄的，以寄出的邮戳日为申请日。"},{"i":6,"n":"第六条","txt":"文件的语言 依照条例和本细则规定提交的各种文件应当使用中文。国家有统一规定的科技术语的，应当采用规范词；外国人名、地名和科技术语没有统一中文译文的，应当注明原文。 依照条例和本细则规定提交的各种证件和证明文件是外文的，国家知识产权局认为必要时，可以要求当事人在指定期限内附送中文译文；期满未附送的，视为未提交该证件和证明文件。"},{"i":7,"n":"第七条","txt":"文件的递交和送达 向国家知识产权局邮寄的各种文件，以寄出的邮戳日为递交日。邮戳日不清晰的，除当事人能够提出证明外，以国家知识产权局收到文件之日为递交日。 国家知识产权局的各种文件，可以通过邮寄、直接送交或者其他方式送达当事人。当事人委托专利代理机构的，文件送交专利代理机构；未委托专利代理机构的，文件送交申请表中指明的联系人。 国家知识产权局邮寄的各种文件，自文件发出之日起满15日，推定为当事人收到文件之日。 根据国家知识产权局规定应当直接送交的文件，以交付日为送达日。 文件送交地址不清，无法邮寄的，可以通过公告的方式送达当事人。自公告之日起满1个月，该文件视为已经送达。"},{"i":8,"n":"第八条","txt":"期限的计算 条例和本细则规定的各种期限的第一日不计算在期限内。期限以年或者月计算的，以其最后一月的相应日为期限届满日；该月无相应日的，以该月最后一日为期限届满日。 期限届满日是法定节假日的，以节假日后的第一个工作日为期限届满日。"},{"i":9,"n":"第九条","txt":"权利的恢复和期限的延长 当事人因不可抗拒的事由而耽误本细则规定的期限或者国家知识产权局指定的期限，造成其权利丧失的，自障碍消除之日起2个月内，但是最迟自期限届满之日起2年内，可以向国家知识产权局说明理由并附具有关证明文件，请求恢复其权利。 当事人因正当理由而耽误本细则规定的期限或者国家知识产权局指定的期限，造成其权利丧失的，可以自收到国家知识产权局的通知之日起2个月内向国家知识产权局说明理由，请求恢复其权利。 当事人请求延长国家知识产权局指定的期限的，应当在期限届满前，向国家知识产权局说明理由并办理有关手续。 条例规定的期限不得请求延长。"},{"i":10,"n":"第十条","txt":"共有 布图设计是2个以上单位或者个人合作创作的，创作者应当共同申请布图设计登记；有合同约定的，从其约定。 涉及共有的布图设计专有权的，每一个共同布图设计权利人在没有征得其他共同布图设计权利人同意的情况下，不得将其所持有的那一部分权利进行转让、出质或者与他人订立独占许可合同或者排他许可合同。"},{"i":11,"n":"第十一条","txt":"向外国人转让专有权 中国单位或者个人向外国人转让布图设计专有权的，在向国家知识产权局办理转让登记时应当提交国务院有关主管部门允许其转让的证明文件。 布图设计专有权发生转移的，当事人应当凭有关证明文件或者法律文书向国家知识产权局办理著录项目变更手续。"},{"i":12,"n":"第十二条","txt":"申请文件 以书面形式申请布图设计登记的，应当向国家知识产权局提交布图设计登记申请表一式两份以及一份布图设计的复制件或者图样。 以国家知识产权局规定的其他形式申请布图设计登记的，应当符合规定的要求。 申请人委托专利代理机构向国家知识产权局申请布图设计登记和办理其他手续的，应当同时提交委托书，写明委托权限。 申请人有2个以上且未委托专利代理机构的，除申请表中另有声明外，以申请表中指明的第一申请人为代表人。"},{"i":13,"n":"第十三条","txt":"申请表 布图设计登记申请表应当写明下列各项： （一）申请人的姓名或者名称、地址或者居住地； （二）申请人的国籍； （三）布图设计的名称； （四）布图设计创作者的姓名或者名称； （五）布图设计的创作完成日期； （六）该布图设计所用于的集成电路的分类； （七）申请人委托专利代理机构的，应当注明的有关事项；申请人未委托专利代理机构的，其联系人的姓名、地址、邮政编码及联系电话； （八）布图设计有条例第十七条所述商业利用行为的，该行为的发生日； （九）布图设计登记申请有保密信息的，含有该保密信息的图层的复制件或者图样页码编号及总页数； （十）申请人或者专利代理机构的签字或者盖章； （十一）申请文件清单； （十二）附加文件及样品清单； （十三）其他需要注明的事项。"},{"i":14,"n":"第十四条","txt":"复制件或者图样 按照条例第十六条规定提交的布图设计的复制件或者图样应当符合下列要求： （一）复制件或者图样的纸件应当至少放大到用该布图设计生产的集成电路的20倍以上；申请人可以同时提供该复制件或者图样的电子版本；提交电子版本的复制件或者图样的，应当包含该布图设计的全部信息，并注明文件的数据格式； （二）复制件或者图样有多张纸件的，应当顺序编号并附具目录； （三）复制件或者图样的纸件应当使用A4纸格式；如果大于A4纸的，应当折叠成A4纸格式； （四）复制件或者图样可以附具简单的文字说明，说明该集成电路布图设计的结构、技术、功能和其他需要说明的事项。"},{"i":15,"n":"第十五条","txt":"涉及保密信息的申请 布图设计在申请日之前没有投入商业利用的，该布图设计登记申请可以有保密信息，其比例最多不得超过该集成电路布图设计总面积的50%。含有保密信息的图层的复制件或者图样页码编号及总页数应当与布图设计登记申请表中所填写的一致。 布图设计登记申请有保密信息的，含有该保密信息的图层的复制件或者图样纸件应当置于在另一个保密文档袋中提交。除侵权诉讼或者行政处理程序需要外，任何人不得查阅或者复制该保密信息。"},{"i":16,"n":"第十六条","txt":"集成电路样品 布图设计在申请日之前已投入商业利用的，申请登记时应当提交4件含有该布图设计的集成电路样品，并应当符合下列要求： （一）所提交的4件集成电路样品应当置于能保证其不受损坏的专用器具中，并附具填写好的国家知识产权局统一编制的表格； （二）器具表面应当写明申请人的姓名、申请号和集成电路名称； （三）器具中的集成电路样品应当采用适当的方式固定，不得有损坏，并能够在干燥器中至少存放十年。"},{"i":17,"n":"第十七条","txt":"不予受理 布图设计登记申请有下列情形的，国家知识产权局不予受理，并通知申请人： （一）未提交布图设计登记申请表或者布图设计的复制件或者图样的，已投入商业利用而未提交集成电路样品的，或者提交的上述各项不一致的； （二）外国申请人的所属国未与中国签订有关布图设计保护协议或者与中国共同参加有关国际条约； （三）所涉及的布图设计属于条例第十二条规定不予保护的； （四）所涉及的布图设计属于条例第十七条规定不予登记的； （五）申请文件未使用中文的； （六）申请类别不明确或者难以确定其属于布图设计的； （七）未按规定委托代理机构的； （八）布图设计登记申请表填写不完整的。"},{"i":18,"n":"第十八条","txt":"文件的补正和修改 除本细则第十七条规定不予受理的外，申请文件不符合条例和本细则规定的条件的，申请人应当在收到国家知识产权局的审查意见通知之日起2个月内进行补正。补正应当按照审查意见通知书的要求进行。逾期未答复的，该申请视为撤回。 申请人按照国家知识产权局的审查意见补正后，申请文件仍不符合条例和本细则的规定的，国家知识产权局应当作出驳回决定。 国家知识产权局可以自行修改布图设计申请文件中文字和符号的明显错误。国家知识产权局自行修改的，应当通知申请人。"},{"i":19,"n":"第十九条","txt":"申请的驳回 除本细则第十八条第二款另有规定的外，申请登记的布图设计有下列各项之一的，国家知识产权局应当作出驳回决定，写明所依据的理由： （一）明显不符合条例第二条第（一）、（二）项规定的； （二）明显不符合条例第五条规定的。"},{"i":20,"n":"第二十条","txt":"布图设计专有权的生效 布图设计登记申请经初步审查没有发现驳回理由的，国家知识产权局应当颁发布图设计登记证书，并在国家知识产权局互联网站和中国知识产权报上予以公告。布图设计专有权自申请日起生效。"},{"i":21,"n":"第二十一条","txt":"登记证书 国家知识产权局颁发的布图设计登记证书应当包括下列各项： （一）布图设计权利人的姓名或者名称和地址； （二）布图设计的名称； （三）布图设计在申请日之前已经投入商业利用的，其首次商业利用的时间； （四）布图设计的申请日及创作完成日； （五）布图设计的颁证日期； （六）布图设计的登记号； （七）国家知识产权局的印章及负责人签字。"},{"i":22,"n":"第二十二条","txt":"更正 国家知识产权局对布图设计公告中出现的错误，一经发现，应当及时更正，并对所作更正予以公告。"},{"i":23,"n":"第二十三条","txt":"复审和撤销机构 国家知识产权局专利复审委员会（以下简称专利复审委员会）负责对国家知识产权局驳回布图设计登记申请决定不服而提出的复审请求的审查，以及负责对布图设计专有权撤销案件的审查。"},{"i":24,"n":"第二十四条","txt":"复审的请求 向专利复审委员会请求复审的，应当提交复审请求书，说明理由，必要时还应当附具有关证据。复审请求书不符合条例第十九条有关规定的，专利复审委员会不予受理。 复审请求不符合规定格式的，复审请求人应当在专利复审委员会指定的期限内补正；期满未补正的，该复审请求视为未提出。"},{"i":25,"n":"第二十五条","txt":"复审程序中文件的修改 复审请求人在提出复审请求或者在对专利复审委员会的复审通知书作出答复时，可以修改布图设计申请文件；但是修改应当仅限于消除驳回决定或者复审通知书指出的缺陷。 修改的申请文件应当提交一式两份。"},{"i":26,"n":"第二十六条","txt":"复审决定 专利复审委员会进行审查后，认为布图设计登记申请的复审请求不符合条例或者本细则有关规定的，应当通知复审请求人，要求其在指定期限内陈述意见。期满未答复的，该复审请求视为撤回；经陈述意见或者进行修改后，专利复审委员会认为该申请仍不符条例和本细则有关规定的，应当作出维持原驳回决定的复审决定。 专利复审委员会进行复审后，认为原驳回决定不符合条例和本细则有关规定的，或者认为经过修改的申请文件消除了原驳回决定指出的缺陷的，应当撤销原驳回决定，通知原审查部门对该申请予以登记和公告。 专利复审委员会的复审决定，应当写明复审决定的理由，并通知布图设计登记申请人。"},{"i":27,"n":"第二十七条","txt":"复审请求的撤回 复审请求人在专利复审委员会作出决定前，可以撤回其复审请求。 复审请求人在专利复审委员会作出决定前撤回其复审请求的，复审程序终止。"},{"i":28,"n":"第二十八条","txt":"复议请求 当事人对国家知识产权局作出的下列具体行政行为不服或者有争议的，可以向国家知识产权局行政复议部门申请复议： （一）不予受理布图设计申请的； （二）将布图设计申请视为撤回的； （三）不允许恢复有关权利的请求的； （四）其他侵犯当事人合法权益的具体行政行为。"},{"i":29,"n":"第二十九条","txt":"撤销程序 布图设计登记公告后，发现登记的布图设计专有权不符合集成电路布图设计保护条例第二条第（一）、（二）项、第三条、第四条、第五条、第十二条或者第十七条规定的，由专利复审委员会撤销该布图设计专有权。 撤销布图设计专有权的，应当首先通知该布图设计权利人，要求其在指定期限内陈述意见。期满未答复的，不影响专利复审委员会作出撤销布图设计专有权的决定。 专利复审委员会撤销布图设计专有权的决定应当写明所依据的理由，并通知该布图设计权利人。"},{"i":30,"n":"第三十条","txt":"撤销决定的公告 对专利复审委员会撤销布图设计专有权的决定未在规定期限内向人民法院起诉，或者在人民法院维持专利复审委员会撤销布图设计专有权决定的判决生效后，国家知识产权局应当将撤销该布图设计专有权的决定在国家知识产权局互联网站和中国知识产权报上公告。 被撤销的布图设计专有权视为自始即不存在。"},{"i":31,"n":"第三十一条","txt":"布图设计专有权的放弃 布图设计权利人在其布图设计专有权保护期届满之前，可以向国家知识产权局提交书面声明放弃该专有权。 布图设计专有权已许可他人实施或者已经出质的，该布图设计专有权的放弃应当征得被许可人或质权人的同意。 布图设计专有权的放弃应当由国家知识产权局登记和公告。"},{"i":32,"n":"第三十二条","txt":"国家知识产权局受理侵权纠纷案件的条件 根据条例第三十一条的规定请求国家知识产权局处理布图设计专有权侵权纠纷的，应当符合下列条件： （一）该布图设计已登记、公告； （二）请求人是布图设计权利人或者与该侵权纠纷有直接利害关系的单位或者个人； （三）有明确的被请求人； （四）有明确的请求事项和具体的事实、理由； （五）当事人任何一方均未就该侵权纠纷向人民法院起诉。"},{"i":33,"n":"第三十三条","txt":"有关程序的中止和恢复 当事人因布图设计申请权或者布图设计专有权的归属发生纠纷，已经向人民法院起诉的，可以请求国家知识产权局中止有关程序。 依照前款规定请求中止有关程序的，应当向国家知识产权局提交请求书，并附具人民法院的有关受理文件副本。 在人民法院作出的判决生效后，当事人应当向国家知识产权局办理恢复有关程序的手续。自请求中止之日起一年内，有关布图设计申请权或者布图设计专有权归属的纠纷未能结案，需要继续中止有关程序的，请求人应当在该期限内请求延长中止。期满未请求延长的，国家知识产权局自行恢复有关程序。 人民法院在审理民事案件中裁定对布图设计专有权采取保全措施的，国家知识产权局在协助执行时中止被保全的布图设计专有权的有关程序。保全期限届满，人民法院没有裁定继续采取保全措施的，国家知识产权局自行恢复有关程序。"},{"i":34,"n":"第三十四条","txt":"应缴纳的费用 向国家知识产权局申请布图设计登记和办理其他手续时，应当缴纳下列费用： （一）布图设计登记费； （二）著录事项变更手续费、延长期限请求费、恢复权利请求费； （三）复审请求费； （四）非自愿许可许可请求费、非自愿许可使用费的裁决请求费。 前款所列各种费用的数额，由国务院价格管理部门会同国家知识产权局另行规定。"},{"i":35,"n":"第三十五条","txt":"缴费手续 条例和本细则规定的各种费用，可以直接向国家知识产权局缴纳，也可以通过邮局或者银行汇付，或者以国家知识产权局规定的其他方式缴纳。 通过邮局或者银行汇付的，应当在送交国家知识产权局的汇单上至少写明正确的申请号以及缴纳的费用名称。不符合本款规定的，视为未办理缴费手续。 直接向国家知识产权局缴纳费用的，以缴纳当日为缴费日；以邮局汇付方式缴纳费用的，以邮局汇出的邮戳日为缴费日；以银行汇付方式缴纳费用的，以银行实际汇出日为缴费日。但是自汇出日至国家知识产权局收到日超过15日的，除邮局或者银行出具证明外，以国家知识产权局收到日为缴费日。 多缴、重缴、错缴布图设计登记费用的，当事人可以向国家知识产权局提出退款请求，但是该请求应当自缴费日起一年内提出。"},{"i":36,"n":"第三十六条","txt":"缴费期限 申请人应当在收到受理通知书后2个月内缴纳布图设计登记费；期满未缴纳或者未缴足的，其申请视为撤回。 当事人请求恢复权利或者复审的，应当在条例及本细则规定的相关期限内缴纳费用；期满未缴纳或者未缴足的，视为未提出请求。 著录事项变更手续费、非自愿许可请求费、非自愿许可使用费的裁决请求费应当自提出请求之日起1个月内缴纳；延长期限请求费应当在相应期限届满前缴纳；期满未缴纳或者未缴足的，视为未提出请求。"},{"i":37,"n":"第三十七条","txt":"布图设计登记簿 国家知识产权局设置布图设计登记簿，登记下列事项： （一）布图设计权利人的姓名或者名称、国籍和地址及其变更； （二）布图设计的登记； （三）布图设计专有权的转移和继承； （四）布图设计专有权的放弃； （五）布图设计专有权的质押、保全及其解除； （六）布图设计专有权的撤销； （七）布图设计专有权的终止； （八）布图设计专有权的恢复； （九）布图设计专有权实施的非自愿许可。"},{"i":38,"n":"第三十八条","txt":"布图设计公告 国家知识产权局定期在国家知识产权局互联网站和中国知识产权报上登载布图设计登记公报，公布或者公告下列内容： （一）布图设计登记簿记载的著录事项； （二）对地址不明的当事人的通知； （三）国家知识产权局作出的更正； （四）其他有关事项。"},{"i":39,"n":"第三十九条","txt":"公众查阅和复制 布图设计登记公告后，公众可以请求查阅该布图设计登记簿或者请求国家知识产权局提供该登记簿的副本。公众也可以请求查阅该布图设计的复制件或者图样的纸件。 本细则第十四条所述的电子版本的复制件或者图样，除侵权诉讼或者行政处理程序需要外，任何人不得查阅或者复制。"},{"i":40,"n":"第四十条","txt":"失效案卷的处理 布图设计登记申请被撤回、视为撤回或者驳回的，以及布图设计专有权被声明放弃、撤销或者终止的，与该布图设计申请或者布图设计专有权有关的案卷，自该申请失效或者该专有权失效之日起满3年后不予保存。"},{"i":41,"n":"第四十一条","txt":"文件的邮寄 向国家知识产权局邮寄有关申请或者布图设计专有权的文件，应当使用挂号信函，一件信函应当只包含同一申请文件。电子版本的复制件或者图样和集成电路样品的邮寄方式应当保证其在邮寄过程中不受损坏。"},{"i":42,"n":"第四十二条","txt":"本细则的解释 本细则由国家知识产权局负责解释。"},{"i":43,"n":"第四十三条","txt":"本细则的实施日期 本细则自2001年10月1日起施行。"}],"jichengdianlubutushejibaohutiaolishishixize":[{"i":1,"n":"第一条","txt":"宗旨 为了保护集成电路布图设计（以下简称布图设计）专有权，促进我国集成电路技术的进步与创新，根据《集成电路布图设计保护条例》（以下简称条例），制定本实施细则（以下简称本细则）。"},{"i":2,"n":"第二条","txt":"登记机构 条例所称的国务院知识产权行政部门是指国家知识产权局。"},{"i":3,"n":"第三条","txt":"办理手续需用的形式 条例和本细则规定的各种文件，应当以书面形式或者以国家知识产权局规定的其他形式办理。"},{"i":4,"n":"第四条","txt":"代理机构 中国单位或者个人在国内申请布图设计登记和办理其他与布图设计有关的事务的，可以委托专利代理机构办理。 在中国没有经常居所或者营业所的外国人、外国企业或者外国其他组织在中国申请布图设计登记和办理其他与布图设计有关的事务的，应当委托国家知识产权局指定的专利代理机构办理。"},{"i":5,"n":"第五条","txt":"申请文件和申请日的确定 向国家知识产权局申请布图设计登记的，应当提交布图设计登记申请表和该布图设计的复制件或者图样；布图设计在申请日以前已投入商业利用的，还应当提交含有该布图设计的集成电路样品。 国家知识产权局收到前款所述布图设计申请文件之日为申请日。如果申请文件是邮寄的，以寄出的邮戳日为申请日。"},{"i":6,"n":"第六条","txt":"文件的语言 依照条例和本细则规定提交的各种文件应当使用中文。国家有统一规定的科技术语的，应当采用规范词；外国人名、地名和科技术语没有统一中文译文的，应当注明原文。 依照条例和本细则规定提交的各种证件和证明文件是外文的，国家知识产权局认为必要时，可以要求当事人在指定期限内附送中文译文；期满未附送的，视为未提交该证件和证明文件。"},{"i":7,"n":"第七条","txt":"文件的递交和送达 向国家知识产权局邮寄的各种文件，以寄出的邮戳日为递交日。邮戳日不清晰的，除当事人能够提出证明外，以国家知识产权局收到文件之日为递交日。 国家知识产权局的各种文件，可以通过邮寄、直接送交或者其他方式送达当事人。当事人委托专利代理机构的，文件送交专利代理机构；未委托专利代理机构的，文件送交申请表中指明的联系人。 国家知识产权局邮寄的各种文件，自文件发出之日起满１５日，推定为当事人收到文件之日。根据国家知识产权局规定应当直接送交的文件，以交付日为送达日。 文件送交地址不清，无法邮寄的，可以通过公告的方式送达当事人。自公告之日起满１个月，该文件视为已经送达。"},{"i":8,"n":"第八条","txt":"期限的计算 条例和本细则规定的各种期限的第一日不计算在期限内。期限以年或者月计算的，以其最后一月的相应日为期限届满日；该月无相应日的，以该月最后一日为期限届满日。 期限届满日是法定节假日的，以节假日后的第一个工作日为期限届满日。"},{"i":9,"n":"第九条","txt":"权利的恢复和期限的延长 当事人因不可抗拒的事由而耽误本细则规定的期限或者国家知识产权局指定的期限，造成其权利丧失的，自障碍消除之日起２个月内，但是最迟自期限届满之日起２年内，可以向国家知识产权局说明理由并附具有关证明文件，请求恢复其权利。 当事人因正当理由而耽误本细则规定的期限或者国家知识产权局指定的期限，造成其权利丧失的，可以自收到国家知识产权局的通知之日起２个月内向国家知识产权局说明理由，请求恢复其权利。 当事人请求延长国家知识产权局指定的期限的，应当在期限届满前，向国家知识产权局说明理由并办理有关手续。 条例规定的期限不得请求延长。"},{"i":10,"n":"第十条","txt":"共有 布图设计是２个以上单位或者个人合作创作的，创作者应当共同申请布图设计登记；有合同约定的，从其约定。 涉及共有的布图设计专有权的，每一个共同布图设计权利人在没有征得其他共同布图设计权利人同意的情况下，不得将其所持有的那一部分权利进行转让、出质或者与他人订立独占许可合同或者排他许可合同。"},{"i":11,"n":"第十一条","txt":"向外国人转让专有权 中国单位或者个人向外国人转让布图设计专有权的，在向国家知识产权局办理转让登记时应当提交国务院有关主管部门允许其转让的证明文件。 布图设计专有权发生转移的，当事人应当凭有关证明文件或者法律文书向国家知识产权局办理著录项目变更手续。"},{"i":12,"n":"第十二条","txt":"申请文件 以书面形式申请布图设计登记的，应当向国家知识产权局提交布图设计登记申请表一式两份以及一份布图设计的复制件或者图样。 以国家知识产权局规定的其他形式申请布图设计登记的，应当符合规定的要求。 申请人委托专利代理机构向国家知识产权局申请布图设计登记和办理其他手续的，应当同时提交委托书，写明委托权限。 申请人有２个以上且未委托专利代理机构的，除申请表中另有声明外，以申请表中指明的第一申请人为代表人。"},{"i":13,"n":"第十三条","txt":"申请表 布图设计登记申请表应当写明下列各项： （一）申请人的姓名或者名称、地址或者居住地； （二）申请人的国籍； （三）布图设计的名称； （四）布图设计创作者的姓名或者名称； （五）布图设计的创作完成日期； （六）该布图设计所用于的集成电路的分类； （七）申请人委托专利代理机构的，应当注明的有关事项；申请人未委托专利代理机构的，其联系人的姓名、地址、邮政编码及联系电话； （八）布图设计有条例第十七条所述商业利用行为的，该行为的发生日； （九）布图设计登记申请有保密信息的，含有该保密信息的图层的复制件或者图样页码编号及总页数； （十）申请人或者专利代理机构的签字或者盖章； （十一）申请文件清单； （十二）附加文件及样品清单； （十三）其他需要注明的事项。"},{"i":14,"n":"第十四条","txt":"复制件或者图样 按照条例第十六条规定提交的布图设计的复制件或者图样应当符合下列要求： （一）复制件或者图样的纸件应当至少放大到用该布图设计生产的集成电路的２０倍以上；申请人可以同时提供该复制件或者图样的电子版本；提交电子版本的复制件或者图样的，应当包含该布图设计的全部信息，并注明文件的数据格式； （二）复制件或者图样有多张纸件的，应当顺序编号并附具目录； （三）复制件或者图样的纸件应当使用Ａ４纸格式；如果大于Ａ４纸的，应当折叠成Ａ４纸格式； （四）复制件或者图样可以附具简单的文字说明，说明该集成电路布图设计的结构、技术、功能和其他需要说明的事项。"},{"i":15,"n":"第十五条","txt":"涉及保密信息的申请 布图设计在申请日之前没有投入商业利用的，该布图设计登记申请可以有保密信息，其比例最多不得超过该集成电路布图设计总面积的５０％。含有保密信息的图层的复制件或者图样页码编号及总页数应当与布图设计登记申请表中所填写的一致。 布图设计登记申请有保密信息的，含有该保密信息的图层的复制件或者图样纸件应当置于在另一个保密文档袋中提交。除侵权诉讼或者行政处理程序需要外，任何人不得查阅或者复制该保密信息。"},{"i":16,"n":"第十六条","txt":"集成电路样品 布图设计在申请日之前已投入商业利用的，申请登记时应当提交４件含有该布图设计的集成电路样品，并应当符合下列要求： （一）所提交的４件集成电路样品应当置于能保证其不受损坏的专用器具中，并附具填写好的国家知识产权局统一编制的表格； （二）器具表面应当写明申请人的姓名、申请号和集成电路名称； （三）器具中的集成电路样品应当采用适当的方式固定，不得有损坏，并能够在干燥器中至少存放十年。"},{"i":17,"n":"第十七条","txt":"不予受理 布图设计登记申请有下列情形的，国家知识产权局不予受理，并通知申请人： （一）未提交布图设计登记申请表或者布图设计的复制件或者图样的，已投入商业利用而未提交集成电路样品的，或者提交的上述各项不一致的； （二）外国申请人的所属国未与中国签订有关布图设计保护协议或者与中国共同参加有关国际条约； （三）所涉及的布图设计属于条例第十二条规定不予保护的； （四）所涉及的布图设计属于条例第十七条规定不予登记的； （五）申请文件未使用中文的； （六）申请类别不明确或者难以确定其属于布图设计的； （七）未按规定委托代理机构的； （八）布图设计登记申请表填写不完整的。"},{"i":18,"n":"第十八条","txt":"文件的补正和修改 除本细则第十七条规定不予受理的外，申请文件不符合条例和本细则规定的条件的，申请人应当在收到国家知识产权局的审查意见通知之日起２个月内进行补正。补正应当按照审查意见通知书的要求进行。逾期未答复的，该申请视为撤回。 申请人按照国家知识产权局的审查意见补正后，申请文件仍不符合条例和本细则的规定的，国家知识产权局应当作出驳回决定。 国家知识产权局可以自行修改布图设计申请文件中文字和符号的明显错误。国家知识产权局自行修改的，应当通知申请人。"},{"i":19,"n":"第十九条","txt":"申请的驳回 除本细则第十八条第二款另有规定的外，申请登记的布图设计有下列各项之一的，国家知识产权局应当作出驳回决定，写明所依据的理由： （一）明显不符合条例第二条第（一）、（二）项规定的； （二）明显不符合条例第五条规定的。"},{"i":20,"n":"第二十条","txt":"布图设计专有权的生效 布图设计登记申请经初步审查没有发现驳回理由的，国家知识产权局应当颁发布图设计登记证书，并在国家知识产权局互联网站和中国知识产权报上予以公告。布图设计专有权自申请日起生效。"},{"i":21,"n":"第二十一条","txt":"登记证书 国家知识产权局颁发的布图设计登记证书应当包括下列各项： （一）布图设计权利人的姓名或者名称和地址； （二）布图设计的名称； （三）布图设计在申请日之前已经投入商业利用的，其首次商业利用的时间； （四）布图设计的申请日及创作完成日； （五）布图设计的颁证日期； （六）布图设计的登记号； （七）国家知识产权局的印章及负责人签字。"},{"i":22,"n":"第二十二条","txt":"更正 国家知识产权局对布图设计公告中出现的错误，一经发现，应当及时更正，并对所作更正予以公告。"},{"i":23,"n":"第二十三条","txt":"复审和撤销机构 国家知识产权局专利复审委员会（以下简称专利复审委员会）负责对国家知识产权局驳回布图设计登记申请决定不服而提出的复审请求的审查，以及负责对布图设计专有权撤销案件的审查。"},{"i":24,"n":"第二十四条","txt":"复审的请求 向专利复审委员会请求复审的，应当提交复审请求书，说明理由，必要时还应当附具有关证据。复审请求书不符合条例第十九条有关规定的，专利复审委员会不予受理。 复审请求不符合规定格式的，复审请求人应当在专利复审委员会指定的期限内补正；期满未补正的，该复审请求视为未提出。"},{"i":25,"n":"第二十五条","txt":"复审程序中文件的修改 复审请求人在提出复审请求或者在对专利复审委员会的复审通知书作出答复时，可以修改布图设计申请文件；但是修改应当仅限于消除驳回决定或者复审通知书指出的缺陷。 修改的申请文件应当提交一式两份。"},{"i":26,"n":"第二十六条","txt":"复审决定 专利复审委员会进行审查后，认为布图设计登记申请的复审请求不符合条例或者本细则有关规定的，应当通知复审请求人，要求其在指定期限内陈述意见。期满未答复的，该复审请求视为撤回；经陈述意见或者进行修改后，专利复审委员会认为该申请仍不符条例和本细则有关规定的，应当作出维持原驳回决定的复审决定。 专利复审委员会进行复审后，认为原驳回决定不符合条例和本细则有关规定的，或者认为经过修改的申请文件消除了原驳回决定指出的缺陷的，应当撤销原驳回决定，通知原审查部门对该申请予以登记和公告。 专利复审委员会的复审决定，应当写明复审决定的理由，并通知布图设计登记申请人。"},{"i":27,"n":"第二十七条","txt":"复审请求的撤回 复审请求人在专利复审委员会作出决定前，可以撤回其复审请求。 复审请求人在专利复审委员会作出决定前撤回其复审请求的，复审程序终止。"},{"i":28,"n":"第二十八条","txt":"复议请求 当事人对国家知识产权局作出的下列具体行政行为不服或者有争议的，可以向国家知识产权局行政复议部门申请复议： （一）不予受理布图设计申请的； （二）将布图设计申请视为撤回的； （三）不允许恢复有关权利的请求的； （四）其他侵犯当事人合法权益的具体行政行为。"},{"i":29,"n":"第二十九条","txt":"撤销程序 布图设计登记公告后，发现登记的布图设计专有权不符合集成电路布图设计保护条例第二条第（一）、（二）项、第三条、第四条、第五条、第十二条或者第十七条规定的，由专利复审委员会撤销该布图设计专有权。 撤销布图设计专有权的，应当首先通知该布图设计权利人，要求其在指定期限内陈述意见。期满未答复的，不影响专利复审委员会作出撤销布图设计专有权的决定。 专利复审委员会撤销布图设计专有权的决定应当写明所依据的理由，并通知该布图设计权利人。"},{"i":30,"n":"第三十条","txt":"撤销决定的公告 对专利复审委员会撤销布图设计专有权的决定未在规定期限内向人民法院起诉，或者在人民法院维持专利复审委员会撤销布图设计专有权决定的判决生效后，国家知识产权局应当将撤销该布图设计专有权的决定在国家知识产权局互联网站和中国知识产权报上公告。 被撤销的布图设计专有权视为自始即不存在。"},{"i":31,"n":"第三十一条","txt":"布图设计专有权的放弃 布图设计权利人在其布图设计专有权保护期届满之前，可以向国家知识产权局提交书面声明放弃该专有权。 布图设计专有权已许可他人实施或者已经出质的，该布图设计专有权的放弃应当征得被许可人或质权人的同意。 布图设计专有权的放弃应当由国家知识产权局登记和公告。"},{"i":32,"n":"第三十二条","txt":"国家知识产权局受理侵权纠纷案件的条件 根据条例第三十一条的规定请求国家知识产权局处理布图设计专有权侵权纠纷的，应当符合下列条件： （一）该布图设计已登记、公告； （二）请求人是布图设计权利人或者与该侵权纠纷有直接利害关系的单位或者个人； （三）有明确的被请求人； （四）有明确的请求事项和具体的事实、理由； （五）当事人任何一方均未就该侵权纠纷向人民法院起诉。"},{"i":33,"n":"第三十三条","txt":"有关程序的中止和恢复 当事人因布图设计申请权或者布图设计专有权的归属发生纠纷，已经向人民法院起诉的，可以请求国家知识产权局中止有关程序。 依照前款规定请求中止有关程序的，应当向国家知识产权局提交请求书，并附具人民法院的有关受理文件副本。 在人民法院作出的判决生效后，当事人应当向国家知识产权局办理恢复有关程序的手续。自请求中止之日起一年内，有关布图设计申请权或者布图设计专有权归属的纠纷未能结案，需要继续中止有关程序的，请求人应当在该期限内请求延长中止。期满未请求延长的，国家知识产权局自行恢复有关程序。 人民法院在审理民事案件中裁定对布图设计专有权采取保全措施的，国家知识产权局在协助执行时中止被保全的布图设计专有权的有关程序。保全期限届满，人民法院没有裁定继续采取保全措施的，国家知识产权局自行恢复有关程序。"},{"i":34,"n":"第三十四条","txt":"应缴纳的费用 向国家知识产权局申请布图设计登记和办理其他手续时，应当缴纳下列费用： （一）布图设计登记费； （二）著录事项变更手续费、延长期限请求费、恢复权利请求费； （三）复审请求费； （四）非自愿许可许可请求费、非自愿许可使用费的裁决请求费。 前款所列各种费用的数额，由国务院价格管理部门会同国家知识产权局另行规定。"},{"i":35,"n":"第三十五条","txt":"缴费手续 条例和本细则规定的各种费用，可以直接向国家知识产权局缴纳，也可以通过邮局或者银行汇付，或者以国家知识产权局规定的其他方式缴纳。 通过邮局或者银行汇付的，应当在送交国家知识产权局的汇单上至少写明正确的申请号以及缴纳的费用名称。不符合本款规定的，视为未办理缴费手续。 直接向国家知识产权局缴纳费用的，以缴纳当日为缴费日；以邮局汇付方式缴纳费用的，以邮局汇出的邮戳日为缴费日；以银行汇付方式缴纳费用的，以银行实际汇出日为缴费日。但是自汇出日至国家知识产权局收到日超过１５日的，除邮局或者银行出具证明外，以国家知识产权局收到日为缴费日。 多缴、重缴、错缴布图设计登记费用的，当事人可以向国家知识产权局提出退款请求，但是该请求应当自缴费日起一年内提出。"},{"i":36,"n":"第三十六条","txt":"缴费期限 申请人应当在收到受理通知书后２个月内缴纳布图设计登记费；期满未缴纳或者未缴足的，其申请视为撤回。 当事人请求恢复权利或者复审的，应当在条例及本细则规定的相关期限内缴纳费用；期满未缴纳或者未缴足的，视为未提出请求。 著录事项变更手续费、非自愿许可请求费、非自愿许可使用费的裁决请求费应当自提出请求之日起１个月内缴纳；延长期限请求费应当在相应期限届满前缴纳；期满未缴纳或者未缴足的，视为未提出请求。"},{"i":37,"n":"第三十七条","txt":"布图设计登记簿 国家知识产权局设置布图设计登记簿，登记下列事项： （一）布图设计权利人的姓名或者名称、国籍和地址及其变更； （二）布图设计的登记； （三）布图设计专有权的转移和继承； （四）布图设计专有权的放弃； （五）布图设计专有权的质押、保全及其解除； （六）布图设计专有权的撤销； （七）布图设计专有权的终止； （八）布图设计专有权的恢复； （九）布图设计专有权实施的非自愿许可。"},{"i":38,"n":"第三十八条","txt":"布图设计公告 国家知识产权局定期在国家知识产权局互联网站和中国知识产权报上登载布图设计登记公报，公布或者公告下列内容： （一）布图设计登记簿记载的著录事项； （二）对地址不明的当事人的通知； （三）国家知识产权局作出的更正； （四）其他有关事项。"},{"i":39,"n":"第三十九条","txt":"公众查阅和复制 布图设计登记公告后，公众可以请求查阅该布图设计登记簿或者请求国家知识产权局提供该登记簿的副本。公众也可以请求查阅该布图设计的复制件或者图样的纸件。 本细则第十四条所述的电子版本的复制件或者图样，除侵权诉讼或者行政处理程序需要外，任何人不得查阅或者复制。"},{"i":40,"n":"第四十条","txt":"失效案卷的处理 布图设计登记申请被撤回、视为撤回或者驳回的，以及布图设计专有权被声明放弃、撤销或者终止的，与该布图设计申请或者布图设计专有权有关的案卷，自该申请失效或者该专有权失效之日起满３年后不予保存。"},{"i":41,"n":"第四十一条","txt":"文件的邮寄 向国家知识产权局邮寄有关申请或者布图设计专有权的文件，应当使用挂号信函，一件信函应当只包含同一申请文件。电子版本的复制件或者图样和集成电路样品的邮寄方式应当保证其在邮寄过程中不受损坏。"},{"i":42,"n":"第四十二条","txt":"本细则的解释 本细则由国家知识产权局负责解释。"},{"i":43,"n":"第四十三条","txt":"本细则的实施日期 本细则自２００１年１０月１日起施行。"}],"jichengdianlubutushejixingzhengzhifabanfa-2":[{"i":1,"n":"第一条","txt":"为了保护集成电路布图设计（以下简称布图设计）专有权，维护社会主义市场经济秩序，根据《集成电路布图设计保护条例》（以下简称条例）以及有关法律法规制定本办法。"},{"i":2,"n":"第二条","txt":"条例第三十一条所称国务院知识产权行政部门是指国家知识产权局。 国家知识产权局设立集成电路布图设计行政执法委员会（以下简称行政执法委员会），负责处理侵犯布图设计专有权的纠纷，调解侵犯布图设计专有权的赔偿数额。 各省、自治区、直辖市的知识产权局应当协助、配合国家知识产权局开展集成电路布图设计行政执法工作。"},{"i":3,"n":"第三条","txt":"行政执法委员会处理侵犯布图设计专有权的纠纷应当以事实为依据、以法律为准绳，遵循公正、及时的原则。 行政执法委员会调解侵犯布图设计专有权的赔偿数额应当按照法律规定，在查明事实、分清是非的基础上，促使当事人相互谅解，达成协议。"},{"i":4,"n":"第四条","txt":"请求行政执法委员会处理布图设计专有权侵权纠纷的，应当符合下列条件： （一）该布图设计已登记、公告； （二）请求人是布图设计专有权的权利人或者与该侵权纠纷有直接利害关系的单位或者个人； （三）有明确的被请求人； （四）有明确的请求事项和具体事实、理由； （五）当事人任何一方均未就该侵权纠纷向人民法院起诉。"},{"i":5,"n":"第五条","txt":"请求人提出请求，应当向行政执法委员会提交请求书以及所涉及的布图设计登记证书副本。请求人应当按照被请求人的数量提供相应数量的请求书副本。"},{"i":6,"n":"第六条","txt":"请求书应当记载以下内容： （一）请求人的姓名或者名称、地址，法定代表人或者主要负责人的姓名、职务，委托代理人的，代理人的姓名和代理机构的名称、地址； （二）被请求人的姓名或者名称、地址； （三）请求处理的事项和具体事实、理由。 有关证据和证明材料可以请求书附件的形式提交。 请求书应当由请求人签名或盖章。"},{"i":7,"n":"第七条","txt":"请求人应当提供证据，证明被请求人采用的布图设计与受保护的布图设计全部相同或者与受保护的布图设计中任何具有独创性的部分相同。 受保护的布图设计尚未投入商业利用的，请求人应当提供证据，证明被请求人有获知该布图设计的实际可能性。"},{"i":8,"n":"第八条","txt":"请求不符合本办法第五条规定的，行政执法委员会应当在收到请求之日起的７日内通知请求人不予受理。 请求不符合本办法第六条、第七条、第八条规定的，行政执法委员会应当在收到请求之日起的７日内通知请求人在指定期限内予以补正。逾期未补正或者经补正仍不符合规定的，请求被视为未提出。 请求符合本办法第五条、第六条、第七条、第八条规定的，行政执法委员会应当及时立案并通知请求人，同时，应指定３名或３名以上单数承办人员组成合议组处理该侵权纠纷。"},{"i":9,"n":"第九条","txt":"立案后，行政执法委员会应当及时将请求书及其附件的副本以寄交、直接送交或者其他方式送达被请求人，要求其在收到请求书副本之日起１５日内提交答辩书一式２份。被请求人逾期不提交答辩书的，不影响行政执法委员会进行处理。 被请求人提交答辩书的，行政执法委员会应当在收到答辩书之日起的７日内将答辩书副本以寄交、直接送交或者其他方式送达请求人。"},{"i":10,"n":"第十条","txt":"侵犯布图设计专有权纠纷涉及复杂技术问题，需要进行鉴定的，行政执法委员会可以委托有关单位进行专业技术鉴定。鉴定意见或者结论需经当事人质证方能作为定案的依据。 鉴定费用由当事人承担。"},{"i":11,"n":"第十一条","txt":"在侵犯布图设计专用权纠纷的处理过程中，专利复审委员会对该布图设计专用权启动撤销程序的，行政执法委员会可以根据情况需要决定是否中止处理程序。"},{"i":12,"n":"第十二条","txt":"行政执法委员会处理侵犯布图设计设计专有权的纠纷，可以根据案情需要决定是否进行口头审理。行政执法委员会决定进行口头审理的，应当至少在口头审理３日前让当事人得知进行口头审理的时间和地点。无正当理由拒不参加或者未经允许中途退出口头审理的，对请求人按撤回请求处理，对被请求人按缺席处理。"},{"i":13,"n":"第十三条","txt":"行政执法委员会举行口头审理的，应当将口头审理的参加人和审理要点记入笔录，经核对无误后，由案件承办人员和参加人签名或盖章。"},{"i":14,"n":"第十四条","txt":"除当事人达成调解、和解协议，或者请求人撤回请求之外，行政执法委员会处理侵犯布图设计专用权的纠纷应当作出处理决定书，写明以下内容： （一）当事人的名称或姓名、地址； （二）当事人陈述的事实和理由； （三）认定侵权行为是否成立的理由和依据； （四）处理决定，认定侵权行为成立的，应当明确写明责令被请求人立即停止的侵权行为的类型、对象和范围；认定侵权行为不成立的，应当驳回请求人的请求； （五）不服处理决定向人民法院提起行政诉讼的途径和期限。 处理决定书应当由案件承办人员署名，加盖行政执法委员会的业务专用章。"},{"i":15,"n":"第十五条","txt":"对行政执法委员会作出的处理决定不服，向人民法院提起行政诉讼的，由行政执法委员会主任委托合议组出庭应诉。"},{"i":16,"n":"第十六条","txt":"在行政执法委员会或者人民法院作出认定侵权成立的处理决定或者判决之后，被请求人就同一布图设计专用权再次作出相同类型的侵权行为，布图设计专有权的权利人或者利害关系人请求处理的，行政执法委员会可以直接作出责令立即停止侵权行为的处理决定。"},{"i":17,"n":"第十七条","txt":"当事人请求行政执法委员会就犯布图设计专有权的赔偿数额进行调解的，应当提交请求书。 请求书应当记载以下内容： （一）请求人的姓名或者名称、地址、法定代表人或主要负责人的姓名、职务； （二）被请求人的姓名或名称、地址； （三）请求调解的具体事项和理由。"},{"i":18,"n":"第十八条","txt":"行政执法委员会收到请求书后，应当及时将请求书副本通过寄交、直接送交或者其他方式送达被请求人，要求其在收到请求书副本之日起的１５日内提交意见陈述书。"},{"i":19,"n":"第十九条","txt":"被请求人提交意见陈述书并同意进行调解的，行政执法委员会应当及时立案，并通知请求人和被请求人进行调解的时间和地点。 被请求人逾期未提交意见陈述书，或者在意见陈述书中表示不接受调解的，行政执法委员会不予立案，并通知请求人。"},{"i":20,"n":"第二十条","txt":"当事人经调解达成协议的，应当制作调解协议书，由双方当事人签名或者盖章，并交行政执法委员会备案；未达成协议的，行政执法委员会以撤销案件的方式结案，并通知双方当事人。"},{"i":21,"n":"第二十一条","txt":"行政执法委员会处理侵犯布图设计专用权的纠纷，可以根据案情需要，在处理过程中依职权调查收集有关证据。"},{"i":22,"n":"第二十二条","txt":"行政执法委员会调查收集证据可以采用拍照、摄像等方式进行现场勘验；查阅、复制与案件有关的合同、帐册等有关文件；询问当事人和证人。 行政执法委员会调查收集证据应当制作笔录。笔录应当由案件承办人员、被调查的单位或者个人签名或者盖章。被调查的单位或者个人拒绝签名或者盖章的，应当在笔录上注明。"},{"i":23,"n":"第二十三条","txt":"行政执法委员会调查收集证据可以采取抽样取证的方式，从涉嫌侵权的产品中抽取一部分作为样品。被抽取样品的数量应当以能够证明事实为限。 行政执法委员会进行抽样取证应当制作笔录，写明被抽取样品的名称、特征、数量。笔录应当由案件承办人员、被调查单位或个人签字或盖章。"},{"i":24,"n":"第二十四条","txt":"在证据可能灭失或者以后难以取得，又无法进行抽样取证的情况下，行政执法委员会可以进行登记保存，并在七日内作出决定。 经登记保存的证据，被调查的单位或个人不得销毁或转移。 行政执法委员会进行登记保存应当制作笔录，写明被登记保存证据的名称、特征、数量以及保存地点。笔录应当由案件承办人员、被调查的单位或个人签名或盖章。"},{"i":25,"n":"第二十五条","txt":"行政执法委员会调查收集证据、核实证据材料的，有关单位或者个人应当如实提供，协助调查。"},{"i":26,"n":"第二十六条","txt":"行政执法委员会调查收集证据、核实证据材料的，有关单位或个人应当如实提供，协助调查。 行政执法委员会委托有关省、自治区、直辖市人民政府的知识产权管理部门协助调查收集证据，应当提出明确的要求。接受委托的部门应当及时、认真地协助调查收集证据，并尽快回复。"},{"i":27,"n":"第二十七条","txt":"行政执法委员会认定侵权行为成立，作出处理决定书的，应当采取下列措施制止侵权行为： （一）被请求人复制受保护的布图设计的，责令其立即停止复制行为，没收、销毁复制的图样、掩膜、专用设备以及含有该布图设计的集成电路； （二）被请求人为商业目的进口、销售的，责令其立即停止进口、销售或者提供行为，没收、销毁有关图样、掩膜； （三）被请求人为商业目的进口、销售或者以其他方式提供含有受保护的布图设计的集成电路，并且知道或者有合理理由应当知道其中含有非法复制的布图设计的，责令其立即停止进口、销售或者提供行为，没收、销毁该集成电路； （四）被请求人为商业目的进口、销售或者以其他方式提供含有侵权集成电路的物品，并且知道或者有合理理由应当知道其中含有非法复制的布图设计的，责令其立即停止进口、销售或者提供行为，从尚未销售、提供的物品中拆除该集成电路，没收、销毁该集成电路；被请求人拒不拆除的，没收、销毁该物品；"},{"i":28,"n":"第二十八条","txt":"行政执法委员会作出认定侵权行为成立的处理决定后，被请求人向人民法院提起行政诉讼的，在诉讼期间不停止决定的执行。 被请求人对行政执法委员会作出的认定侵权行为成立的处理决定期满不起诉又不停止侵权行为的，国家知识产权局可以请求人民法院强制执行。"},{"i":29,"n":"第二十九条","txt":"本办法由国家知识产权局负责解释。"},{"i":30,"n":"第三十条","txt":"本办法自颁布之日起施行。"}],"jichengdianlubutushejixingzhengzhifabanfa":[{"i":1,"n":"第一条","txt":"为了保护集成电路布图设计（以下简称布图设计）专有权，维护社会主义市场经济秩序，根据《集成电路布图设计保护条例》（以下简称条例）以及有关法律法规制定本办法。"},{"i":2,"n":"第二条","txt":"条例第三十一条所称国务院知识产权行政部门是指国家知识产权局。 国家知识产权局设立集成电路布图设计行政执法委员会（以下简称行政执法委员会），负责处理侵犯布图设计专有权的纠纷，调解侵犯布图设计专有权的赔偿数额。 各省、自治区、直辖市的知识产权局应当协助、配合国家知识产权局开展集成电路布图设计行政执法工作。"},{"i":3,"n":"第三条","txt":"行政执法委员会处理侵犯布图设计专有权的纠纷应当以事实为依据、以法律为准绳，遵循公正、及时的原则。 行政执法委员会调解侵犯布图设计专有权的赔偿数额应当按照法律规定，在查明事实、分清是非的基础上，促使当事人相互谅解，达成协议。"},{"i":4,"n":"第四条","txt":"请求行政执法委员会处理布图设计专有权侵权纠纷的，应当符合下列条件： （一）该布图设计已登记、公告； （二）请求人是布图设计专有权的权利人或者与该侵权纠纷有直接利害关系的单位或者个人； （三）有明确的被请求人； （四）有明确的请求事项和具体事实、理由； （五）当事人任何一方均未就该侵权纠纷向人民法院起诉。"},{"i":5,"n":"第五条","txt":"请求人提出请求，应当向行政执法委员会提交请求书以及所涉及的布图设计登记证书副本。请求人应当按照被请求人的数量提供相应数量的请求书副本。"},{"i":6,"n":"第六条","txt":"请求书应当记载以下内容： （一）请求人的姓名或者名称、地址，法定代表人或者主要负责人的姓名、职务，委托代理人的，代理人的姓名和代理机构的名称、地址； （二）被请求人的姓名或者名称、地址； （三）请求处理的事项和具体事实、理由。 有关证据和证明材料可以请求书附件的形式提交。 请求书应当由请求人签名或盖章。"},{"i":7,"n":"第七条","txt":"请求人应当提供证据，证明被请求人采用的布图设计与受保护的布图设计全部相同或者与受保护的布图设计中任何具有独创性的部分相同。 受保护的布图设计尚未投入商业利用的，请求人应当提供证据，证明被请求人有获知该布图设计的实际可能性。"},{"i":8,"n":"第八条","txt":"请求不符合本办法第五条规定的，行政执法委员会应当在收到请求之日起的７日内通知请求人不予受理。 请求不符合本办法第六条、第七条、第八条规定的，行政执法委员会应当在收到请求之日起的７日内通知请求人在指定期限内予以补正。逾期未补正或者经补正仍不符合规定的，请求被视为未提出。 请求符合本办法第五条、第六条、第七条、第八条规定的，行政执法委员会应当及时立案并通知请求人，同时，应指定３名或３名以上单数承办人员组成合议组处理该侵权纠纷。"},{"i":9,"n":"第九条","txt":"立案后，行政执法委员会应当及时将请求书及其附件的副本以寄交、直接送交或者其他方式送达被请求人，要求其在收到请求书副本之日起１５日内提交答辩书一式２份。被请求人逾期不提交答辩书的，不影响行政执法委员会进行处理。 被请求人提交答辩书的，行政执法委员会应当在收到答辩书之日起的７日内将答辩书副本以寄交、直接送交或者其他方式送达请求人。"},{"i":10,"n":"第十条","txt":"侵犯布图设计专有权纠纷涉及复杂技术问题，需要进行鉴定的，行政执法委员会可以委托有关单位进行专业技术鉴定。鉴定意见或者结论需经当事人质证方能作为定案的依据。 鉴定费用由当事人承担。"},{"i":11,"n":"第十一条","txt":"在侵犯布图设计专用权纠纷的处理过程中，专利复审委员会对该布图设计专用权启动撤销程序的，行政执法委员会可以根据情况需要决定是否中止处理程序。"},{"i":12,"n":"第十二条","txt":"行政执法委员会处理侵犯布图设计设计专有权的纠纷，可以根据案情需要决定是否进行口头审理。行政执法委员会决定进行口头审理的，应当至少在口头审理３日前让当事人得知进行口头审理的时间和地点。无正当理由拒不参加或者未经允许中途退出口头审理的，对请求人按撤回请求处理，对被请求人按缺席处理。"},{"i":13,"n":"第十三条","txt":"行政执法委员会举行口头审理的，应当将口头审理的参加人和审理要点记入笔录，经核对无误后，由案件承办人员和参加人签名或盖章。"},{"i":14,"n":"第十四条","txt":"除当事人达成调解、和解协议，或者请求人撤回请求之外，行政执法委员会处理侵犯布图设计专用权的纠纷应当作出处理决定书，写明以下内容： （一）当事人的名称或姓名、地址； （二）当事人陈述的事实和理由； （三）认定侵权行为是否成立的理由和依据； （四）处理决定，认定侵权行为成立的，应当明确写明责令被请求人立即停止的侵权行为的类型、对象和范围；认定侵权行为不成立的，应当驳回请求人的请求； （五）不服处理决定向人民法院提起行政诉讼的途径和期限。 处理决定书应当由案件承办人员署名，加盖行政执法委员会的业务专用章。"},{"i":15,"n":"第十五条","txt":"对行政执法委员会作出的处理决定不服，向人民法院提起行政诉讼的，由行政执法委员会主任委托合议组出庭应诉。"},{"i":16,"n":"第十六条","txt":"在行政执法委员会或者人民法院作出认定侵权成立的处理决定或者判决之后，被请求人就同一布图设计专用权再次作出相同类型的侵权行为，布图设计专有权的权利人或者利害关系人请求处理的，行政执法委员会可以直接作出责令立即停止侵权行为的处理决定。"},{"i":17,"n":"第十七条","txt":"当事人请求行政执法委员会就犯布图设计专有权的赔偿数额进行调解的，应当提交请求书。 请求书应当记载以下内容： （一）请求人的姓名或者名称、地址、法定代表人或主要负责人的姓名、职务； （二）被请求人的姓名或名称、地址； （三）请求调解的具体事项和理由。"},{"i":18,"n":"第十八条","txt":"行政执法委员会收到请求书后，应当及时将请求书副本通过寄交、直接送交或者其他方式送达被请求人，要求其在收到请求书副本之日起的１５日内提交意见陈述书。"},{"i":19,"n":"第十九条","txt":"被请求人提交意见陈述书并同意进行调解的，行政执法委员会应当及时立案，并通知请求人和被请求人进行调解的时间和地点。 被请求人逾期未提交意见陈述书，或者在意见陈述书中表示不接受调解的，行政执法委员会不予立案，并通知请求人。"},{"i":20,"n":"第二十条","txt":"当事人经调解达成协议的，应当制作调解协议书，由双方当事人签名或者盖章，并交行政执法委员会备案；未达成协议的，行政执法委员会以撤销案件的方式结案，并通知双方当事人。"},{"i":21,"n":"第二十一条","txt":"行政执法委员会处理侵犯布图设计专用权的纠纷，可以根据案情需要，在处理过程中依职权调查收集有关证据。"},{"i":22,"n":"第二十二条","txt":"行政执法委员会调查收集证据可以采用拍照、摄像等方式进行现场勘验；查阅、复制与案件有关的合同、帐册等有关文件；询问当事人和证人。 行政执法委员会调查收集证据应当制作笔录。笔录应当由案件承办人员、被调查的单位或者个人签名或者盖章。被调查的单位或者个人拒绝签名或者盖章的，应当在笔录上注明。"},{"i":23,"n":"第二十三条","txt":"行政执法委员会调查收集证据可以采取抽样取证的方式，从涉嫌侵权的产品中抽取一部分作为样品。被抽取样品的数量应当以能够证明事实为限。 行政执法委员会进行抽样取证应当制作笔录，写明被抽取样品的名称、特征、数量。笔录应当由案件承办人员、被调查单位或个人签字或盖章。"},{"i":24,"n":"第二十四条","txt":"在证据可能灭失或者以后难以取得，又无法进行抽样取证的情况下，行政执法委员会可以进行登记保存，并在七日内作出决定。 经登记保存的证据，被调查的单位或个人不得销毁或转移。 行政执法委员会进行登记保存应当制作笔录，写明被登记保存证据的名称、特征、数量以及保存地点。笔录应当由案件承办人员、被调查的单位或个人签名或盖章。"},{"i":25,"n":"第二十五条","txt":"行政执法委员会调查收集证据、核实证据材料的，有关单位或者个人应当如实提供，协助调查。"},{"i":26,"n":"第二十六条","txt":"行政执法委员会调查收集证据、核实证据材料的，有关单位或个人应当如实提供，协助调查。 行政执法委员会委托有关省、自治区、直辖市人民政府的知识产权管理部门协助调查收集证据，应当提出明确的要求。接受委托的部门应当及时、认真地协助调查收集证据，并尽快回复。"},{"i":27,"n":"第二十七条","txt":"行政执法委员会认定侵权行为成立，作出处理决定书的，应当采取下列措施制止侵权行为： （一）被请求人复制受保护的布图设计的，责令其立即停止复制行为，没收、销毁复制的图样、掩膜、专用设备以及含有该布图设计的集成电路； （二）被请求人为商业目的进口、销售的，责令其立即停止进口、销售或者提供行为，没收、销毁有关图样、掩膜； （三）被请求人为商业目的进口、销售或者以其他方式提供含有受保护的布图设计的集成电路，并且知道或者有合理理由应当知道其中含有非法复制的布图设计的，责令其立即停止进口、销售或者提供行为，没收、销毁该集成电路； （四）被请求人为商业目的进口、销售或者以其他方式提供含有侵权集成电路的物品，并且知道或者有合理理由应当知道其中含有非法复制的布图设计的，责令其立即停止进口、销售或者提供行为，从尚未销售、提供的物品中拆除该集成电路，没收、销毁该集成电路；被请求人拒不拆除的，没收、销毁该物品；"},{"i":28,"n":"第二十八条","txt":"行政执法委员会作出认定侵权行为成立的处理决定后，被请求人向人民法院提起行政诉讼的，在诉讼期间不停止决定的执行。 被请求人对行政执法委员会作出的认定侵权行为成立的处理决定期满不起诉又不停止侵权行为的，国家知识产权局可以请求人民法院强制执行。"},{"i":29,"n":"第二十九条","txt":"本办法由国家知识产权局负责解释。"},{"i":30,"n":"第三十条","txt":"本办法自颁布之日起施行。"}],"chimingshangbiaorendinghebaohuguiding-2":[{"i":1,"n":"第一条","txt":"为规范驰名商标认定工作，保护驰名商标持有人的合法权益，根据《中华人民共和国商标法》（以下简称商标法）、《中华人民共和国商标法实施条例》（以下简称实施条例），制定本规定。"},{"i":2,"n":"第二条","txt":"驰名商标是在中国为相关公众所熟知的商标。 相关公众包括与使用商标所标示的某类商品或者服务有关的消费者，生产前述商品或者提供服务的其他经营者以及经销渠道中所涉及的销售者和相关人员等。"},{"i":3,"n":"第三条","txt":"商标局、商标评审委员会根据当事人请求和审查、处理案件的需要，负责在商标注册审查、商标争议处理和工商行政管理部门查处商标违法案件过程中认定和保护驰名商标。"},{"i":4,"n":"第四条","txt":"驰名商标认定遵循个案认定、被动保护的原则。"},{"i":5,"n":"第五条","txt":"当事人依照商标法第三十三条规定向商标局提出异议，并依照商标法第十三条规定请求驰名商标保护的，可以向商标局提出驰名商标保护的书面请求并提交其商标构成驰名商标的证据材料。"},{"i":6,"n":"第六条","txt":"当事人在商标不予注册复审案件和请求无效宣告案件中，依照商标法第十三条规定请求驰名商标保护的，可以向商标评审委员会提出驰名商标保护的书面请求并提交其商标构成驰名商标的证据材料。"},{"i":7,"n":"第七条","txt":"涉及驰名商标保护的商标违法案件由市（地、州）级以上工商行政管理部门管辖。当事人请求工商行政管理部门查处商标违法行为，并依照商标法第十三条规定请求驰名商标保护的，可以向违法行为发生地的市（地、州）级以上工商行政管理部门进行投诉，并提出驰名商标保护的书面请求，提交证明其商标构成驰名商标的证据材料。"},{"i":8,"n":"第八条","txt":"当事人请求驰名商标保护应当遵循诚实信用原则，并对事实及所提交的证据材料的真实性负责。"},{"i":9,"n":"第九条","txt":"以下材料可以作为证明符合商标法第十四条第一款规定的证据材料： （一）证明相关公众对该商标知晓程度的材料。 （二）证明该商标使用持续时间的材料，如该商标使用、注册的历史和范围的材料。该商标为未注册商标的，应当提供证明其使用持续时间不少于五年的材料。该商标为注册商标的，应当提供证明其注册时间不少于三年或者持续使用时间不少于五年的材料。 （三）证明该商标的任何宣传工作的持续时间、程度和地理范围的材料，如近三年广告宣传和促销活动的方式、地域范围、宣传媒体的种类以及广告投放量等材料。 （四）证明该商标曾在中国或者其他国家和地区作为驰名商标受保护的材料。 （五）证明该商标驰名的其他证据材料，如使用该商标的主要商品在近三年的销售收入、市场占有率、净利润、纳税额、销售区域等材料。 前款所称“三年”、“五年”，是指被提出异议的商标注册申请日期、被提出无效宣告请求的商标注册申请日期之前的三年、五年，以及在"},{"i":10,"n":"第十条","txt":"当事人依照本规定第五条、第六条规定提出驰名商标保护请求的，商标局、商标评审委员会应当在商标法第三十五条、第三十七条、第四十五条规定的期限内及时作出处理。"},{"i":11,"n":"第十一条","txt":"当事人依照本规定第七条规定请求工商行政管理部门查处商标违法行为的，工商行政管理部门应当对投诉材料予以核查，依照《工商行政管理机关行政处罚程序规定》的有关规定决定是否立案。决定立案的，工商行政管理部门应当对当事人提交的驰名商标保护请求及相关证据材料是否符合商标法第十三条、第十四条、实施条例第三条和本规定第九条规定进行初步核实和审查。经初步核查符合规定的，应当自立案之日起三十日内将驰名商标认定请示、案件材料副本一并报送上级工商行政管理部门。经审查不符合规定的，应当依照《工商行政管理机关行政处罚程序规定》的规定及时作出处理。"},{"i":12,"n":"第十二条","txt":"省（自治区、直辖市）工商行政管理部门应当对本辖区内市（地、州）级工商行政管理部门报送的驰名商标认定相关材料是否符合商标法第十三条、第十四条、实施条例第三条和本规定第九条规定进行核实和审查。经核查符合规定的，应当自收到驰名商标认定相关材料之日起三十日内，将驰名商标认定请示、案件材料副本一并报送商标局。经审查不符合规定的，应当将有关材料退回原立案机关，由其依照《工商行政管理机关行政处罚程序规定》的规定及时作出处理。"},{"i":13,"n":"第十三条","txt":"商标局、商标评审委员会在认定驰名商标时，应当综合考虑商标法第十四条第一款和本规定第九条所列各项因素，但不以满足全部因素为前提。 商标局、商标评审委员会在认定驰名商标时，需要地方工商行政管理部门核实有关情况的，相关地方工商行政管理部门应当予以协助。"},{"i":14,"n":"第十四条","txt":"商标局经对省（自治区、直辖市）工商行政管理部门报送的驰名商标认定相关材料进行审查，认定构成驰名商标的，应当向报送请示的省（自治区、直辖市）工商行政管理部门作出批复。 立案的工商行政管理部门应当自商标局作出认定批复后六十日内依法予以处理，并将行政处罚决定书抄报所在省（自治区、直辖市）工商行政管理部门。省（自治区、直辖市）工商行政管理部门应当自收到抄报的行政处罚决定书之日起三十日内将案件处理情况及行政处罚决定书副本报送商标局。"},{"i":15,"n":"第十五条","txt":"各级工商行政管理部门在商标注册和管理工作中应当加强对驰名商标的保护，维护权利人和消费者合法权益。商标违法行为涉嫌犯罪的，应当将案件及时移送司法机关。"},{"i":16,"n":"第十六条","txt":"商标注册审查、商标争议处理和工商行政管理部门查处商标违法案件过程中，当事人依照商标法第十三条规定请求驰名商标保护时，可以提供该商标曾在我国作为驰名商标受保护的记录。 当事人请求驰名商标保护的范围与已被作为驰名商标予以保护的范围基本相同，且对方当事人对该商标驰名无异议，或者虽有异议，但异议理由和提供的证据明显不足以支持该异议的，商标局、商标评审委员会、商标违法案件立案部门可以根据该保护记录，结合相关证据，给予该商标驰名商标保护。"},{"i":17,"n":"第十七条","txt":"在商标违法案件中，当事人通过弄虚作假或者提供虚假证据材料等不正当手段骗取驰名商标保护的，由商标局撤销对涉案商标已作出的认定，并通知报送驰名商标认定请示的省（自治区、直辖市）工商行政管理部门。"},{"i":18,"n":"第十八条","txt":"地方工商行政管理部门违反本规定第十一条、第十二条规定未履行对驰名商标认定相关材料进行核实和审查职责，或者违反本规定第十三条第二款规定未予以协助或者未履行核实职责，或者违反本规定第十四条第二款规定逾期未对商标违法案件作出处理或者逾期未报送处理情况的，由上一级工商行政管理部门予以通报，并责令其整改。"},{"i":19,"n":"第十九条","txt":"各级工商行政管理部门应当建立健全驰名商标认定工作监督检查制度。"},{"i":20,"n":"第二十条","txt":"参与驰名商标认定与保护相关工作的人员，玩忽职守、滥用职权、徇私舞弊，违法办理驰名商标认定有关事项，收受当事人财物，牟取不正当利益的，依照有关规定予以处理。"},{"i":21,"n":"第二十一条","txt":"本规定自公布之日起30日后施行。2003年4月17日国家工商行政管理总局公布的《驰名商标认定和保护规定》同时废止。"}]};
